    "custody", "custodian", "settlement", "liquidity", "off-ramp", "on-ramp",
    # Español / portugués frecuente en resúmenes y fuentes reconstruidas
    "colabora", "colaboracion", "colaboración", "asociacion", "asociación", "alianza",
