def _is_radar_engine_node(entity: Any) -> bool:
    return _canonical_entity_name(entity) in RADAR_ENGINE_NODES

def _is_radar_observation_node(entity: Any) -> bool:
    return _canonical_entity_name(entity) in RADAR_OBSERVATION_NODES

def _domain_matches(domain: str, suffixes: Tuple[str, ...]) -> bool:
    d = str(domain or "").lower().replace("www.", "")
    return any(d == s or d.endswith("." + s) or d.endswith(s) for s in suffixes)

def _source_tier(url: Any) -> str:
    d = _proof_domain(str(url or ""))
    if not d:
        return "none"
    if _domain_matches(d, PRIMARY_SOURCE_DOMAINS) or any(h in str(url).lower() for h in _PRIMARY_DOC_HOST_HINTS):
        return "primary"
    if _domain_matches(d, MAJOR_NEWS_DOMAINS):
        return "major_news"
    if _domain_matches(d, WEAK_SOURCE_DOMAINS):
        return "weak"
    return "secondary"

def _claim_has_relation_language(text: Any) -> bool:
    t = str(text or "").lower()
    nt = _norm_key(t)
    return any(v in t or v in nt for v in RELATION_VERBS)

def _proof_quality_multiplier(proof: Dict[str, Any], node_a: Any = "", node_b: Any = "") -> float:
    if not isinstance(proof, dict):
        return 0.0
    ptype = str(proof.get("type", "") or "").strip().lower()
    if proof.get("onchain"):
        return 1.0 if ptype in PAIR_ONCHAIN_TYPES else 0.0
    if ptype in {"social_mention", "ai_inference", "sin_wallet"}:
        return 0.0
    url = _extract_url_from_any(proof)
    tier = _source_tier(url)
    blob = _proof_text_blob(proof)
    # Una fuente que solo menciona dos nombres, sin verbo/relación, no prueba una conexión.
    if not _claim_has_relation_language(blob):
        return 0.0
    if tier == "primary":
        return 1.0
    if tier == "major_news":
        return 0.62
    if tier == "secondary":
        return 0.42
    if tier == "weak":
        return 0.22
    return 0.0

def _cap_score_by_source_mix(score: float, proofs: List[Dict[str, Any]]) -> float:
    if not proofs:
        return 0.0
    if any(p.get("onchain") and str(p.get("type", "")).lower() in PAIR_ONCHAIN_TYPES for p in proofs):
        return min(float(score), 0.97)
    tiers = [_source_tier(_extract_url_from_any(p)) for p in proofs if p.get("internet")]
    has_primary = any(t == "primary" for t in tiers)
    has_major = any(t == "major_news" for t in tiers)
    independent_domains = {_proof_domain(_extract_url_from_any(p)) for p in proofs if p.get("internet") and _proof_domain(_extract_url_from_any(p))}
    if has_primary:
        return min(float(score), 0.92)
    if has_major and len(independent_domains) >= 2:
        return min(float(score), 0.62)
    if has_major:
        return min(float(score), 0.55)
    if len(independent_domains) >= 2:
        return min(float(score), 0.42)
    return min(float(score), 0.32)


def _is_core_ripple_node(entity: Any) -> bool:
    c = _canonical_entity_name(entity)
    return c in {
        "Ripple Payments", "XRPL", "RLUSD", "DEX/AMM", "Permissioned DEX",
        "Custody/Metaco", "Treasury", "Rail", "Hidden Road / Prime",
        "Standard Custody", "Ripple Escrow",
    }


def _proof_relevant_to_pair(proof: Dict[str, Any], node_a: str, node_b: str) -> bool:
    """
    Filtro duro de relevancia A↔B. Una fuente solo vale si demuestra la relación,
    no si simplemente contiene palabras que encajan con la narrativa.
    """
    if not isinstance(proof, dict):
        return False

    # Los motores internos del radar no son entidades externas verificables.
    # Ejemplo bloqueado: BIS ↔ Topology Engine como “conexión”.
    if _is_radar_engine_node(node_a) or _is_radar_engine_node(node_b):
        return False

    ptype = str(proof.get("type", "") or "").strip().lower()

    # On-chain solo cuenta si es evidencia de PAR. Wallet activa/ofertas genéricas
    # son evidencia del nodo, no de la conexión A↔B.
    if proof.get("onchain"):
        return ptype in PAIR_ONCHAIN_TYPES

    if not proof.get("internet"):
        return False
    url = _extract_url_from_any(proof)
    if not url.startswith("http"):
        return False
    if ptype not in EVIDENCE_SCORES or ptype in {"social_mention", "ai_inference", "sin_wallet"}:
        return False
    if _proof_quality_multiplier(proof, node_a, node_b) <= 0:
        return False

    blob = _proof_text_blob(proof)
    domain = _proof_domain(url)
    blob_plus = f"{blob} {domain}"
    mentions_a = _blob_mentions_any(blob_plus, _entity_search_terms(node_a))
    mentions_b = _blob_mentions_any(blob_plus, _entity_search_terms(node_b))

    official_ripple_domain = domain.endswith("ripple.com") or domain.endswith("xrpl.org")
    if official_ripple_domain and (_is_core_ripple_node(node_a) or _is_core_ripple_node(node_b)):
        # Si la fuente es Ripple/XRPL y el otro lado es externo, debe aparecer el externo.
        if _is_core_ripple_node(node_a) and _is_core_ripple_node(node_b):
            return mentions_a and mentions_b
        if _is_core_ripple_node(node_a):
            return mentions_b
        if _is_core_ripple_node(node_b):
            return mentions_a

    return bool(mentions_a and mentions_b)

def _dedupe_and_filter_proofs(node_a: str, node_b: str, proofs: Any, max_items: int = 3) -> List[Dict[str, Any]]:
    """Deduplica por URL/historia y filtra fuentes que no demuestran A↔B."""
    if not isinstance(proofs, list):
        return []
    out: List[Dict[str, Any]] = []
    seen_urls: Set[str] = set()
    seen_stories: Set[str] = set()
    seen_labels: Set[str] = set()
    for raw in proofs:
        if not isinstance(raw, dict):
            continue
        p = dict(raw)
        if p.get("onchain"):
            # v113: wallet_activa/ofertas genéricas prueban existencia del nodo, no una relación A↔B.
            if str(p.get("type", "") or "").strip().lower() not in PAIR_ONCHAIN_TYPES:
                continue
            label_key = _norm_key(p.get("type", "") + " " + p.get("label", "") + " " + str(p.get("tx_hash", "")))[:180]
            if label_key in seen_labels:
                continue
            seen_labels.add(label_key)
            out.append(p)
            continue
        p["internet"] = bool(p.get("internet", True))
        url = _extract_url_from_any(p)
        canon = _canonical_source_url(url)
        if canon:
            p["url"] = canon
        if not _proof_relevant_to_pair(p, node_a, node_b):
            continue
        story = _source_story_key(canon)
        label_key = _norm_key(str(p.get("type", "")) + " " + str(p.get("label", "")) + " " + str(p.get("snippet", "")))[:220]
        if canon and canon in seen_urls:
            continue
        if story and story in seen_stories and len(story) > 8:
            continue
        if label_key and label_key in seen_labels:
            continue
        if canon:
            seen_urls.add(canon)
        if story:
            seen_stories.add(story)
        if label_key:
            seen_labels.add(label_key)
        out.append(p)
        if len([x for x in out if x.get("internet")]) >= max_items:
            # Mantener como máximo N pruebas internet; on-chain no se corta aquí.
            pass
    # Orden: on-chain > documentos/official > noticias.
    rank = {
        "tx_directa": 0, "odl_payment": 1, "trust_line": 2, "amm_pool": 3,
        "official_partner": 4, "regulatory_filing_pdf": 5, "contract_pdf": 6,
        "regulatory_filing": 7, "press_release": 8, "github_repo": 9,
        "news_major": 10, "job_posting": 11, "news_minor": 12, "wallet_activa": 13,
    }
    onchain = [p for p in out if p.get("onchain")]
    internet = sorted([p for p in out if p.get("internet")], key=lambda x: rank.get(str(x.get("type", "")), 99))[:max_items]
    return onchain + internet


def _register_dynamic_node(conn: sqlite3.Connection, name: str, layer: str, icon: str,
                           confidence: float, summary: str, source_url: str,
                           now: str) -> bool:
    """Inserta/actualiza un nodo descubierto sin duplicar alias.

    Devuelve True si el nodo se creó o si cambió algún campo que pueda afectar
    al mapa. En versiones anteriores solo devolvía True al crear; por eso una
    re-búsqueda podía actualizar evidencia/capa en SQLite sin provocar refresco
    visual de los mapas.
    """
    cname = _canonical_display_node(name)
    # Si el nombre canónico resuelve a un nodo estático existente, no crear duplicado dinámico.
    # Ejemplo: GTreasury/Gtresaury/G Treasury se absorbe dentro de Treasury.
    if cname in NODES or _canonical_target_node(cname, set(NODES.keys())) in NODES:
        return False
    # v124: clasificar con nombre + resumen + fuentes, no solo con el nombre.
    # Si la IA trae una categoría nueva útil, se conserva; si trae algo genérico,
    # el router autónomo intenta crear una categoría semántica estable.
    layer = _safe_dynamic_layer_name(layer)
    auto_layer, auto_icon, _auto_reason = _autonomous_category_from_context(cname, summary, source_url, layer)
    inferred_layer, inferred_icon = _infer_layer_icon_from_name(cname, layer, icon or "🔎")
    if _should_force_inferred_layer(cname, layer, inferred_layer) and inferred_layer in ZONE_POS:
        layer = inferred_layer
        if not icon or icon in {"?", "🔎", "•"} or str(layer) in {"Stablecoins", "CBDC"}:
            icon = inferred_icon
    elif auto_layer and (_layer_is_generic_for_dynamic(layer) or layer == "Descubierto"):
        layer = auto_layer
        if not icon or icon in {"?", "🔎", "•"}:
            icon = auto_icon
    elif _layer_is_generic_for_dynamic(layer) and inferred_layer in ZONE_POS:
        layer = inferred_layer
        if not icon or icon in {"?", "🔎", "•"}:
            icon = inferred_icon
    node_id = hashlib.sha256(_norm_key(cname).encode()).hexdigest()[:12]
    new_values = (
        cname, layer, icon or "?", round(float(confidence or 0.0), 6),
        str(source_url or "")[:1200], str(summary or "")[:500],
    )
    before = conn.execute(
        "SELECT name, layer, icon, confidence, source_url, summary FROM dynamic_nodes WHERE node_id=?",
        (node_id,),
    ).fetchone()
    changed = before is None
    if before is not None:
        old_values = (
            str(before[0] or ""), str(before[1] or ""), str(before[2] or ""),
            round(float(before[3] or 0.0), 6), str(before[4] or "")[:1200], str(before[5] or "")[:500],
        )
        changed = old_values != new_values
    conn.execute("""
        INSERT OR REPLACE INTO dynamic_nodes
        (node_id, name, layer, icon, confidence, source_url, summary, added_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        node_id, *new_values, now,
    ))
    return bool(changed)


def _register_dynamic_route(conn: sqlite3.Connection, src: str, dst: str, kind: str,
                            signal_col: str, label: str, confidence: float,
                            evidence: str, source_urls: str, now: str) -> bool:
    """Inserta/actualiza una ruta descubierta con pruebas y sin duplicados.

    Devuelve True si la ruta es nueva o si cambió su tipo/confianza/evidencia.
    Esto alimenta el revisionado de mapas para que las 3 vistas se refresquen
    cuando una investigación actualiza datos guardados.
    """
    src = _canonical_display_node(src)
    dst = _canonical_display_node(dst)
    if not src or not dst or src == dst:
        return False
    route_kind = kind or "discovered"
    route_id = hashlib.sha256(f"{_norm_key(src)}>{_norm_key(dst)}>{_norm_key(route_kind)}".encode()).hexdigest()[:12]
    new_values = (
        src, dst, route_kind, signal_col or _route_signal_for_kind(route_kind),
        label or f"{src} -> {dst}", round(float(confidence or 0.0), 6),
        str(evidence or "")[:600], str(source_urls or "")[:1200],
    )
    before = conn.execute(
        "SELECT src, dst, kind, signal_col, label, confidence, evidence, source_urls FROM dynamic_routes WHERE route_id=?",
        (route_id,),
    ).fetchone()
    changed = before is None
    if before is not None:
        old_values = (
            str(before[0] or ""), str(before[1] or ""), str(before[2] or ""), str(before[3] or ""),
            str(before[4] or ""), round(float(before[5] or 0.0), 6),
            str(before[6] or "")[:600], str(before[7] or "")[:1200],
        )
        changed = old_values != new_values
    conn.execute("""
        INSERT OR REPLACE INTO dynamic_routes
        (route_id, src, dst, kind, signal_col, label, confidence, evidence, source_urls, added_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        route_id, *new_values, now,
    ))
    return bool(changed)

