RRP_DOCUMENTED_ROUTE_KINDS_V143 = {
    "official", "official_announcement", "official_partner", "press_release", "primary_source",
    "partner_page", "central_bank_pdf", "official_pdf", "official_document", "filing",
    "regulatory_filing_pdf", "technology_basis", "documented_product_platform",
    "documented_pilot", "documented_platform", "documented_partner", "government_pilot",
    "documented", "verified_documentary", "case_study", "partner_case_study", "product_platform",
    "cbdc_pilot", "pilot", "ripple_infra", "payment_rail", "system_rail",
    "documented_infra", "infrastructure", "infrastructure_partner", "institutional_route",
}
RRP_WATCH_ROUTE_KINDS_V143 = {
    "watch", "watch_only", "monitoring_link", "ecosystem_watch", "discovered", "model", "future", "future_watch",
    "deductive_watch", "infra_deduction", "transitive_watch", "onchain_watch", "stablecoin_watch",
    "public_trace_watch", "public_watchpoint", "indirect_watch", "review", "candidate", "inferred",
    "speculative", "public_gateway_watch", "needs_review", "pending_verification",
}

def route_signal(row: pd.Series, route: Tuple[str, str, str, str, str]) -> float:
    _, _, kind, signal, _ = route
    s = float(row.get(signal, 0.0))
    if kind == "core_infra":
        # Las conexiones internas Ripple↔XRPL no dependen de que hoy haya una señal alta en métricas.
        # Son aristas de arquitectura del mapa y deben verse claramente siempre.
        return clamp(max(s, 0.78))
    if kind == "weak_evidence":
        # Una prueba débil no debe desaparecer del mapa confirmado: se ve, pero con línea discontinua/naranja.
        return clamp(max(s, 0.42))
    if kind == "public_trace_watch":
        # Vigilancia publica obligatoria: no es prueba operativa, pero debe ser visible.
        return clamp(max(s, 0.50))
    if kind in RRP_DOCUMENTED_ROUTE_KINDS_V143:
        # Ruta documental/piloto: debe verse aunque la métrica diaria esté baja.
        return clamp(max(s, 0.46))
    if kind in RRP_WATCH_ROUTE_KINDS_V143:
        return clamp(max(s, 0.38))
    if kind == "future":
        s *= 0.40
    return clamp(s)


def route_color(row: pd.Series, route: Tuple[str, str, str, str, str]) -> str:
    s = route_signal(row, route)
    kind = route[2]
    if kind == "core_infra":
        return "#14F195"    # verde XRPL core — infraestructura interna Ripple
    if float(row["bear_score"]) >= 75 and s < 0.45:
        return "#FF5A67"
    if kind == "verified":
        return "#22C55E"    # verde confirmado — verificado por investigación
    if kind == "weak_evidence":
        return "#F59E0B"    # naranja — hay evidencia guardada, pero no suficiente para confirmación fuerte
    if kind == "public_trace_watch":
        return "#F97316"    # naranja vivo — punto publico obligatorio de vigilancia, no prueba operativa
    if kind in RRP_DOCUMENTED_ROUTE_KINDS_V143:
        return "#F59E0B"    # ámbar — prueba documental/piloto/no operativa
    if kind == "core_infra":
        return "#14F195"    # verde XRPL core — infraestructura interna Ripple
    if kind == "real":
        return "#3CFF9B"    # verde neón — on-chain TX directo
    if kind == "obligatory":
        return "#FF4D6D"    # rojo-rosa — implicación técnica
    if kind == "public":
        return "#00CFFF"    # cian — gateway público
    if kind == "monitoring_link":
        return "#38BDF8"   # azul — observabilidad interna, no prueba externa
    if kind == "ecosystem_watch":
        return "#A78BFA"   # violeta — contexto ecosistema, requiere proof-first
    if kind == "watch_only":
        return "#64748B"   # gris — ruta de observación, no prueba verificable
    if kind == "watch":
        return "#B673FF" if s >= 0.45 else "#9B59B6"   # morado — vigilada
    if kind in {"deductive_watch", "infra_deduction", "transitive_watch"}:
        return "#B673FF" if s >= 0.35 else "#8B5CF6"   # morado — deducción/vigilancia explícita
    if kind in {"government_payment_rail", "official", "institutional"}:
        return "#FCD34D" if s >= 0.35 else "#F59E0B"
    if kind == "model":
        return "#5AD7FF" if s >= 0.45 else "#60A5FA"
    if kind == "future":
        return "#8CA0B8"
    if kind in {"odl"}:
        return "#FB923C"    # naranja — corredor ODL
    if kind in {"discovered"}:
        return "#FFD700"    # dorado — descubierta IA
    return "#F59E0B" if s >= 0.45 else "#D97706"  # ámbar — privada inferida


def route_dash(route: Tuple[str, str, str, str, str]) -> str:
    kind = route[2]
    if kind in {"real", "public", "verified", "core_infra"}:
        return "solid"      # confirmado/on-chain/público/core Ripple-XRPL
    if kind == "weak_evidence":
        return "dash"       # evidencia débil: visible en confirmadas, pero sin venderla como confirmación fuerte
    if kind == "public_trace_watch":
        return "dash"       # vigilancia obligatoria publica: visible, pero no afirmacion operativa
    if kind in RRP_DOCUMENTED_ROUTE_KINDS_V143:
        return "dashdot"    # documental/piloto: visible, pero no se vende como operación on-chain
    if kind == "obligatory":
        return "dash"       # deducción técnica declarada; debe verse como regla/estructura, no como TX directa
    if kind in {"watch_only", "monitoring_link"}:
        return "dot"
    if kind == "ecosystem_watch":
        return "dash"
    if kind in {"watch", "model"}:
        return "solid"
    if kind in {"deductive_watch", "infra_deduction", "transitive_watch"}:
        return "dash"
    if kind in {"government_payment_rail", "official", "institutional"}:
        return "dashdot"
    if kind == "future":
        return "dot"
    if kind == "discovered":
        return "dashdot"
    return "dash"


def hot_routes_count(row: pd.Series) -> int:
    return sum(route_signal(row, r) >= 0.60 for r in ROUTES)


def get_state(row: pd.Series) -> Dict[str, str]:
    phase = int(row["phase"])
    phase_name = str(row["phase_name"])

    if float(row["flip_score"]) >= 80:
        return {
            "state": "flip",
            "headline": "🔥 Flip de Switches en curso",
            "simple": "El radar detecta huellas públicas coordinadas, clusters, topología y persistencia. Esto ya no parece solo ruido.",
            "price": "Potencial de repunte fuerte si la demanda no encuentra suficiente oferta.",
            "risk": "Riesgo medio: parte institucional sigue inferida, pero la huella pública es fuerte.",
            "adoption": f"Fase {phase} — {phase_name}",
        }
    if float(row["bear_score"]) >= 75:
        return {
            "state": "bear",
            "headline": "⚠️ Riesgo de bajada / slowdown",
            "simple": "La actividad pública verificable cae o parece spike sin persistencia.",
            "price": "Riesgo de falso rebote o presión bajista.",
            "risk": "Alto.",
            "adoption": f"Fase {phase} — {phase_name}: sin adopción real confirmada.",
        }
    if float(row["bull_score"]) >= 62 and float(row["price_score"]) >= 58:
        return {
            "state": "bull",
            "headline": "🟢 Repunte probable en precio",
            "simple": "Hay actividad suficiente para impulso de precio, pero el sistema aún separa esto de adopción real.",
            "price": "Repunte probable.",
            "risk": "Medio.",
            "adoption": f"Fase {phase} — {phase_name}: todavía no es Full Flip.",
        }
    return {
        "state": "normal",
        "headline": "🟠 Actividad normal",
        "simple": "Señales mixtas. El radar no ve aún huellas públicas coordinadas suficientes.",
        "price": "Sin señal clara.",
        "risk": "Neutral/moderado.",
        "adoption": f"Fase {phase} — {phase_name}",
    }


