# =============================================================================
# Esta capa evita el falso 0% cuando no existe A→C directo pero sí existe
# una cadena documental A→B→C. También conserva la frontera crítica:
# XRPL/RLUSD sin prueba directa quedan como WATCH/INFERIDO, no como operativo.

CHAIN_TARGETS = {"Ripple Payments", "RippleNet", "XRPL", "RLUSD"}
WATCH_ONLY_CHAIN_TARGETS = {"XRPL", "RLUSD"}
CHAIN_CORE_TARGETS = {"Ripple Payments", "RippleNet"}

CHAIN_EVIDENCE_SEEDS = []
# CLEAN MODE: sin pruebas semilla/precargadas.
# Las pruebas institucionales deben venir de una búsqueda/verificación real o de la BD generada por el usuario.



def _contains_cjk(text: Any) -> bool:
    return any("\u4e00" <= ch <= "\u9fff" for ch in str(text or ""))


def _native_query_variants(entity: Any) -> List[str]:
    """Consultas adicionales en idioma nativo para que 中国人民银行 no se busque solo en inglés."""
    raw = str(entity or "").strip()
    canonical = _canonical_entity_name(raw)
    key = _norm_key(raw)
    variants: List[str] = []

    def add(q: str) -> None:
        q = re.sub(r"\s+", " ", str(q or "").strip())
        if q and q not in variants:
            variants.append(q)

    native = None
    try:
        native = NATIVE_ENTITY_HINTS.get(key, (None, None))[1]
    except Exception:
        native = None
    if _contains_cjk(raw):
        native = raw
    if canonical == "People's Bank of China (PBoC)":
        native = native or "中国人民银行"
        for q in [
            f'"{native}" 连连支付',
            f'"{native}" mBridge',
            f'"{native}" 多边央行数字货币桥',
            f'"{native}" 国际清算银行',
            f'"{native}" 跨境支付 区块链',
            f'"{native}" Ripple',
            f'"{native}" RippleNet',
            '中国人民银行 连连支付',
            '中国人民银行 mBridge',
            '数字人民币 mBridge',
            '连连支付 Ripple',
            '连连国际 RippleNet',
            '人民银行 跨境支付 区块链',
        ]:
            add(q)

    if native and native != raw:
        for q in [f'"{native}" Ripple', f'"{native}" XRPL', f'"{native}" RippleNet', f'"{native}" mBridge']:
            add(q)

    for q in [
        f'"{canonical}" "Ripple"',
        f'"{canonical}" "XRPL"',
        f'"{canonical}" "RippleNet"',
        f'"{canonical}" "Project mBridge"',
        f'"{canonical}" "LianLian Pay"',
    ]:
        add(q)
    return variants[:14]


def _native_query_instruction(entity: Any) -> str:
    qs = _native_query_variants(entity)
    if not qs:
        return ""
    return (
        "\nBÚSQUEDA MULTILINGÜE OBLIGATORIA: además del nombre inglés/canónico, ejecuta consultas locales como: "
        + " ; ".join(qs)
        + ". Prioriza fuentes oficiales del país, PDFs, bancos centrales, BIS y comunicados de la entidad. "
    )


def _chain_all_routes(conn: Optional[sqlite3.Connection] = None) -> List[Tuple[str, str, str, str, str]]:
    routes = list(ROUTES)
    if conn is not None:
        try:
            rows = conn.execute("SELECT src,dst,kind,signal_col,label FROM dynamic_routes WHERE COALESCE(sanitizer_status,'active')!='quarantined'").fetchall()
            routes.extend([(str(a), str(b), str(c), str(d), str(e)) for a, b, c, d, e in rows])
        except Exception:
            pass
    # dedupe dirigido conservando orden
    seen = set(); out = []
    for r in routes:
        if len(r) < 5:
            continue
        key = (_canonical_entity_key(r[0]), _canonical_entity_key(r[1]), str(r[2]))
        if key not in seen:
            out.append(r); seen.add(key)
    return out


def _proof_score_from_row(row: Any) -> Tuple[float, Dict[str, Any]]:
    if not row:
        return 0.0, {}
    try:
        pdata = json.loads(row[0] or "{}")
    except Exception:
        pdata = {}
    try:
        score = float(pdata.get("calibrated_score", row[2] if len(row) > 2 else 0.0) or 0.0)
    except Exception:
        score = 0.0
    return max(0.0, min(1.0, score)), pdata


def _verified_direct_score(conn: sqlite3.Connection, a: str, b: str) -> Tuple[float, Dict[str, Any]]:
    row = _connection_proof_row(conn, a, b)
    score, pdata = _proof_score_from_row(row)
    if score <= 0:
        return 0.0, {}
    ptype = str((pdata.get("proofs") or [{}])[0].get("type", "")).lower() if isinstance(pdata.get("proofs"), list) else ""
    if ptype in {"sin_wallet", "unknown", "no_evidence"} and not pdata.get("has_internet") and not pdata.get("has_onchain"):
        return 0.0, {}
    # 0.50+ se considera eslabón válido. Los chains sintetizados también valen si son a Ripple Payments/RippleNet.
    if score >= 0.50 or str(pdata.get("chain_status", "")).startswith("verified"):
        return score, pdata
    return 0.0, {}


def _upsert_chain_seed(conn: sqlite3.Connection, seed: Dict[str, Any]) -> None:
    a = _canonical_entity_name(seed.get("a")); b = _canonical_entity_name(seed.get("b"))
    existing = _connection_proof_row(conn, a, b)
    score, _ = _proof_score_from_row(existing)
    if score >= float(seed.get("score", 0.0)):
        return
    now = datetime.now(timezone.utc).isoformat()
    proof = {
        "type": seed.get("type", "official_partner"),
        "icon": "🏛️",
        "label": seed.get("label", "Prueba institucional semilla"),
        "url": seed.get("url", ""),
        "snippet": seed.get("snippet", ""),
        "internet": True,
        "onchain": False,
    }
    pdata = {
        "node_a": a, "node_b": b,
        "proofs": [proof],
        "cert_label": "✅ Evidencia documental/institucional",
        "cert_color": "#22C55E",
        "calibrated_score": float(seed.get("score", 0.0)),
        "has_onchain": False,
        "has_internet": True,
        "seeded_known_evidence": True,
    }
    conn.execute("""
        INSERT OR REPLACE INTO connection_proofs
        (proof_id, node_a, node_b, node_a_key, node_b_key, pair_key, proof_type, proof_data, onchain, confidence, validated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        _canonical_pair_proof_id(a, b), a, b, _canonical_entity_key(a), _canonical_entity_key(b), _canonical_pair_key(a, b),
        proof["type"], json.dumps(pdata, ensure_ascii=False), 1, float(seed.get("score", 0.0)), now
    ))


def _seed_known_chain_evidence_if_relevant(conn: sqlite3.Connection, focus_node: str = "") -> None:
    """CLEAN MODE: no inserta semillas conocidas ni pruebas precargadas."""
    return


def _find_verified_route_chain(conn: sqlite3.Connection, source: str, target: str, max_hops: int = 3) -> Optional[Dict[str, Any]]:
    source = _canonical_entity_name(source); target = _canonical_entity_name(target)
    adjacency: Dict[str, List[str]] = defaultdict(list)
    for a, b, *_ in _chain_all_routes(conn):
        aa = _canonical_entity_name(a); bb = _canonical_entity_name(b)
        if aa and bb and bb not in adjacency[aa]:
            adjacency[aa].append(bb)

    queue = deque([(source, [source])])
    visited = {source}
    while queue:
        node, route = queue.popleft()
        if len(route) - 1 > max_hops:
            continue
        if node == target and len(route) > 1:
            scores = []; proof_datas = []
            ok = True
            for a, b in zip(route[:-1], route[1:]):
                sc, pd = _verified_direct_score(conn, a, b)
                if sc <= 0:
                    ok = False; break
                scores.append(sc); proof_datas.append(pd)
            if ok and scores:
                conf = max(0.0, min(0.95, min(scores) - (len(scores)-1)*0.08))
                return {"route": route, "confidence": conf, "proof_datas": proof_datas}
        for nxt in adjacency.get(node, []):
            if nxt not in visited and len(route) <= max_hops:
                visited.add(nxt)
                queue.append((nxt, route + [nxt]))
    return None


def _save_synthetic_chain_proof(conn: sqlite3.Connection, source: str, target: str, chain: Dict[str, Any], watch: bool = False) -> None:
    source = _canonical_entity_name(source); target = _canonical_entity_name(target)
    if not chain or not chain.get("route"):
        return
    direct_score, direct_pd = _verified_direct_score(conn, source, target)
    # Nunca rebajar una prueba directa fuerte.
    if direct_score >= 0.60 and not direct_pd.get("chain_synthetic"):
        return
    route = chain["route"]
    conf = float(chain.get("confidence", 0.0))
    if watch:
        conf = min(conf, 0.45)
        cert_label = "👁 Watch/inferida por cadena"
        cert_color = "#F59E0B"
        proof_type = "watch_inferred_chain"
        label = "Conexión inferida por cadena; requiere prueba directa para considerarse operativa"
    else:
        cert_label = "🔗 Indirecta verificada por cadena"
        cert_color = "#38BDF8"
        proof_type = "verified_chain"
        label = "Conexión indirecta verificada por cadena documental"
    urls = []
    for pd in chain.get("proof_datas", []):
        for pr in pd.get("proofs", []) if isinstance(pd, dict) else []:
            u = _canonical_source_url(pr.get("url", ""))
            if u.startswith("http") and u not in urls:
                urls.append(u)
    now = datetime.now(timezone.utc).isoformat()
    proof = {
        "type": proof_type,
        "icon": "🔗" if not watch else "👁",
        "label": label,
        "url": urls[0] if urls else "",
        "snippet": " → ".join(route),
        "internet": True,
        "onchain": False,
        "chain_route": route,
        "sources": urls[:5],
    }
    pdata = {
        "node_a": source,
        "node_b": target,
        "proofs": [proof],
        "cert_label": cert_label,
        "cert_color": cert_color,
        "calibrated_score": conf,
        "has_onchain": False,
        "has_internet": True,
        "chain_synthetic": True,
        "chain_status": proof_type,
        "chain_route": route,
        "chain_explanation": _explain_chain_plain(source, target, route, watch),
    }
    conn.execute("""
        INSERT OR REPLACE INTO connection_proofs
        (proof_id, node_a, node_b, node_a_key, node_b_key, pair_key, proof_type, proof_data, onchain, confidence, validated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        _canonical_pair_proof_id(source, target), source, target,
        _canonical_entity_key(source), _canonical_entity_key(target), _canonical_pair_key(source, target),
        proof_type, json.dumps(pdata, ensure_ascii=False), 0, conf, now
    ))


def _explain_chain_plain(source: str, target: str, route: List[str], watch: bool) -> str:
    r = " → ".join(route)
    if watch:
        return (f"{source} no tiene una prueba directa operativa hacia {target}. "
                f"El radar detecta una ruta indirecta ({r}), pero como {target} exige prueba directa/on-chain, "
                "queda marcado como watch/inferido.")
    return (f"{source} conecta con {target} por una cadena de eslabones verificados: {r}. "
            "No es una prueba de operación directa A→C, sino una relación indirecta trazable.")


def rebuild_chain_proofs_for_node(conn: sqlite3.Connection, focus_node: str, peers: Optional[List[str]] = None) -> None:
    """Actualiza pruebas de cadena tras cada búsqueda/verificación para que las líneas cambien al instante."""
    ensure_discovery_tables(conn)
    _seed_known_chain_evidence_if_relevant(conn, focus_node)
    focus = _canonical_entity_name(focus_node)
    targets = set(CHAIN_TARGETS)
    if peers:
        targets.update(_canonical_entity_name(p) for p in peers)
    # 1) A→Ripple Payments/RippleNet como indirecta verificada si hay cadena documental.
    for target in ["Ripple Payments", "RippleNet"]:
        if focus == target:
            continue
        ch = _find_verified_route_chain(conn, focus, target, max_hops=3)
        if ch:
            _save_synthetic_chain_proof(conn, focus, target, ch, watch=False)
    # 2) A→XRPL/RLUSD como WATCH si A llega a Ripple Payments pero no existe prueba directa a XRPL/RLUSD.
    base = _find_verified_route_chain(conn, focus, "Ripple Payments", max_hops=3)
    if base:
        for target in ["XRPL", "RLUSD"]:
            if focus == target:
                continue
            direct_score, direct_pd = _verified_direct_score(conn, focus, target)
            if direct_score >= 0.60 and not direct_pd.get("chain_synthetic"):
                continue
            watch_chain = dict(base)
            watch_chain["route"] = list(base["route"]) + [target]
            _save_synthetic_chain_proof(conn, focus, target, watch_chain, watch=True)
    # 3) Cadenas entre peers visibles: si A→B→C está probado, crear A→C.
    if peers:
        for target in peers:
            t = _canonical_entity_name(target)
            if t == focus:
                continue
            ch = _find_verified_route_chain(conn, focus, t, max_hops=3)
            if ch:
                _save_synthetic_chain_proof(conn, focus, t, ch, watch=(t in WATCH_ONLY_CHAIN_TARGETS))
    try:
        conn.commit()
    except Exception:
        pass


def render_chain_logic_box(focus_node: str, conn: Optional[sqlite3.Connection]) -> None:
    if conn is None:
        return
    try:
        key = _canonical_entity_key(focus_node)
        rows = conn.execute(
            "SELECT node_a,node_b,proof_data,confidence FROM connection_proofs "
            "WHERE COALESCE(sanitizer_status,'active')!='quarantined' AND (node_a=? OR node_b=? OR node_a_key=? OR node_b_key=?) ORDER BY confidence DESC LIMIT 10",
            (focus_node, focus_node, key, key)
        ).fetchall()
    except Exception:
        rows = []
    if not rows:
        return
    items = []
    for na, nb, pdata_s, conf in rows:
        try:
            pd = json.loads(pdata_s or "{}")
        except Exception:
            pd = {}
        route = pd.get("chain_route") or []
        cert = pd.get("cert_label") or "Prueba guardada"
        expl = pd.get("chain_explanation") or "Eslabón directo o prueba guardada."
        peer = nb if _canonical_entity_key(na) == _canonical_entity_key(focus_node) else na
        route_txt = " → ".join(route) if route else f"{na} ↔ {nb}"
        items.append(
            f"<li style='margin-bottom:6px'><b>{html.escape(str(peer))}</b> · "
            f"<span style='color:#CBD5E1'>{html.escape(str(cert))} · {float(conf or 0)*100:.0f}%</span><br>"
            f"<code style='white-space:normal;color:#93C5FD'>{html.escape(route_txt)}</code><br>"
            f"<span style='color:#94A3B8'>{html.escape(str(expl))}</span></li>"
        )
    st.markdown(f"""
<div style='border:1px solid #334155;border-radius:14px;padding:13px 15px;background:rgba(15,23,42,.86);margin:10px 0 14px 0'>
  <div style='color:#E2E8F0;font-weight:800;font-size:.95rem;margin-bottom:5px'>🧠 Lectura por cadena de evidencia</div>
  <div style='color:#CBD5E1;font-size:.82rem;line-height:1.5;margin-bottom:8px'>
    El radar no verifica solo enlaces directos. Si <b>A</b> conecta documentalmente con <b>B</b>, y <b>B</b> conecta con <b>C</b>,
    entonces <b>A→C</b> se muestra como conexión indirecta verificada por cadena. Pero si el destino final es <b>XRPL</b> o <b>RLUSD</b>
    y no hay prueba directa/on-chain, se queda como <b>watch/inferida</b>, no como conexión operativa.
  </div>
  <ul style='margin:0;padding-left:18px;font-size:.80rem;line-height:1.45'>{''.join(items)}</ul>
</div>
""", unsafe_allow_html=True)

def ensure_discovery_tables(conn: sqlite3.Connection) -> None:
    conn.executescript("""
        CREATE TABLE IF NOT EXISTS dynamic_nodes (
            node_id     TEXT PRIMARY KEY,
            name        TEXT NOT NULL,
            layer       TEXT NOT NULL DEFAULT 'Descubierto',
            icon        TEXT NOT NULL DEFAULT '?',
            confidence  REAL NOT NULL DEFAULT 0.0,
            source_url  TEXT,
            summary     TEXT,
            added_at    TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS dynamic_routes (
            route_id    TEXT PRIMARY KEY,
            src         TEXT NOT NULL,
            dst         TEXT NOT NULL,
            kind        TEXT NOT NULL DEFAULT 'discovered',
            signal_col  TEXT NOT NULL DEFAULT 'institutional_route_score',
            label       TEXT NOT NULL,
            confidence  REAL NOT NULL DEFAULT 0.0,
            evidence    TEXT,
            source_urls TEXT,
            added_at    TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS institution_search_cache (
            query       TEXT PRIMARY KEY,
            result_json TEXT NOT NULL,
            searched_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS search_cache_aliases (
            alias_key       TEXT PRIMARY KEY,
            canonical_query TEXT NOT NULL,
            canonical_name  TEXT,
            search_type     TEXT NOT NULL DEFAULT 'discovery',
            created_at      TEXT NOT NULL,
            hit_count       INTEGER NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS api_search_audit (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            query_text      TEXT NOT NULL,
            canonical_key   TEXT,
            search_type     TEXT NOT NULL DEFAULT 'discovery',
            decision        TEXT NOT NULL,
            source          TEXT,
            reason          TEXT,
            created_at      TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS connection_proofs (
            proof_id      TEXT PRIMARY KEY,
            node_a        TEXT NOT NULL,
            node_b        TEXT NOT NULL,
            node_a_key    TEXT,
            node_b_key    TEXT,
            pair_key      TEXT,
            proof_type    TEXT NOT NULL,
            proof_data    TEXT NOT NULL DEFAULT '{}',
            onchain       INTEGER NOT NULL DEFAULT 0,
            confidence    REAL NOT NULL DEFAULT 0.0,
            validated_at  TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS node_verifications (
            node          TEXT PRIMARY KEY,
            connected     INTEGER NOT NULL DEFAULT 0,
            confidence    REAL NOT NULL DEFAULT 0.0,
            kind_override TEXT NOT NULL DEFAULT 'verified',
            proofs_json   TEXT NOT NULL DEFAULT '[]',
            verified_at   TEXT NOT NULL,
            source        TEXT NOT NULL DEFAULT 'manual'
        );
        CREATE TABLE IF NOT EXISTS map_update_log (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            update_type TEXT NOT NULL,
            entity_name TEXT NOT NULL,
            details     TEXT,
            updated_at  TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS api_budget (
            id            INTEGER PRIMARY KEY CHECK (id=1),
            budget_usd    REAL NOT NULL DEFAULT 100.0,
            spent_usd     REAL NOT NULL DEFAULT 0.0,
            call_count    INTEGER NOT NULL DEFAULT 0,
            cache_hits    INTEGER NOT NULL DEFAULT 0,
            last_reset    TEXT NOT NULL,
            locked        INTEGER NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS active_sessions (
            session_id    TEXT PRIMARY KEY,
            started_at    TEXT NOT NULL,
            heartbeat     TEXT NOT NULL,
            status        TEXT NOT NULL DEFAULT 'idle'
        );
        CREATE TABLE IF NOT EXISTS community_users (
            user_id       TEXT PRIMARY KEY,
            nickname      TEXT NOT NULL,
            created_at    TEXT NOT NULL,
            last_seen     TEXT NOT NULL,
            reputation    INTEGER NOT NULL DEFAULT 1,
            muted         INTEGER NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS community_messages (
            id            INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id       TEXT NOT NULL,
            nickname      TEXT NOT NULL,
            body          TEXT NOT NULL,
            created_at    TEXT NOT NULL,
            deleted       INTEGER NOT NULL DEFAULT 0,
            lang          TEXT NOT NULL DEFAULT 'es',
            pinned        INTEGER NOT NULL DEFAULT 0,
            role          TEXT NOT NULL DEFAULT 'user'
        );
        CREATE TABLE IF NOT EXISTS chat_translations (
            message_id    INTEGER NOT NULL,
            target_lang   TEXT NOT NULL,
            translated    TEXT NOT NULL,
            created_at    TEXT NOT NULL,
            PRIMARY KEY(message_id, target_lang)
        );
        CREATE TABLE IF NOT EXISTS ai_waiting_queue (
            session_id    TEXT PRIMARY KEY,
            nickname      TEXT,
            query         TEXT NOT NULL,
            status        TEXT NOT NULL DEFAULT 'queued',
            created_at    TEXT NOT NULL,
            updated_at    TEXT NOT NULL
        );
    """)
    # Migraciones: añadir columnas nuevas si la tabla ya existe sin ellas
    _migrations = [
        ("dynamic_routes",         "source_urls TEXT"),
        ("dynamic_nodes",          "source_url  TEXT"),
        ("connection_proofs",      "proof_data  TEXT NOT NULL DEFAULT '{}'"),
        ("connection_proofs",      "node_a_key  TEXT"),
        ("connection_proofs",      "node_b_key  TEXT"),
        ("connection_proofs",      "pair_key    TEXT"),
        ("node_verifications",     "source      TEXT NOT NULL DEFAULT 'manual'"),
        ("institution_search_cache","expires_at  TEXT"),
        ("institution_search_cache","hit_count   INTEGER NOT NULL DEFAULT 0"),
        ("institution_search_cache","search_type TEXT NOT NULL DEFAULT 'discovery'"),
        ("community_users",        "language    TEXT NOT NULL DEFAULT 'es'"),
        ("community_users",        "role        TEXT NOT NULL DEFAULT 'user'"),
        ("community_messages",     "lang        TEXT NOT NULL DEFAULT 'es'"),
        ("community_messages",     "pinned      INTEGER NOT NULL DEFAULT 0"),
        ("community_messages",     "role        TEXT NOT NULL DEFAULT 'user'"),
    ]
    for table, col_def in _migrations:
        col_name = col_def.split()[0]
        existing = [r[1] for r in conn.execute(f"PRAGMA table_info({table})").fetchall()]
        if col_name not in existing:
            try:
                conn.execute(f"ALTER TABLE {table} ADD COLUMN {col_def}")
            except Exception:
                pass
    # Backfill de claves canónicas para pruebas antiguas: evita duplicados A↔B/B↔A.
    try:
        rows = conn.execute("SELECT proof_id, node_a, node_b FROM connection_proofs").fetchall()
        for old_pid, na, nb in rows:
            na_key = _canonical_entity_key(na)
            nb_key = _canonical_entity_key(nb)
            pk = _canonical_pair_key(na, nb)
            new_pid = _canonical_pair_proof_id(na, nb)
            conn.execute(
                "UPDATE connection_proofs SET node_a_key=?, node_b_key=?, pair_key=? WHERE proof_id=?",
                (na_key, nb_key, pk, old_pid),
            )
            # Si aún no existe el proof_id canónico, migrar el id para que futuras búsquedas lo encuentren directo.
            if old_pid != new_pid:
                exists = conn.execute("SELECT 1 FROM connection_proofs WHERE proof_id=?", (new_pid,)).fetchone()
                if not exists:
                    conn.execute("UPDATE connection_proofs SET proof_id=? WHERE proof_id=?", (new_pid, old_pid))
        conn.execute("CREATE INDEX IF NOT EXISTS idx_connection_proofs_pair_key ON connection_proofs(pair_key)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_connection_proofs_node_keys ON connection_proofs(node_a_key, node_b_key)")
    except Exception:
        pass
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_search_cache_aliases_canonical ON search_cache_aliases(canonical_query)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_api_search_audit_key_type ON api_search_audit(canonical_key, search_type)")
    except Exception:
        pass
    conn.commit()


# =============================================================================
# CACHÉ COMPARTIDA MULTI-USUARIO
# =============================================================================
# Toda búsqueda AI se guarda en institution_search_cache (SQLite compartido).
# Si otro usuario busca la misma entidad → resultado instantáneo, 0 tokens.
# TTL configurable por tipo de búsqueda.

_CACHE_TTL: Dict[str, int] = {
    # CostGuard v2: las conexiones institucionales no cambian cada día.
    # TTL más largo = menos llamadas repetidas sin perder utilidad para una beta pública.
    "discovery":    30,  # días — búsqueda de partners/conexiones
    "verification": 60,  # días — verificación individual, incluso negativa
    "batch_verify": 60,  # días — verificación en lote
    "negative":     14,  # días — reservado para futuros negativos explícitos
}
_MAX_AI_CALLS_SESSION = 20  # máximo de llamadas AI nuevas por sesión de usuario normal; admin = ilimitado
_MAX_BATCH_PEERS = 5        # no verificar 20 rutas caras a la vez


def _is_admin_unlimited_ai(conn: Optional[sqlite3.Connection] = None) -> bool:
    """True si esta sesión es admin y debe saltarse límites de cupo, cola y búsquedas por sesión.

    Mantiene separado el presupuesto global API/CostGuard: el admin no consume cupo público,
    pero el presupuesto global sigue protegiendo el gasto total salvo que se cambie esa política.
    """
    try:
        if st.session_state.get("admin_authenticated") and _is_admin_name(st.session_state.get("community_nickname", "")):
            return True
        if conn is not None and _is_admin_session(conn):
            return True
    except Exception:
        pass
    return False

_PRIORITY_PEERS = [
    "RLUSD", "XRPL", "Ripple Payments", "Ripple Prime", "Hidden Road",
    "Custody/Metaco", "Metaco", "Securitize", "Treasury", "DEX/AMM",
    "Permissioned DEX", "DTCC/NSCC", "SWIFT", "FedNow"
]


def _cache_key_search(canonical_name: str, search_type: str) -> str:
    # La clave de caché usa el nombre canónico + normalización fuerte.
    # Así "BLACK ROCK INC.", "black-rock" y "BlackRock" reutilizan la misma respuesta.
    canonical = _canonical_entity_name(canonical_name)
    return f"{search_type}::{_norm_key(canonical)}"


def _cache_alias_keys(name: str, search_type: str = "discovery") -> List[str]:
    """Claves alternativas para que BlackRock, black rock, BLACKROCK INC, etc. reutilicen caché."""
    raw = str(name or "").strip()
    canonical = _canonical_entity_name(raw)
    keys = []
    for val in {raw, canonical, raw.replace("-", " "), raw.replace(".", " "), raw.replace(",", " ")}:
        nk = _norm_key(val)
        if nk:
            keys.append(f"{search_type}::{nk}")
    # Compacta nombres corporativos comunes para capturar variantes.
    compact = re.sub(r"\b(inc|ltd|limited|llc|corp|corporation|group|holdings|plc|sa|ag|nv|bank)\b", "", _norm_key(raw))
    compact = re.sub(r"\s+", " ", compact).strip()
    if compact:
        keys.append(f"{search_type}::{compact}")
    return list(dict.fromkeys(keys))


def _audit_search_decision(conn: sqlite3.Connection, query: str, search_type: str, decision: str, source: str = "", reason: str = "") -> None:
    try:
        conn.execute(
            "INSERT INTO api_search_audit(query_text, canonical_key, search_type, decision, source, reason, created_at) VALUES(?,?,?,?,?,?,?)",
            (str(query or "")[:240], _cache_key_search(str(query or ""), search_type), search_type, decision, source[:120], reason[:500], datetime.now(timezone.utc).isoformat())
        )
        conn.commit()
    except Exception:
        pass


def _get_search_cache(conn: sqlite3.Connection, name: str,
                      search_type: str = "discovery") -> Optional[Dict]:
    """Devuelve resultado cacheado si existe y no ha expirado. Primero exacto, luego alias normalizados."""
    try:
        now = datetime.now(timezone.utc).isoformat()
        candidate_keys = _cache_alias_keys(name, search_type)
        key = candidate_keys[0] if candidate_keys else _cache_key_search(_canonical_entity_name(name), search_type)

        # 1) Búsqueda exacta/normalizada directa.
        for cand in candidate_keys:
            row = conn.execute(
                "SELECT result_json FROM institution_search_cache WHERE query=? AND (expires_at IS NULL OR expires_at > ?)",
                (cand, now)
            ).fetchone()
            if row:
                conn.execute("UPDATE institution_search_cache SET hit_count=hit_count+1 WHERE query=?", (cand,))
                conn.commit()
                try:
                    _record_cache_hit(conn)
                    _audit_search_decision(conn, name, search_type, "cache_hit", "institution_search_cache", f"key={cand}")
                except Exception:
                    pass
                return json.loads(row[0])

        # 2) Búsqueda por alias → canonical_query.
        for cand in candidate_keys:
            row_alias = conn.execute(
                "SELECT canonical_query FROM search_cache_aliases WHERE alias_key=? AND search_type=?",
                (cand, search_type)
            ).fetchone()
            if not row_alias:
                continue
            canonical_query = row_alias[0]
            row = conn.execute(
                "SELECT result_json FROM institution_search_cache WHERE query=? AND (expires_at IS NULL OR expires_at > ?)",
                (canonical_query, now)
            ).fetchone()
            if row:
                conn.execute("UPDATE search_cache_aliases SET hit_count=hit_count+1 WHERE alias_key=?", (cand,))
                conn.execute("UPDATE institution_search_cache SET hit_count=hit_count+1 WHERE query=?", (canonical_query,))
                conn.commit()
                try:
                    _record_cache_hit(conn)
                    _audit_search_decision(conn, name, search_type, "cache_alias_hit", "search_cache_aliases", f"alias={cand} -> {canonical_query}")
                except Exception:
                    pass
                return json.loads(row[0])
    except Exception:
        pass
    return None



def _delete_discovery_cache_for_entity(conn: sqlite3.Connection, name: str,
                                       search_type: str = "discovery") -> int:
    """Borra caché/aliases de una entidad para obligar a una búsqueda online real.

    Incluye claves modernas (discovery::<normalizado>) y claves legacy guardadas
    como nombre plano en versiones antiguas.
    """
    deleted = 0
    try:
        raw = str(name or "").strip()
        canonical = _canonical_entity_name(raw)
        variants = {raw, canonical, raw.lower(), canonical.lower(), _norm_key(raw), _norm_key(canonical)}
        variants.update(_entity_alias_keys(raw))
        variants.update(_entity_alias_keys(canonical))
        cache_keys = set()
        for v in list(variants):
            v = str(v or "").strip()
            if not v:
                continue
            cache_keys.add(v)
            cache_keys.add(v.lower())
            cache_keys.add(f"{search_type}::{_norm_key(v)}")
        cache_keys.update(_cache_alias_keys(raw, search_type))
        cache_keys.update(_cache_alias_keys(canonical, search_type))

        canonical_queries = set()
        for k in list(cache_keys):
            for row in conn.execute(
                "SELECT canonical_query FROM search_cache_aliases WHERE alias_key=? OR canonical_query=?",
                (k, k),
            ).fetchall():
                if row and row[0]:
                    canonical_queries.add(row[0])
        cache_keys.update(canonical_queries)

        for k in list(cache_keys):
            cur = conn.execute("DELETE FROM institution_search_cache WHERE query=?", (k,))
            deleted += int(cur.rowcount or 0)
            cur = conn.execute(
                "DELETE FROM search_cache_aliases WHERE alias_key=? OR canonical_query=?",
                (k, k),
            )
            deleted += int(cur.rowcount or 0)
        conn.commit()
        _audit_search_decision(conn, raw, search_type, "cache_purged_for_clean_research", "ui_clean_research", f"deleted={deleted}")
    except Exception:
        pass
    return deleted


def _purge_discovery_associations_for_entity(conn: sqlite3.Connection, name: str,
                                             purge_cache: bool = True) -> Dict[str, int]:
    """Elimina lo que la entidad ya encontró para poder re-investigar de cero.

    Borra solo memoria dinámica/derivada de esa entidad: rutas dinámicas, pruebas
    guardadas, route_paths y caché de búsqueda. No toca NODES ni ROUTES fijas.
    """
    ensure_discovery_tables(conn)
    try:
        ensure_route_paths_table(conn)
    except Exception:
        pass

    raw = str(name or "").strip()
    canonical = _canonical_entity_name(raw)
    entity_key = _canonical_entity_key(canonical)
    counters = {"cache": 0, "dynamic_routes": 0, "connection_proofs": 0, "route_paths": 0, "node_verifications": 0, "dynamic_nodes": 0, "audit": 0}

    def same_entity(value: Any) -> bool:
        try:
            return _canonical_entity_key(value) == entity_key
        except Exception:
            return False

    try:
        # 1) Rutas dinámicas directas A→B donde la entidad participa.
        rows = conn.execute("SELECT route_id, src, dst FROM dynamic_routes").fetchall()
        ids = [r[0] for r in rows if same_entity(r[1]) or same_entity(r[2])]
        for rid in ids:
            cur = conn.execute("DELETE FROM dynamic_routes WHERE route_id=?", (rid,))
            counters["dynamic_routes"] += int(cur.rowcount or 0)

        # 2) Pruebas guardadas A↔B donde la entidad participa.
        rows = conn.execute("SELECT proof_id, node_a, node_b, node_a_key, node_b_key FROM connection_proofs").fetchall()
        pids = []
        for pid, a, b, ak, bk in rows:
            if same_entity(a) or same_entity(b) or str(ak or "") == entity_key or str(bk or "") == entity_key:
                pids.append(pid)
        for pid in pids:
            cur = conn.execute("DELETE FROM connection_proofs WHERE proof_id=?", (pid,))
            counters["connection_proofs"] += int(cur.rowcount or 0)

        # 3) Rutas A→B materializadas.
        try:
            rows = conn.execute("SELECT rowid, origin, public_hop, destination FROM route_paths").fetchall()
            rowids = [r[0] for r in rows if same_entity(r[1]) or same_entity(r[2]) or same_entity(r[3])]
            for rowid in rowids:
                cur = conn.execute("DELETE FROM route_paths WHERE rowid=?", (rowid,))
                counters["route_paths"] += int(cur.rowcount or 0)
        except Exception:
            pass

        # 4) Verificación manual/derivada del nodo.
        try:
            rows = conn.execute("SELECT node FROM node_verifications").fetchall()
            for (node,) in rows:
                if same_entity(node):
                    cur = conn.execute("DELETE FROM node_verifications WHERE node=?", (node,))
                    counters["node_verifications"] += int(cur.rowcount or 0)
        except Exception:
            pass

        # 5) Nodo dinámico principal solo si NO es nodo fijo. SWIFT/FedNow/etc. se conservan.
        if canonical not in NODES:
            try:
                rows = conn.execute("SELECT name FROM dynamic_nodes").fetchall()
                for (node,) in rows:
                    if same_entity(node):
                        cur = conn.execute("DELETE FROM dynamic_nodes WHERE name=?", (node,))
                        counters["dynamic_nodes"] += int(cur.rowcount or 0)
            except Exception:
                pass

        # 6) Auditoría de búsquedas de esa entidad: no afecta al mapa, pero evita que
        # el panel siga sugiriendo que la última investigación antigua es la actual.
        try:
            rows = conn.execute("SELECT id, query_text, canonical_key FROM api_search_audit WHERE search_type='discovery'").fetchall()
            for aid, qtxt, ckey in rows:
                if same_entity(qtxt) or str(ckey or "") == entity_key:
                    cur = conn.execute("DELETE FROM api_search_audit WHERE id=?", (aid,))
                    counters["audit"] += int(cur.rowcount or 0)
        except Exception:
            pass

        if purge_cache:
            counters["cache"] = _delete_discovery_cache_for_entity(conn, raw, "discovery")

        conn.commit()
        try:
            st.cache_data.clear()
        except Exception:
            pass
        _log_map_update(conn, "clean_research_purge", canonical, json.dumps(counters, ensure_ascii=False))
    except Exception as exc:
        counters["error"] = str(exc)[:240]
    return counters



def _static_routes_for_entity(name: Any, limit: int = 12) -> List[Dict[str, Any]]:
    """Devuelve las rutas base/fijas donde participa una entidad.

    Sirve para que Descubrimientos muestre lo que ya existe en el grafo aunque
    la re-búsqueda limpia haya borrado rutas dinámicas/pruebas previas. Estas
    rutas son clicables indirectamente: el botón enfoca el nodo en Radar y allí
    se ven junto con las futuras rutas descubiertas.
    """
    raw = str(name or "").strip()
    if not raw:
        return []
    canonical = _canonical_target_node(raw, set(NODES.keys())) or _canonical_entity_name(raw)
    entity_key = _canonical_entity_key(canonical)
    out: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for src, dst, kind, signal_col, label in ROUTES:
        try:
            src_key = _canonical_entity_key(src)
            dst_key = _canonical_entity_key(dst)
        except Exception:
            src_key, dst_key = str(src).lower(), str(dst).lower()
        if entity_key not in {src_key, dst_key}:
            continue
        peer = dst if entity_key == src_key else src
        direction = "out" if entity_key == src_key else "in"
        rkey = f"{src_key}->{dst_key}:{kind}:{signal_col}"
        if rkey in seen:
            continue
        seen.add(rkey)
        out.append({
            "src": src,
            "dst": dst,
            "peer": peer,
            "direction": direction,
            "kind": kind,
            "signal_col": signal_col,
            "label": label,
            "canonical_node": canonical,
            "fixed": True,
        })
        if len(out) >= limit:
            break
    return out


def _result_future_routes_for_display(result: Dict[str, Any], limit: int = 12) -> List[Dict[str, Any]]:
    """Rutas candidatas/futuras derivadas del resultado actual de Discovery.

    No garantiza que estén verificadas. Solo prepara una lectura clara de lo que
    el resultado propone añadir/actualizar para compararlo con rutas fijas.
    """
    if not isinstance(result, dict):
        return []
    root = _canonical_entity_name(result.get("institution", ""))
    routes: List[Dict[str, Any]] = []
    seen: Set[str] = set()

    def push(dst: Any, source: str = "resultado", kind: str = "candidate") -> None:
        nonlocal routes
        dst_name = _canonical_target_node(dst, set(NODES.keys())) or _canonical_entity_name(dst)
        if not dst_name or dst_name in {"Descubierto", "?"}:
            return
        if _canonical_entity_key(dst_name) == _canonical_entity_key(root):
            return
        key = f"{_canonical_entity_key(root)}->{_canonical_entity_key(dst_name)}:{source}:{kind}"
        if key in seen:
            return
        seen.add(key)
        routes.append({"src": root, "dst": dst_name, "peer": dst_name, "direction": "out", "kind": kind, "source": source})

    for x in result.get("connects_to") or []:
        push(x, "connects_to", "detected")
    for mp in result.get("map_points") or []:
        if isinstance(mp, dict):
            for target in mp.get("connects_to") or []:
                push(target, f"map_point:{mp.get('name','')}", "map_point")
        else:
            push(mp, "map_points", "map_point")
    for p in result.get("partners") or []:
        if isinstance(p, dict):
            push(p.get("name"), "partners", "partner")
        else:
            push(p, "partners", "partner")
    for ft in result.get("future_watch_targets") or []:
        if isinstance(ft, dict):
            push(ft.get("target"), ft.get("source", "future_watch"), ft.get("kind", "future_watch"))
        else:
            push(ft, "future_watch", "future_watch")
    return routes[:limit]

def _set_search_cache(conn: sqlite3.Connection, name: str,
                      result: Dict, search_type: str = "discovery") -> None:
    """Guarda resultado en caché compartida con TTL y aliases normalizados."""
    try:
        canonical_name = _canonical_display_node(name)
        # Guardar también el payload con nombre canónico para que la UI no vuelva a pintar alias.
        if isinstance(result, dict):
            result = dict(result)
            result["institution"] = canonical_name
        key = _cache_key_search(canonical_name, search_type)
        ttl = _CACHE_TTL.get(search_type, 7)
        now = datetime.now(timezone.utc)
        expires = (now + timedelta(days=ttl)).isoformat()
        conn.execute("""
            INSERT OR REPLACE INTO institution_search_cache
            (query, result_json, searched_at, expires_at, hit_count, search_type)
            VALUES (?, ?, ?, ?, COALESCE(
                (SELECT hit_count+1 FROM institution_search_cache WHERE query=?), 1
            ), ?)
        """, (key, json.dumps(result), now.isoformat(), expires, key, search_type))
        # Guardar aliases: cada variante futura apunta al mismo resultado.
        for alias in _cache_alias_keys(str(name or canonical_name), search_type):
            conn.execute("""
                INSERT OR REPLACE INTO search_cache_aliases(alias_key, canonical_query, canonical_name, search_type, created_at, hit_count)
                VALUES(?,?,?,?,?, COALESCE((SELECT hit_count FROM search_cache_aliases WHERE alias_key=?), 0))
            """, (alias, key, canonical_name, search_type, now.isoformat(), alias))
        conn.commit()
        _audit_search_decision(conn, name, search_type, "cache_write", "institution_search_cache", f"key={key}")
    except Exception:
        pass


def _local_knowledge_bundle(conn: sqlite3.Connection, name: str) -> Dict[str, Any]:
    """Busca si ya hay datos internos para una entidad antes de gastar API."""
    out = {"proofs": 0, "dynamic_routes": 0, "route_paths": 0, "examples": []}
    try:
        nk = _norm_key(_canonical_entity_name(name))
        like = f"%{nk.replace(' ', '%')}%"
        # Pruebas fijas.
        rows = conn.execute("""
            SELECT node_a, node_b, confidence, proof_type FROM connection_proofs
            WHERE lower(node_a) LIKE lower(?) OR lower(node_b) LIKE lower(?) OR node_a_key LIKE ? OR node_b_key LIKE ?
            ORDER BY confidence DESC LIMIT 5
        """, (f"%{name}%", f"%{name}%", f"%{nk}%", f"%{nk}%")).fetchall()
        out["proofs"] = len(rows)
        for a,b,c,t in rows:
            out["examples"].append(f"Prueba: {a} ↔ {b} · {float(c or 0)*100:.0f}% · {t}")
        # Rutas dinámicas.
        rows = conn.execute("""
            SELECT src, dst, confidence, label FROM dynamic_routes
            WHERE lower(src) LIKE lower(?) OR lower(dst) LIKE lower(?)
            ORDER BY confidence DESC LIMIT 5
        """, (f"%{name}%", f"%{name}%")).fetchall()
        out["dynamic_routes"] = len(rows)
        for a,b,c,l in rows:
            out["examples"].append(f"Ruta dinámica: {a} → {b} · {float(c or 0)*100:.0f}% · {l}")
        # Rutas A-B históricas: no conocemos esquema siempre, así que intentar columnas comunes.
        try:
            rows = conn.execute("SELECT * FROM route_paths LIMIT 1").fetchall()
            cols = [r[1] for r in conn.execute("PRAGMA table_info(route_paths)").fetchall()]
            if cols:
                text_cols = [c for c in cols if c.lower() in ("src","dst","source","target","origin","destination","node_a","node_b","route","label","name")]
                if text_cols:
                    where = " OR ".join([f"lower({c}) LIKE lower(?)" for c in text_cols])
                    rr = conn.execute(f"SELECT COUNT(*) FROM route_paths WHERE {where}", tuple([f"%{name}%"]*len(text_cols))).fetchone()
                    out["route_paths"] = int(rr[0] or 0) if rr else 0
        except Exception:
            pass
    except Exception:
        pass
    out["total"] = int(out.get("proofs",0)) + int(out.get("dynamic_routes",0)) + int(out.get("route_paths",0))
    out["examples"] = out["examples"][:8]
    return out


def _render_cache_first_status(conn: sqlite3.Connection, query: str, search_type: str = "discovery") -> Dict[str, Any]:
    """Panel visible: indica si la consulta gastará API o saldrá gratis de memoria."""
    query = str(query or "").strip()
    status = {"cache": False, "local_total": 0, "can_skip_api": False}
    if not query:
        return status
    cached = _get_search_cache(conn, query, search_type)
    local = _local_knowledge_bundle(conn, query)
    status["cache"] = bool(cached)
    status["local_total"] = int(local.get("total", 0))
    status["can_skip_api"] = bool(cached) or status["local_total"] > 0
    if cached:
        st.success("✅ Memoria compartida: esta búsqueda ya existe en caché · 0 gasto API")
    elif status["local_total"] > 0:
        st.info(f"🧠 Memoria interna: ya hay {status['local_total']} dato(s) relacionados. Revisa fichas/rutas antes de gastar API.")
        if local.get("examples"):
            with st.expander("Ver datos internos encontrados antes de buscar online", expanded=False):
                for ex in local["examples"]:
                    st.write("• " + ex)
    else:
        st.warning("⚠️ No hay memoria útil para esta entidad. Si lanzas búsqueda online puede consumir API.")
    return status


def _log_map_update(conn: sqlite3.Connection, update_type: str,
                    entity_name: str, details: str = "") -> None:
    """Registra un cambio en el mapa para notificar a otras sesiones."""
    try:
        conn.execute(
            "INSERT INTO map_update_log (update_type, entity_name, details, updated_at) "
            "VALUES (?, ?, ?, ?)",
            (update_type, entity_name, details[:500],
             datetime.now(timezone.utc).isoformat())
        )
        conn.commit()
    except Exception:
        pass


def _get_pending_updates(conn: sqlite3.Connection, since: str) -> int:
    """Devuelve nº de actualizaciones del mapa posteriores a `since`."""
    try:
        if not since:
            return 0
        row = conn.execute(
            "SELECT COUNT(*) FROM map_update_log WHERE updated_at > ?", (since,)
        ).fetchone()
        return int(row[0]) if row else 0
    except Exception:
        return 0


def _get_last_map_update(conn: sqlite3.Connection) -> str:
    """Devuelve timestamp de la última actualización del mapa."""
    try:
        row = conn.execute("SELECT MAX(updated_at) FROM map_update_log").fetchone()
        return row[0] or ""
    except Exception:
        return ""


def _get_map_revision_token(conn: sqlite3.Connection) -> str:
    """Firma ligera de los datos que alimentan los mapas.

    Streamlit/Plotly a veces conserva el componente con la misma key aunque SQLite
    haya cambiado. Esta firma entra en datarevision y en las keys de los 3 mapas.
    """
    try:
        parts = []
        for table, date_col in (
            ("dynamic_nodes", "added_at"),
            ("dynamic_routes", "added_at"),
            ("connection_proofs", "validated_at"),
            ("node_verifications", "verified_at"),
            ("map_update_log", "updated_at"),
            ("route_paths", "day"),
            ("daily_metrics", "day"),
            ("discovered_wallets", "last_seen"),
        ):
            try:
                row = conn.execute(f"SELECT COUNT(*), COALESCE(MAX({date_col}), '') FROM {table}").fetchone()
                parts.append(f"{table}:{int(row[0] or 0)}:{row[1] or ''}")
            except Exception:
                parts.append(f"{table}:0:")
        raw = "|".join(parts)
        return hashlib.sha256(raw.encode("utf-8", "ignore")).hexdigest()[:12]
    except Exception:
        return str(int(_time.time()))


def _session_ai_quota() -> Tuple[int, int]:
    """Devuelve (llamadas_usadas, máximo) para la sesión actual.

    Los admins no tienen límite de búsquedas por sesión. Se devuelve un máximo simbólico
    muy alto solo para evitar dividir/romper la UI antigua.
    """
    used = int(st.session_state.get("ai_calls_session", 0) or 0)
    if _is_admin_unlimited_ai(None):
        return used, 999_999
    return used, _MAX_AI_CALLS_SESSION


def _increment_ai_calls() -> int:
    """Incrementa el contador de llamadas AI de la sesión. Admin no consume quota de sesión."""
    if _is_admin_unlimited_ai(None):
        return int(st.session_state.get("ai_calls_session", 0) or 0)
    n = int(st.session_state.get("ai_calls_session", 0) or 0) + 1
    st.session_state["ai_calls_session"] = n
    return n


# =============================================================================
# PRESUPUESTO API + COLA DE USUARIOS
# =============================================================================
# Costes estimados de reserva. Luego se reconcilian con usage real si Anthropic lo devuelve.
# CostGuard v2: Haiku por defecto + JSON corto + batch limitado.
_CALL_COST: Dict[str, float] = {
    "discovery_fast": 0.035,
    "discovery_deep": 0.160,
    "discovery":      0.035,
    "verification":   0.018,
    "batch_verify":   0.080,
}
_PRICE_PER_TOKEN: Dict[str, Tuple[float, float]] = {
    # USD por token aproximado. Sirve para que el presupuesto no sea a ciegas.
    "haiku":  (1.0 / 1_000_000, 5.0 / 1_000_000),
    "sonnet": (3.0 / 1_000_000, 15.0 / 1_000_000),
}
_WEB_SEARCH_COST = 0.010  # $10 / 1000 búsquedas web aprox.
_BUDGET_WARN_PCT   = 0.80   # avisar al 80% del presupuesto
_BUDGET_LOCK_PCT   = 0.97   # bloquear al 97% (dejar margen)
_SESSION_HEARTBEAT = 90     # segundos hasta considerar sesión inactiva


def _init_budget(conn: sqlite3.Connection) -> None:
    """Inicializa la fila de presupuesto si no existe."""
    try:
        exists = conn.execute("SELECT id FROM api_budget WHERE id=1").fetchone()
        if not exists:
            conn.execute(
                "INSERT INTO api_budget (id, budget_usd, spent_usd, call_count, cache_hits, last_reset, locked) "
                "VALUES (1, 100.0, 0.0, 0, 0, ?, 0)",
                (datetime.now(timezone.utc).isoformat(),)
            )
            conn.commit()
    except Exception:
        pass


def _get_budget(conn: sqlite3.Connection) -> Dict[str, Any]:
    """Lee el estado actual del presupuesto."""
    try:
        _init_budget(conn)
        row = conn.execute(
            "SELECT budget_usd, spent_usd, call_count, cache_hits, last_reset, locked FROM api_budget WHERE id=1"
        ).fetchone()
        if row:
            budget, spent, calls, hits, reset, locked = row
            return {
                "budget": float(budget),
                "spent":  float(spent),
                "calls":  int(calls),
                "hits":   int(hits),
                "reset":  reset,
                "locked": bool(locked),
                "remaining": float(budget) - float(spent),
                "pct": float(spent) / max(float(budget), 0.01),
            }
    except Exception:
        pass
    return {"budget": 100.0, "spent": 0.0, "calls": 0, "hits": 0,
            "reset": "", "locked": False, "remaining": 100.0, "pct": 0.0}


def _charge_budget(conn: sqlite3.Connection, call_type: str = "discovery") -> bool:
    """
    Descuenta el coste estimado del presupuesto.
    Devuelve False si el presupuesto está agotado/bloqueado.
    """
    try:
        _init_budget(conn)
        b = _get_budget(conn)
        cost = _CALL_COST.get(call_type, 0.15)
        budget = max(float(b.get("budget", 100.0)), 0.01)
        spent = float(b.get("spent", 0.0))
        projected_pct = (spent + cost) / budget
        # Bloqueamos antes de pasar el umbral para dejar margen real y evitar gastar de más.
        if b["locked"] or b["pct"] >= _BUDGET_LOCK_PCT or projected_pct >= _BUDGET_LOCK_PCT:
            conn.execute("UPDATE api_budget SET locked=1 WHERE id=1")
            conn.commit()
            return False
        conn.execute(
            "UPDATE api_budget SET spent_usd=spent_usd+?, call_count=call_count+1 WHERE id=1",
            (cost,)
        )
        conn.commit()
        return True
    except Exception:
        return True  # si falla la BD, permitir la llamada


def _estimate_anthropic_cost(data: Dict[str, Any], model: str, fallback_call_type: str = "discovery_fast") -> Optional[float]:
    """Calcula coste aproximado usando usage real de Anthropic cuando está disponible."""
    try:
        usage = data.get("usage") or {}
        if not usage:
            return None
        m = (model or "").lower()
        family = "sonnet" if "sonnet" in m else "haiku"
        in_rate, out_rate = _PRICE_PER_TOKEN.get(family, _PRICE_PER_TOKEN["haiku"])
        input_tokens = int(usage.get("input_tokens") or 0)
        output_tokens = int(usage.get("output_tokens") or 0)
        # Prompt caching: si vienen estos campos, los contabilizamos de forma conservadora.
        cache_creation = int(usage.get("cache_creation_input_tokens") or 0)
        cache_read = int(usage.get("cache_read_input_tokens") or 0)
        server_tool_use = usage.get("server_tool_use") or {}
        web_requests = int(server_tool_use.get("web_search_requests") or 0) if isinstance(server_tool_use, dict) else 0
        token_cost = (input_tokens * in_rate) + (output_tokens * out_rate)
        token_cost += cache_creation * in_rate * 1.25
        token_cost += cache_read * in_rate * 0.10
        web_cost = web_requests * _WEB_SEARCH_COST
        total = token_cost + web_cost
        # Si usage no reporta web_search pero sabemos que hubo herramienta, mantenemos una reserva mínima.
        return max(total, _CALL_COST.get(fallback_call_type, 0.01) * 0.30)
    except Exception:
        return None


def _settle_budget(conn: Optional[sqlite3.Connection], call_type: str, data: Dict[str, Any], model: str) -> None:
    """Ajusta el presupuesto reservado al coste estimado real devuelto por Anthropic."""
    if conn is None:
        return
    try:
        reserved = _CALL_COST.get(call_type, 0.0)
        actual = _estimate_anthropic_cost(data, model, call_type)
        if actual is None:
            return
        delta = actual - reserved
        if abs(delta) < 0.0001:
            return
        conn.execute(
            "UPDATE api_budget SET spent_usd=MAX(0, spent_usd + ?) WHERE id=1",
            (delta,)
        )
        # Si el coste real empuja al límite, bloquear para la siguiente llamada.
        b = _get_budget(conn)
        if b.get("pct", 0.0) >= _BUDGET_LOCK_PCT:
            conn.execute("UPDATE api_budget SET locked=1 WHERE id=1")
        conn.commit()
    except Exception:
        pass


def _refund_budget(conn: Optional[sqlite3.Connection], call_type: str) -> None:
    """Devuelve la reserva si la llamada no llegó a completarse."""
    if conn is None:
        return
    try:
        cost = _CALL_COST.get(call_type, 0.0)
        if cost <= 0:
            return
        conn.execute(
            "UPDATE api_budget SET spent_usd=MAX(0, spent_usd - ?), call_count=MAX(0, call_count-1) WHERE id=1",
            (cost,)
        )
        conn.commit()
    except Exception:
        pass


def _rank_peers_for_cost(peers: List[str]) -> List[str]:
    """Ordena peers para gastar en los más importantes primero."""
    def score(peer: str) -> Tuple[int, str]:
        cn = _canonical_entity_name(peer)
        pri = 999
        for i, p in enumerate(_PRIORITY_PEERS):
            if _norm_key(cn) == _norm_key(p) or _norm_key(p) in _norm_key(cn):
                pri = i
                break
        return (pri, cn)
    seen: Set[str] = set()
    ranked: List[str] = []
    for p in sorted([x for x in peers if str(x).strip()], key=score):
        k = _norm_key(_canonical_entity_name(p))
        if k not in seen:
            seen.add(k)
            ranked.append(p)
    return ranked


def _compact_sources(items: Any, max_items: int = 5) -> List[Any]:
    """Recorta sources/evidence sin duplicar por URL/historia aunque cambie el snippet."""
    if not isinstance(items, list):
        return []
    out: List[Any] = []
    seen: Set[str] = set()
    seen_stories: Set[str] = set()
    seen_titles: Set[str] = set()
    for it in items:
        url = _extract_url_from_any(it)
        title_key = ""
        if isinstance(it, dict):
            title_key = _source_title_key(it.get("title") or it.get("name") or it.get("claim") or it.get("label") or "")
        if title_key and title_key in seen_titles:
            continue
        if url:
            canon = _canonical_source_url(url)
            story = _source_story_key(canon)
            key = canon or story
            if key in seen or (story and story in seen_stories):
                continue
            seen.add(key)
            if story:
                seen_stories.add(story)
            if title_key:
                seen_titles.add(title_key)
            if isinstance(it, dict):
                it = dict(it)
                it["url"] = canon
            else:
                it = canon
        else:
            key = json.dumps(it, sort_keys=True, ensure_ascii=False)[:300] if isinstance(it, dict) else str(it)[:300]
            if key in seen:
                continue
            seen.add(key)
            if title_key:
                seen_titles.add(title_key)
        out.append(it)
        if len(out) >= max_items:
            break
    return out


def _extract_url_from_any(item: Any) -> str:
    """Extrae URL desde strings, sources dict o evidence_items dict."""
    if isinstance(item, dict):
        for key in ("url", "source", "href", "link"):
            val = str(item.get(key, "") or "").strip()
            if val.startswith("http"):
                return val
        return ""
    val = str(item or "").strip()
    return val if val.startswith("http") else ""


def _is_pdf_or_primary_doc_url(url: str, proof_type: str = "") -> bool:
    """True si la fuente parece PDF/documento primario aunque no acabe en .pdf."""
    u = str(url or "").strip().lower()
    if not u:
        return False
    clean = u.split("#", 1)[0].split("?", 1)[0]
    if clean.endswith(".pdf") or ".pdf" in clean:
        return True
    ptype = str(proof_type or "").lower()
    if ptype in {"regulatory_filing_pdf", "contract_pdf"}:
        return True
    if any(h in u for h in _PRIMARY_DOC_HOST_HINTS):
        return ptype in {"", "regulatory_filing", "regulatory_filing_pdf", "contract_pdf", "official_partner", "press_release"}
    return False


def _discovery_document_counts(result: Dict[str, Any]) -> Tuple[int, int]:
    """Cuenta documentos PDF/primarios y fuentes totales visibles en Discovery."""
    seen_urls: Set[str] = set()
    total_sources = 0
    doc_sources = 0

    for item in (result.get("sources") or []):
        url = _extract_url_from_any(item)
        canon = _canonical_source_url(url)
        if not canon or canon in seen_urls:
            continue
        seen_urls.add(canon)
        total_sources += 1
        if _is_pdf_or_primary_doc_url(canon):
            doc_sources += 1

    for item in (result.get("evidence_items") or []):
        url = _extract_url_from_any(item)
        canon = _canonical_source_url(url)
        if not canon or canon in seen_urls:
            continue
        seen_urls.add(canon)
        total_sources += 1
        ptype = str(item.get("type", "") if isinstance(item, dict) else "")
        if _is_pdf_or_primary_doc_url(canon, ptype):
            doc_sources += 1

    return doc_sources, total_sources


def _discovery_pdf_line_html(result: Dict[str, Any]) -> str:
    """Línea siempre visible para Discovery: documentos encontrados o 0."""
    doc_count, total_sources = _discovery_document_counts(result)
    if doc_count:
        return (
            "<div style='color:#3CFF9B;font-size:0.78rem;margin:4px 0 8px;'>"
            f"📄 Documentos PDF/primarios encontrados: <b>{doc_count}</b></div>"
        )
    if total_sources:
        return (
            "<div style='color:#64748B;font-size:0.78rem;margin:4px 0 8px;'>"
            "📄 0 documentos PDF verificables encontrados</div>"
        )
    return (
        "<div style='color:#334155;font-size:0.78rem;margin:4px 0 8px;'>"
        "📄 0 documentos PDF — sin fuentes registradas</div>"
    )




# ── Robustez Discovery: JSON leniente + recuperación de fuentes web ─────────
def _extract_first_balanced_json(raw: str) -> str:
    """Extrae el primer objeto JSON balanceado ignorando llaves dentro de strings."""
    txt = str(raw or "").strip().replace("```json", "").replace("```", "").strip()
    if not txt:
        return ""
    starts = [i for i, ch in enumerate(txt) if ch == "{"]
    for start in starts:
        depth = 0
        in_str = False
        esc = False
        obj_start = start
        for i in range(start, len(txt)):
            ch = txt[i]
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    in_str = False
                continue
            if ch == '"':
                in_str = True
            elif ch == "{":
                if depth == 0:
                    obj_start = i
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    return txt[obj_start:i + 1]
    s = txt.find("{")
    e = txt.rfind("}") + 1
    return txt[s:e] if s != -1 and e > s else ""


def _repair_common_json_issues(js: str) -> str:
    """Repara fallos típicos de LLM: comas finales, comas omitidas, rangos y claves sin comillas."""
    t = str(js or "").strip()
    # Normalizaciones de texto que rompen json.loads.
    t = (t.replace("\ufeff", "")
           .replace("\u00a0", " ")
           .replace("“", '"').replace("”", '"')
           .replace("‘", "'").replace("’", "'"))
    # Quitar comentarios tipo // o /* */ fuera de JSON estricto.
    t = re.sub(r"/\*.*?\*/", "", t, flags=re.DOTALL)
    t = re.sub(r"(^|\n)\s*//.*?(?=\n|$)", r"\1", t)
    # Convertir porcentajes de confianza: "confidence": 68% -> 0.68
    def _pct(m):
        try:
            return f'{m.group(1)}{max(0.0, min(1.0, float(m.group(2))/100.0)):.2f}'
        except Exception:
            return m.group(0)
    t = re.sub(r'("confidence"\s*:\s*)(\d{1,3})\s*%', _pct, t)
    # Convertir rangos numéricos: "confidence": 0.60-0.75 -> 0.675
    def _rng(m):
        try:
            a = float(m.group(2)); b = float(m.group(3))
            mid = max(0.0, min(1.0, (a + b) / 2.0))
            return f'{m.group(1)}{mid:.3f}'
        except Exception:
            return m.group(0)
    t = re.sub(r'("confidence"\s*:\s*)(0?\.\d+|1(?:\.0+)?)\s*[–—-]\s*(0?\.\d+|1(?:\.0+)?)', _rng, t)
    # true/false/null con mayúsculas tipo Python.
    t = re.sub(r"\bTrue\b", "true", t)
    t = re.sub(r"\bFalse\b", "false", t)
    t = re.sub(r"\bNone\b", "null", t)
    # Claves sin comillas: {connected: true, confidence: .68}
    t = re.sub(r'([\{,]\s*)([A-Za-z_][A-Za-z0-9_]*)(\s*:)', r'\1"\2"\3', t)
    # Números empezando por punto: : .68 -> : 0.68
    t = re.sub(r'(:\s*)\.(\d+)', r'\g<1>0.\2', t)
    # Comas finales antes de cerrar objeto/lista.
    t = re.sub(r",\s*([}\]])", r"\1", t)
    # Objetos consecutivos dentro de listas: } {  -> }, {
    t = re.sub(r"}\s*\n\s*{", "},\n{", t)
    # URLs consecutivas en arrays sources: "https://a" "https://b" -> "https://a", "https://b"
    t = re.sub(r'("https?://[^"\n]+")\s*\n\s*("https?://)', r'\1,\n\2', t)
    # Campo siguiente sin coma después de string, número, boolean, null, objeto o lista.
    t = re.sub(r'("|\d|true|false|null|\}|\])\s*\n\s*("[A-Za-z_][A-Za-z0-9_]*"\s*:)', r'\1,\n\2', t)
    # También cuando viene en la misma línea por recorte agresivo.
    t = re.sub(r'(\}|\])\s+("[A-Za-z_][A-Za-z0-9_]*"\s*:)', r'\1, \2', t)
    return t


def _json_safe(obj: Any) -> Any:
    """Convierte objetos de ast.literal_eval a estructuras JSON serializables."""
    if isinstance(obj, dict):
        return {str(k): _json_safe(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_json_safe(v) for v in obj]
    if isinstance(obj, (str, int, float, bool)) or obj is None:
        return obj
    return str(obj)


def _loads_json_or_python_literal(txt: str) -> Optional[Dict[str, Any]]:
    """Intenta cargar JSON estricto y luego diccionario estilo Python/single quotes."""
    if not str(txt or "").strip():
        return None
    try:
        parsed = json.loads(txt)
        if isinstance(parsed, dict):
            return parsed
    except Exception:
        pass
    # Fallback: muchas respuestas vienen como {'connected': True, ...}
    try:
        py_txt = txt
        py_txt = re.sub(r"\btrue\b", "True", py_txt, flags=re.IGNORECASE)
        py_txt = re.sub(r"\bfalse\b", "False", py_txt, flags=re.IGNORECASE)
        py_txt = re.sub(r"\bnull\b", "None", py_txt, flags=re.IGNORECASE)
        parsed = ast.literal_eval(py_txt)
        if isinstance(parsed, dict):
            return _json_safe(parsed)
    except Exception:
        return None
    return None


def _discovery_result_is_structurally_valid(obj: Dict[str, Any]) -> bool:
    """Valida estructura mínima para no cachear basura aunque el JSON parsee."""
    if not isinstance(obj, dict):
        return False
    # Debe contener al menos uno de los campos principales del schema.
    primary = {"connected", "confidence", "summary", "sources", "evidence_items", "connects_to", "route_decisions", "future_watch_targets"}
    return bool(primary.intersection(obj.keys()))


def _loads_discovery_json_lenient(raw: str) -> Dict[str, Any]:
    """Carga JSON del Discovery con JSON Doctor local antes de activar fallback."""
    raw = str(raw or "").strip()
    candidates: List[str] = []
    balanced = _extract_first_balanced_json(raw)
    if balanced:
        candidates.append(balanced)
    s = raw.find("{"); e = raw.rfind("}") + 1
    if s != -1 and e > s:
        candidates.append(raw[s:e])
    candidates.append(raw)

    last_error: Optional[Exception] = None
    seen: Set[str] = set()
    for cand in candidates:
        cand = cand.strip().replace("```json", "").replace("```", "").strip()
        if not cand or cand in seen:
            continue
        seen.add(cand)
        variants = [
            cand,
            _repair_common_json_issues(cand),
            _repair_common_json_issues(_extract_first_balanced_json(cand) or cand),
        ]
        for variant in variants:
            variant = str(variant or "").strip()
            if not variant or variant in seen:
                continue
            seen.add(variant)
            try:
                parsed = _loads_json_or_python_literal(variant)
                if isinstance(parsed, dict) and _discovery_result_is_structurally_valid(parsed):
                    if variant != cand:
                        parsed["_json_auto_repaired"] = True
                    return parsed
            except Exception as exc:
                last_error = exc
    raise ValueError(f"Respuesta AI con JSON inválido tras JSON Doctor local: {last_error}")


def _salvage_discovery_from_text_and_sources(institution_name: str, entity_type: str,
                                             raw_text: str, data: Optional[Dict[str, Any]],
                                             err: Exception) -> Dict[str, Any]:
    """Último recurso: reconstruye un JSON válido desde el texto libre + URLs web_search.

    No inventa pruebas: solo crea un contenedor válido con fuentes, resumen y señales
    que después pasan por _finalize_discovery_result y el gate Proof-First.
    """
    blob = str(raw_text or "")[:4000]
    urls = re.findall(r"https?://[^\s\]\)\}\>'\"]+", blob)
    result = {
        "institution": institution_name,
        "entity_type": entity_type,
        "connected": False,
        "confidence": 0.0,
        "summary": "JSON reconstruido automáticamente desde texto/fuentes porque la respuesta de IA no era parseable. Se aplicará Proof‑First antes de dibujar rutas.",
        "ripple_products": [],
        "layer": _classify_entity(institution_name) if entity_type else "Descubierto",
        "icon": "🧩",
        "connects_to": [],
        "route_kind": "private",
        "sources": urls,
        "wallets": [], "corridors": [], "partners": [], "map_points": [],
        "evidence_items": [], "route_decisions": [], "future_watch_targets": [],
        "_json_salvaged": True,
        "_json_repair_error": str(err)[:160],
    }
    low = (blob + " " + " ".join(urls)).lower()
    # Señales fuertes para Treasury/GTreasury/SWIFT sin afirmar XRP directo.
    if any(x in low for x in ("swift certified partner", "alliance lite2", "swiftref", "treasury.ripple.com", "ripple treasury", "gtreasury", "gt treasury", "gtresaury")):
        result["connected"] = True
        result["confidence"] = 0.62
        result["summary"] = "Reconstruido: detectada ruta de infraestructura SWIFT↔Ripple Treasury/GTreasury; no prueba liquidación XRP directa."
        result["ripple_products"] = ["Ripple Treasury"]
        result["connects_to"] = ["Treasury"]
        result["route_kind"] = "institutional"
    return _merge_discovery_sources(result, data, max_sources=8)

def _extract_anthropic_web_sources(data: Dict[str, Any], max_items: int = 10) -> List[Dict[str, str]]:
    """Recupera URLs/títulos de bloques web_search y citations aunque el JSON final venga mal formado."""
    found: List[Dict[str, str]] = []
    seen: Set[str] = set()
    seen_titles: Set[str] = set()

    def add(url: Any, title: Any = "") -> None:
        u = _canonical_source_url(str(url or "").strip())
        if not u or not u.startswith("http") or u in seen:
            return
        tkey = _source_title_key(title)
        if tkey and tkey in seen_titles:
            return
        seen.add(u)
        if tkey:
            seen_titles.add(tkey)
        found.append({"url": u, "title": str(title or "Fuente web").strip()[:180]})

    def walk(obj: Any) -> None:
        if len(found) >= max_items:
            return
        if isinstance(obj, dict):
            url = obj.get("url") or obj.get("source_url") or obj.get("href") or obj.get("link") or obj.get("uri")
            title = obj.get("title") or obj.get("name") or obj.get("label") or obj.get("text") or ""
            if url:
                add(url, title)
            for v in obj.values():
                walk(v)
        elif isinstance(obj, list):
            for v in obj:
                walk(v)

    try:
        walk(data.get("content", []))
    except Exception:
        pass
    return _compact_sources(found, max_items)


def _merge_discovery_sources(result: Dict[str, Any], data: Optional[Dict[str, Any]] = None, max_sources: int = 8) -> Dict[str, Any]:
    """Normaliza sources/evidence y añade URLs recuperadas desde web_search/citations."""
    result = dict(result or {})
    sources_raw: List[Any] = list(result.get("sources") or [])
    evidence_raw: List[Any] = list(result.get("evidence_items") or [])

    # Las URLs de evidence también deben contar como sources visibles.
    for ev in evidence_raw:
        u = _extract_url_from_any(ev)
        if u:
            sources_raw.append(u)

    if data:
        for item in _extract_anthropic_web_sources(data, max_sources):
            u = _extract_url_from_any(item)
            if u:
                # Importante: una URL recuperada de web_search NO es una prueba de conexión.
                # Se muestra como fuente para revisión, pero no se guarda en evidence_items.
                sources_raw.append(item if isinstance(item, dict) else u)

    # Reparar cachés antiguos: mover "fuentes recuperadas automáticamente" fuera de pruebas.
    cleaned_evidence: List[Any] = []
    for ev in evidence_raw:
        if _is_auto_recovered_evidence(ev):
            u = _extract_url_from_any(ev)
            if u:
                sources_raw.append(ev)
            continue
        cleaned_evidence.append(ev)
    evidence_raw = cleaned_evidence

    # sources debe ser lista de URLs string para que la UI las pinte bien.
    clean_sources: List[str] = []
    for item in _compact_sources(sources_raw, max_sources):
        u = _extract_url_from_any(item)
        if u:
            clean_sources.append(_canonical_source_url(u))
    result["sources"] = _compact_sources(clean_sources, max_sources)
    result["evidence_items"] = _compact_sources(evidence_raw, max_sources)
    return result


def _fallback_discovery_from_partial_response(institution_name: str, entity_type: str,
                                              data: Optional[Dict[str, Any]], err: Exception) -> Dict[str, Any]:
    """No devuelve 0 fuentes si la API buscó pero el JSON final vino roto."""
    result = {
        "institution": institution_name,
        "entity_type": entity_type,
        "connected": False,
        "confidence": 0.0,
        "summary": f"La búsqueda respondió, pero el JSON vino mal formado. Recuperé fuentes web para revisión. JSON Doctor no pudo reconstruir estructura suficiente. Error técnico: {str(err)[:120]}",
        "ripple_products": [], "layer": _classify_entity(institution_name) if entity_type else "Descubierto", "icon": "🧩",
        "connects_to": [], "route_kind": "private", "sources": [],
        "wallets": [], "corridors": [], "partners": [], "map_points": [], "evidence_items": [],
        "_json_recovered": True,
    }
    return _merge_discovery_sources(result, data, max_sources=8)


def _enrich_discovery_with_chain_seeds(result: Dict[str, Any], institution_name: str) -> Dict[str, Any]:
    """
    Barrido infra-wide: corrige el falso 0 cuando la conexión no es XRP directa
    pero sí hay infraestructura documentada en capas como Treasury/SWIFT,
    ledger permissioned, DEX/AMM o puntos on-chain a vigilar.

    Regla: lo documentado se puede dibujar; lo hipotético/on-chain futuro solo se
    muestra como watch/future, no como prueba confirmada.
    """
    result = dict(result or {})
    canonical = _canonical_entity_name(institution_name)
    key = _canonical_entity_key(canonical)
    blob = _infra_blob(result, institution_name)

    is_swift_context = (key == _canonical_entity_key("SWIFT") or " swift " in f" {blob} " or "swift" == blob)
    is_treasury_context = any(x in blob for x in ("ripple treasury", "gtreasury", "gt treasury", "gtresaury", "gtresury", "gtresauri", "swift certified partner", "alliance lite2", "swiftref", "treasury ripple com company partners"))

    # 1) SWIFT ↔ Ripple Treasury / GTreasury: conexión infra documentada, no XRP settlement.
    if is_swift_context or is_treasury_context:
        treasury_url = "https://treasury.ripple.com/company/partners"
        claim = (
            "Ripple Treasury indica que forma parte del SWIFT Certified Partner Program "
            "y ofrece conectividad bancaria global, SWIFT Alliance Lite2 y SWIFTRef. "
            "Esto prueba ruta de infraestructura Treasury/SWIFT, no liquidación XRP directa."
        )
        _result_add_evidence(
            result,
            title="Ripple Treasury — SWIFT Certified Partner Program",
            claim=claim,
            url=treasury_url,
            target="Treasury",
            evidence_type="official_partner",
            confidence=0.72,
        )
        _result_add_route_decision(
            result, to="Treasury", claim=claim, url=treasury_url,
            evidence_type="official_partner", confidence=0.72, kind="institutional", draw_on_map=True,
        )
        _result_add_connect_target(result, "Treasury")
        products = list(result.get("ripple_products") or [])
        if "Ripple Treasury" not in products:
            products.append("Ripple Treasury")
        result["ripple_products"] = products
        result["connected"] = True
        try:
            result["confidence"] = max(float(result.get("confidence", 0) or 0), 0.68)
        except Exception:
            result["confidence"] = 0.68
        result["route_kind"] = result.get("route_kind") or "institutional"
        if not result.get("summary") or "JSON" in str(result.get("summary")):
            result["summary"] = "Conexión directa SWIFT→XRP no confirmada; sí hay ruta infra documentada SWIFT↔Ripple Treasury/GTreasury."
        elif "Treasury" not in str(result.get("summary")):
            result["summary"] = (str(result.get("summary", "")).rstrip(" .") + ". Además: ruta infra SWIFT↔Ripple Treasury/GTreasury documentada.")[:600]

        # 2) SWIFT shared ledger / permissioned on-chain: ruta futura a vigilar.
        swift_ledger_url = "https://www.swift.com/news-events/news/swift-add-blockchain-based-ledger"
        swift_mvp_url = "https://www.swift.com/news-events/news/swifts-blockchain-based-shared-ledger-progresses-mvp-implementation"
        ledger_claim = (
            "Swift anunció un shared ledger/blockchain para pagos 24/7 e interoperabilidad con sistemas existentes y emergentes. "
            "Se clasifica como watch permissioned/tokenised infra, no como XRPL/DEX confirmado."
        )
        _result_add_evidence(
            result, title="Swift blockchain-based shared ledger", claim=ledger_claim,
            url=swift_ledger_url, target="Topology Engine", evidence_type="primary_source", confidence=0.62,
        )
        _result_add_route_decision(
            result, to="Topology Engine", claim=ledger_claim, url=swift_ledger_url,
            evidence_type="primary_source", confidence=0.62, kind="watch", draw_on_map=True,
        )
        _result_add_source(result, swift_mvp_url)
        _result_add_future_watch_target(result, "Permissioned DEX", reason="Vigilar si el ledger permissioned de Swift deja puente con redes/tokenised value compatibles.", source="swift_ledger", kind="permissioned_onchain_watch")
        _result_add_future_watch_target(result, "DEX/AMM", reason="Vigilar si aparece huella pública XRPL: AMM, DEX, trustlines, offers o gateways.", source="xrpl_public_edge", kind="dex_amm_watch")
        _result_add_future_watch_target(result, "XRPL", reason="No confirmado: solo se activaría con TX, trustline, wallet, gateway o fuente oficial XRPL/Ripple.", source="xrpl_public_edge", kind="onchain_watch")
        _result_add_future_watch_target(result, "RLUSD", reason="No confirmado: vigilar emisión/movimientos/trustlines RLUSD asociados a gateways o tesorería.", source="rlusd_public_edge", kind="stablecoin_watch")

        # Deducción transitiva visible: SWIFT no se conecta a XRPL por prueba directa,
        # pero si ya existe prueba SWIFT↔Treasury/GTreasury, el mapa debe enseñar los
        # bordes Ripple que habría que vigilar. Se dibujan como deductive_watch.
        transitive_url = treasury_url
        transitive_targets = {
            "Permissioned DEX": (0.50, "SWIFT→Treasury/GTreasury deja una ruta institucional permissioned a vigilar. No prueba uso directo de XRP."),
            "DEX/AMM": (0.46, "SWIFT→Treasury/GTreasury conecta con una zona de liquidez XRPL/DEX a vigilar. No prueba operación on-chain."),
            "XRPL": (0.48, "SWIFT→Treasury/GTreasury conecta indirectamente con el borde XRPL que debe vigilarse. No prueba liquidación SWIFT en XRPL."),
            "RLUSD": (0.45, "SWIFT→Treasury/GTreasury conecta indirectamente con el borde RLUSD/stablecoin a vigilar. No prueba uso directo de RLUSD."),
        }
        for _target, (_c, _claim) in transitive_targets.items():
            _result_add_route_decision(
                result, to=_target, claim=_claim, url=transitive_url,
                evidence_type="deductive_watch", confidence=_c, kind="deductive_watch", draw_on_map=True,
            )

    return result


def _finalize_discovery_result(result: Dict[str, Any], institution_name: str, entity_type: str,
                               data: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Aplica defaults, normaliza fuentes y enriquece rutas semilla antes de pintar/cachar."""
    result = dict(result or {})
    result["institution"] = _canonical_display_node(institution_name)
    result["entity_type"] = entity_type
    defaults = {
        "connected": False, "confidence": 0.0, "summary": "", "ripple_products": [],
        "layer": "Descubierto", "icon": "?", "connects_to": [], "route_kind": "private",
        "sources": [], "wallets": [], "corridors": [], "partners": [], "map_points": [], "evidence_items": [],
    }
    for k, v in defaults.items():
        result.setdefault(k, v)
    try:
        result["confidence"] = max(0.0, min(1.0, float(result.get("confidence", 0) or 0)))
    except Exception:
        result["confidence"] = 0.0
    if isinstance(result.get("summary"), str) and len(result["summary"]) > 600:
        result["summary"] = result["summary"][:600].rstrip() + "…"
    result = _merge_discovery_sources(result, data, max_sources=8)
    # Si el JSON vino roto, no dejamos "Confianza 0" cuando sí hubo búsqueda y fuentes.
    # Esta cifra es una confianza de investigación mínima, no una prueba de conexión.
    if result.get("_json_recovered") and not result.get("connected") and float(result.get("confidence", 0) or 0) <= 0:
        result["confidence"] = _fallback_confidence_from_sources(result)
        result["_confidence_is_research_quality"] = True
    result["evidence_items"] = _valid_discovery_evidence_items(result)
    result = _enrich_discovery_with_chain_seeds(result, institution_name)
    # Si un caché viejo venía marcado como JSON roto pero el enriquecimiento/semillas
    # ya lo convirtió en estructura útil, no lo pintamos como error: queda como reconstruido.
    if result.get("_json_recovered") and (result.get("connected") or result.get("route_decisions") or result.get("evidence_items")):
        result["_json_salvaged"] = True
        result.pop("_json_recovered", None)
    return result

def _resolve_native_search_identity(entity: str) -> Tuple[str, Optional[str], bool]:
    """Devuelve (script, nombre_nativo, usar_bloque_nativo) para ASCII y no-ASCII."""
    raw = str(entity or "").strip()
    has_non_ascii = any(ord(c) > 127 for c in raw)
    if has_non_ascii:
        return _detect_script(raw), None, True
    low = raw.lower()
    for pattern, (script, native_name) in _KNOWN_NATIVE_NAMES.items():
        if pattern in low:
            return script, native_name, True
    return "en", None, False


def _record_cache_hit(conn: sqlite3.Connection) -> None:
    """Registra un cache hit en el presupuesto (sin coste)."""
    try:
        conn.execute("UPDATE api_budget SET cache_hits=cache_hits+1 WHERE id=1")
        conn.commit()
    except Exception:
        pass


def _session_id() -> str:
    """ID único de sesión (generado una vez por sesión Streamlit)."""
    if "session_uid" not in st.session_state:
        import secrets
        st.session_state["session_uid"] = secrets.token_hex(8)
    return st.session_state["session_uid"]


def _heartbeat(conn: sqlite3.Connection, status: str = "idle") -> None:
    """Registra/actualiza la sesión activa. Llámalo en cada render del panel."""
    try:
        sid = _session_id()
        now = datetime.now(timezone.utc).isoformat()
        conn.execute("""
            INSERT OR REPLACE INTO active_sessions (session_id, started_at, heartbeat, status)
            VALUES (?, COALESCE((SELECT started_at FROM active_sessions WHERE session_id=?), ?), ?, ?)
        """, (sid, sid, now, now, status))
        # Limpiar sesiones inactivas
        cutoff = (datetime.now(timezone.utc) - timedelta(seconds=_SESSION_HEARTBEAT * 2)).isoformat()
        conn.execute("DELETE FROM active_sessions WHERE heartbeat < ?", (cutoff,))
        conn.commit()
    except Exception:
        pass


def _active_users(conn: sqlite3.Connection) -> Tuple[int, int]:
    """Devuelve (total_activos, usando_ai_ahora)."""
    try:
        cutoff = (datetime.now(timezone.utc) - timedelta(seconds=_SESSION_HEARTBEAT)).isoformat()
        total = conn.execute(
            "SELECT COUNT(*) FROM active_sessions WHERE heartbeat > ?", (cutoff,)
        ).fetchone()[0]
        ai_now = conn.execute(
            "SELECT COUNT(*) FROM active_sessions WHERE heartbeat > ? AND status='searching'",
            (cutoff,)
        ).fetchone()[0]
        return int(total), int(ai_now)
    except Exception:
        return 1, 0


def _queue_position(conn: sqlite3.Connection) -> int:
    """Posición del usuario actual en la cola de búsquedas AI (0 = libre)."""
    try:
        sid = _session_id()
        cutoff = (datetime.now(timezone.utc) - timedelta(seconds=_SESSION_HEARTBEAT)).isoformat()
        # Cuenta sesiones con status='searching' que empezaron ANTES que la nuestra
        my_start = conn.execute(
            "SELECT started_at FROM active_sessions WHERE session_id=?", (sid,)
        ).fetchone()
        if not my_start:
            return 0
        pos = conn.execute(
            "SELECT COUNT(*) FROM active_sessions "
            "WHERE status='searching' AND heartbeat > ? AND session_id != ? AND started_at <= ?",
            (cutoff, sid, my_start[0])
        ).fetchone()[0]
        return int(pos)
    except Exception:
        return 0


def render_budget_bar(conn: sqlite3.Connection) -> None:
    """Muestra la barra de presupuesto API en el sidebar o panel."""
    b = _get_budget(conn)
    spent    = b["spent"]
    budget   = b["budget"]
    remaining = b["remaining"]
    pct       = b["pct"]
    calls     = b["calls"]
    hits      = b["hits"]

    if pct >= _BUDGET_LOCK_PCT:
        color = "#EF4444"
        label = "❌ PRESUPUESTO AGOTADO — Solo resultados cacheados disponibles"
    elif pct >= _BUDGET_WARN_PCT:
        color = "#F59E0B"
        label = f"⚠️ Presupuesto bajo — quedan ${remaining:.2f}"
    else:
        color = "#22C55E"
        label = f"✅ ${remaining:.2f} disponibles de ${budget:.0f}"

    bar_pct = min(pct * 100, 100)
    st.markdown(f"""
<div style='background:#1E293B;border-radius:10px;padding:10px 14px;margin-bottom:8px;'>
  <div style='display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;'>
    <span style='font-size:0.82rem;color:#94A3B8;'>💰 Presupuesto API</span>
    <span style='font-size:0.82rem;font-weight:700;color:{color};'>{label}</span>
  </div>
  <div style='background:#0B1220;border-radius:6px;height:10px;overflow:hidden;'>
    <div style='background:{color};width:{bar_pct:.1f}%;height:100%;border-radius:6px;
                transition:width 0.5s;'></div>
  </div>
  <div style='display:flex;justify-content:space-between;margin-top:5px;'>
    <span style='font-size:0.75rem;color:#64748B;'>${spent:.2f} gastados · {calls} búsquedas nuevas · CostGuard v2</span>
    <span style='font-size:0.75rem;color:#22C55E;'>{hits} desde caché (gratis)</span>
  </div>
</div>
""", unsafe_allow_html=True)


def _is_current_session_searching(conn: sqlite3.Connection) -> bool:
    """Indica si la sesión actual está marcada como búsqueda AI activa."""
    try:
        sid = _session_id()
        row = conn.execute(
            "SELECT status FROM active_sessions WHERE session_id=?", (sid,)
        ).fetchone()
        return bool(row and row[0] == "searching")
    except Exception:
        return False


def render_queue_status(conn: sqlite3.Connection) -> None:
    """Muestra usuarios activos y número aproximado en la fila AI."""
    try:
        total, ai_now = _active_users(conn)
        if _is_admin_unlimited_ai(conn):
            st.caption(f"👑 Admin activo: búsquedas ilimitadas de sesión · usuarios activos: {total} · cola pública ignorada")
            return
        searching = _is_current_session_searching(conn)
        if searching:
            pos = max(1, _queue_position(conn) + 1)
            st.info(f"⏳ Tu búsqueda AI está en curso · estás en la posición #{pos} de la fila · usuarios activos: {total}")
        elif ai_now > 0:
            st.warning(f"👥 Búsquedas AI activas ahora: {ai_now} · si lanzas una búsqueda, entrarás aprox. como #{ai_now + 1} en la fila")
        else:
            st.caption(f"👥 Usuarios activos: {total} · fila AI libre ahora: serías #1 si lanzas una búsqueda")
    except Exception:
        pass




def _public_nickname_value() -> str:
    return str(st.session_state.get("community_nickname", "") or "").strip()


def _public_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _public_queue_cleanup(conn: sqlite3.Connection) -> None:
    """Limpia cola AI vieja para que un navegador cerrado no bloquee la beta."""
    try:
        cutoff = (datetime.now(timezone.utc) - timedelta(minutes=12)).isoformat()
        conn.execute("DELETE FROM ai_waiting_queue WHERE updated_at < ?", (cutoff,))
        conn.commit()
    except Exception:
        pass


def _public_queue_position(conn: sqlite3.Connection, session_id: Optional[str] = None) -> int:
    """Posición 1-based del usuario en la cola AI. 0 si no está en cola.

    Admin no entra en cola pública.
    """
    if _is_admin_unlimited_ai(conn):
        return 0
    try:
        _public_queue_cleanup(conn)
        sid = session_id or _session_id()
        rows = conn.execute(
            "SELECT session_id FROM ai_waiting_queue WHERE status='queued' ORDER BY created_at ASC"
        ).fetchall()
        ids = [str(r[0]) for r in rows]
        return ids.index(sid) + 1 if sid in ids else 0
    except Exception:
        return 0


def _public_queue_total(conn: sqlite3.Connection) -> int:
    try:
        _public_queue_cleanup(conn)
        return int(conn.execute("SELECT COUNT(*) FROM ai_waiting_queue WHERE status='queued'").fetchone()[0])
    except Exception:
        return 0


def _public_enqueue_ai(conn: sqlite3.Connection, query: str) -> int:
    """Mete la sesión actual en cola AI y devuelve su posición.

    Admin ejecuta directo y no ocupa cola pública.
    """
    if _is_admin_unlimited_ai(conn):
        return 0
    try:
        sid = _session_id()
        nick = _public_nickname_value() or "Visitante"
        now = _public_now_iso()
        conn.execute(
            "INSERT OR REPLACE INTO ai_waiting_queue (session_id,nickname,query,status,created_at,updated_at) "
            "VALUES (?, ?, ?, 'queued', COALESCE((SELECT created_at FROM ai_waiting_queue WHERE session_id=?), ?), ?)",
            (sid, nick, query, sid, now, now),
        )
        conn.commit()
        return _public_queue_position(conn, sid)
    except Exception:
        return 0


def _public_can_run_ai_now(conn: sqlite3.Connection) -> bool:
    """Solo deja ejecutar a quien está primero, no hay otra búsqueda AI y tiene cupo investigador.

    Admin bypass: sin límite de cupo público, sin cola y sin bloqueo por otra sesión.
    """
    try:
        if _is_admin_unlimited_ai(conn):
            return True
        if not _can_current_user_investigate(conn):
            return False
        _, ai_now = _active_users(conn)
        if ai_now > 0 and not _is_current_session_searching(conn):
            return False
        pos = _public_queue_position(conn)
        return pos in (0, 1)
    except Exception:
        return bool(st.session_state.get("rrp_can_investigate", False))


def _public_finish_ai(conn: sqlite3.Connection) -> None:
    try:
        conn.execute("DELETE FROM ai_waiting_queue WHERE session_id=?", (_session_id(),))
        conn.commit()
    except Exception:
        pass


