def render_shared_live_sync(conn: sqlite3.Connection) -> None:
    """Sincronización multiusuario opcional.

    v116 cambia la filosofía: por defecto NO se refresca toda la app cada pocos
    segundos, porque eso corta música, formularios, scroll y fichas abiertas.

    Streamlit no tiene push real desde SQLite a navegador. Para saber que otro
    usuario guardó datos hacen falta una de estas dos cosas:
    1) interacción normal del usuario, o
    2) polling/auto-refresh.

    Por seguridad UX, el polling queda desactivado salvo que el admin lo active
    en la sesión. Si se activa, solo muestra aviso de cambios; no fuerza rerun
    infinito ni aplica cambios sin que el usuario acepte.
    """
    polling_enabled = bool(st.session_state.get("rrp_live_polling_enabled", ENABLE_SHARED_LIVE_SYNC))
    if not polling_enabled:
        return
    try:
        current_rev = _get_map_revision_token(conn)
        last_rev = st.session_state.get("rrp_live_last_revision", "")
        if last_rev and current_rev != last_rev:
            st.session_state["rrp_live_seen_change"] = True
        st.session_state["rrp_live_last_revision"] = current_rev
    except Exception:
        pass
    try:
        if st_autorefresh is not None:
            st_autorefresh(
                interval=int(max(30, LIVE_SHARED_REFRESH_SECONDS) * 1000),
                key="rrp_shared_live_sync_tick_v116_quiet",
            )
    except Exception:
        pass


def _consume_apply_updates_query(conn: sqlite3.Connection) -> bool:
    """Gestiona el enlace ?rrp_apply_updates=1 del aviso flotante."""
    try:
        qp = st.query_params
        if str(qp.get("rrp_apply_updates", "")) == "1":
            last = _get_last_map_update(conn)
            if last:
                st.session_state["map_last_seen_global"] = last
                st.session_state["map_last_seen"] = last
            try:
                del st.query_params["rrp_apply_updates"]
            except Exception:
                st.query_params.clear()
            st.toast("✅ Cambios del radar cargados.")
            return True
    except Exception:
        pass
    return False


def _apply_shared_updates_now(conn: sqlite3.Connection) -> None:
    """Aplica los cambios compartidos en la pestaña actual, sin enlaces externos."""
    try:
        last = _get_last_map_update(conn)
        if last:
            st.session_state["map_last_seen_global"] = last
            st.session_state["map_last_seen"] = last
        st.session_state["rrp_pending_shared_updates"] = 0
        st.session_state["rrp_live_seen_change"] = False
        st.toast("✅ Cambios del radar aplicados en esta pestaña.")
    except Exception:
        pass


def render_global_update_notice(conn: sqlite3.Connection) -> None:
    """
    Aviso de cambios compartidos sin abrir ventanas nuevas.

    v119:
    - Se elimina el <a href="?rrp_apply_updates=1"> que en algunos navegadores/
      embeds/Cloudflare abría una pestaña nueva.
    - Se usa un botón Streamlit real. Al pulsarlo, el estado se actualiza en la
      sesión actual y se fuerza un rerun controlado de la misma pestaña.
    """
    try:
        # Compatibilidad: si alguien entra con el query param antiguo, lo consume
        # sin abrir nada y vuelve a la URL limpia.
        if _consume_apply_updates_query(conn):
            try:
                st.rerun()
            except Exception:
                pass
            return

        last = _get_last_map_update(conn)
        seen = st.session_state.get("map_last_seen_global", "")
        if not last:
            return
        if not seen:
            st.session_state["map_last_seen_global"] = last
            st.session_state["map_last_seen"] = last
            return

        pending = _get_pending_updates(conn, seen)
        if pending <= 0:
            st.session_state["rrp_pending_shared_updates"] = 0
            return

        st.session_state["rrp_pending_shared_updates"] = pending

        # CSS ligero para que el aviso se vea como tarjeta flotante, pero el botón
        # es Streamlit nativo; no hay links, no hay target=_blank, no hay ventana nueva.
        if ENABLE_FLOATING_UPDATE_NOTICE:
            st.markdown(f"""
<style>
.rrp-update-card-v119 {{
  border: 1px solid rgba(34,211,238,.45);
  background: rgba(15,23,42,.92);
  color: #E2E8F0;
  border-radius: 18px;
  padding: 12px 14px;
  margin: 8px 0 10px 0;
  box-shadow: 0 10px 34px rgba(0,0,0,.22);
}}
.rrp-update-card-v119 b {{ color:#67E8F9; }}
.rrp-update-card-v119 small {{ display:block; color:#94A3B8; margin-top:4px; line-height:1.3; }}
</style>
<div class="rrp-update-card-v119">
  <div>🔔 <b>{pending} dato(s) nuevos detectados</b></div>
  <div style="font-size:.88rem;margin-top:4px">Hay rutas/pruebas/mapas actualizados por otra sesión.</div>
  <small>No se aplica solo para no cortar música, formularios ni investigación. Pulsa el botón de abajo para actualizar esta misma pestaña.</small>
</div>
""", unsafe_allow_html=True)
        else:
            st.info(f"🔔 {pending} cambios compartidos pendientes. Aplica cambios cuando quieras.")

        if st.button(
            "🔄 Aplicar cambios en esta pestaña",
            key=f"rrp_apply_shared_updates_current_tab_{pending}",
            use_container_width=True,
        ):
            _apply_shared_updates_now(conn)
            try:
                st.rerun()
            except Exception:
                pass
    except Exception:
        pass

def _diagnose_api_key() -> Dict[str, Any]:
    """
    Diagnóstico completo de la API key de Anthropic.
    Devuelve dict con: source, key_preview, format_ok, reachable, status_code,
    error_type, error_msg, model_ok, suggestion.
    """
    result: Dict[str, Any] = {
        "source": "no encontrada",
        "key_preview": "",
        "format_ok": False,
        "reachable": False,
        "status_code": None,
        "error_type": "",
        "error_msg": "",
        "model_ok": False,
        "suggestion": "",
    }

    key = _get_api_key()
    if not key:
        result["suggestion"] = "No hay API key configurada. Ve a Setup y pégala en 'Sesión temporal' o crea el archivo .env."
        return result

    result["key_preview"] = f"sk-ant-...{key[-8:]}" if len(key) > 12 else "***"

    # Detectar fuente
    if _os.environ.get("ANTHROPIC_API_KEY", "").strip():
        result["source"] = "variable de entorno"
    elif _os.path.isfile(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), ".env")):
        result["source"] = "archivo .env"
    elif st.session_state.get("_manual_api_key"):
        result["source"] = "sesión manual (Setup)"
    else:
        result["source"] = "Streamlit secrets"

    # Validar formato básico sk-ant-...
    result["format_ok"] = key.startswith("sk-ant-") and len(key) > 30

    # Test mínimo a la API — ping con 1 token
    try:
        _test_payload = {
            "model": ANTHROPIC_MODEL_FAST,
            "max_tokens": 1,
            "messages": [{"role": "user", "content": "ping"}],
        }
        _headers = {
            "x-api-key": key,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json",
        }
        resp = requests.post(ANTHROPIC_API_URL, json=_test_payload, headers=_headers, timeout=15)
        result["status_code"] = resp.status_code
        result["reachable"] = True

        if resp.status_code == 200:
            result["model_ok"] = True
            result["suggestion"] = "✅ API key válida y modelo accesible."
        else:
            _body = {}
            try:
                _body = resp.json()
            except Exception:
                pass
            _etype = _body.get("error", {}).get("type", "")
            _emsg  = _body.get("error", {}).get("message", resp.text[:300])
            result["error_type"] = _etype
            result["error_msg"]  = _emsg

            if resp.status_code == 401:
                if "invalid_api_key" in _etype or "invalid x-api-key" in _emsg.lower():
                    result["suggestion"] = (
                        "❌ La key existe pero es inválida o ha sido revocada. "
                        "Ve a console.anthropic.com → API Keys y genera una nueva."
                    )
                else:
                    result["suggestion"] = "❌ Error 401. Comprueba que pegaste la key completa sin espacios."
            elif resp.status_code == 403:
                result["suggestion"] = "❌ Acceso denegado (403). La key no tiene permisos para este modelo o workspace."
            elif resp.status_code == 429:
                result["suggestion"] = "⏳ Rate limit (429). La key funciona pero hay demasiadas solicitudes. Espera unos segundos."
            elif resp.status_code == 400:
                # 400 con ping mínimo puede ser normal si el modelo requiere más tokens
                result["model_ok"] = True
                result["suggestion"] = "⚠️ La key parece válida (400 en ping mínimo es normal). Intenta buscar."
            else:
                result["suggestion"] = f"Error HTTP {resp.status_code}: {_emsg[:200]}"
    except requests.exceptions.ConnectionError:
        result["error_msg"] = "No se puede conectar a api.anthropic.com. Comprueba tu conexión a internet."
        result["suggestion"] = "Sin conexión a internet o firewall bloqueando api.anthropic.com."
    except requests.exceptions.Timeout:
        result["error_msg"] = "Timeout — la API tardó más de 15s en responder."
        result["suggestion"] = "Conexión lenta o Anthropic temporalmente sobrecargado. Inténtalo de nuevo."
    except Exception as _ex:
        result["error_msg"] = str(_ex)[:300]
        result["suggestion"] = f"Error inesperado: {_ex}"

    return result


def render_api_diagnostics() -> None:
    """Panel de diagnóstico de API key — se muestra en Setup."""
    st.markdown("### 🩺 Diagnóstico de API key")
    with st.spinner("Probando conexión con Anthropic…"):
        d = _diagnose_api_key()

    rows = [
        ("Fuente detectada",    d["source"]),
        ("Key (preview)",       d["key_preview"] or "—"),
        ("Formato válido",      "✅ Sí" if d["format_ok"] else "❌ No (debe empezar por sk-ant-)"),
        ("Conectividad",        "✅ Alcanzable" if d["reachable"] else "❌ Sin respuesta"),
        ("HTTP status",         str(d["status_code"]) if d["status_code"] else "—"),
        ("Modelo accesible",    "✅ Sí" if d["model_ok"] else ("⚠️ Ver diagnóstico" if d["reachable"] else "—")),
        ("Tipo de error",       d["error_type"] or "—"),
        ("Mensaje de error",    d["error_msg"] or "—"),
    ]
    _diag_md = "| Campo | Valor |\n|---|---|\n"
    for _k, _v in rows:
        _diag_md += f"| {_k} | `{_v}` |\n"
    st.markdown(_diag_md)

    # Diagnóstico principal
    sug = d.get("suggestion", "")
    if d["model_ok"]:
        st.success(sug)
    elif d["status_code"] == 429:
        st.warning(sug)
    elif sug:
        st.error(sug)

    if d["status_code"] == 401:
        st.markdown("""
**Pasos para generar una nueva key:**
1. Ve a [console.anthropic.com/settings/keys](https://console.anthropic.com/settings/keys)
2. Click **Create Key**
3. Copia la key completa (`sk-ant-api03-...`)
4. Pégala en **Setup → Sesión temporal** o en el archivo `.env`
""")


