# Etiquetas de certeza según puntuación combinada
def _cert_label(score: float) -> tuple:
    """Devuelve (etiqueta, color) según nivel de certeza."""
    if score >= 0.88:  return ("✅ Conexión confirmada",      "#3CFF9B")
    if score >= 0.70:  return ("🟡 Conexión probable",        "#FB923C")
    if score >= 0.45:  return ("🔶 Conexión posible",         "#F59E0B")
    if score >= 0.20:  return ("⚠️ Evidencia débil",          "#FF5A67")
    return              ("❌ Sin evidencia verificable",       "#64748B")

def _combine_evidence_score(proofs: List[Dict]) -> float:
    """
    Combina pruebas con penalización por calidad de fuente.
    v113 evita que tres noticias menores o una wallet genérica eleven una conexión
    a nivel “confirmado”.
    """
    if not proofs:
        return 0.0
    weighted: List[float] = []
    for p in proofs:
        if not isinstance(p, dict):
            continue
        base = EVIDENCE_SCORES.get(str(p.get("type", "") or ""), 0.0)
        if p.get("onchain"):
            mult = 1.0 if str(p.get("type", "")).lower() in PAIR_ONCHAIN_TYPES else 0.0
        elif p.get("internet"):
            mult = _proof_quality_multiplier(p)
        else:
            mult = 0.0
        s = max(0.0, min(0.99, float(base) * float(mult)))
        if s > 0:
            weighted.append(s)
    if not weighted:
        return 0.0
    combined = 1.0
    for s in sorted(weighted, reverse=True):
        combined *= (1.0 - s)
    score = 1.0 - combined
    score = _cap_score_by_source_mix(score, proofs)
    return round(float(score), 3)


