def _region_hint_for_entity_v147(entity: Any) -> Tuple[str, str]:
    """Devuelve (perfil_local, nombre_local) para cualquier entidad si es inferible."""
    raw = str(entity or "").strip()
    canonical = _canonical_entity_name(raw)
    keys = _entity_alias_keys(raw) + _entity_alias_keys(canonical)
    blob = " " + " ".join(keys).lower() + " "
    # 1) Alias explícitos.
    for k in keys:
        item = _REGION_HINTS_V147.get(_norm_key(k)) or NATIVE_ENTITY_HINTS.get(_norm_key(k))
        if item:
            return str(item[0] or "en"), str(item[1] or canonical or raw)
    # 2) Señales por país/región en el nombre.
    country_rules = [
        (("china", "chinese", "pboc", "中国", "人民银行"), ("zh", "")),
        (("japan", "japanese", "tokyo", "日本"), ("ja", "")),
        (("korea", "korean", "seoul", "한국"), ("ko", "")),
        (("russia", "russian", "moscow", "рос"), ("ru", "")),
        (("saudi", "qatar", "uae", "emirates", "dubai", "abu dhabi", "arab", "الإمارات", "السعود"), ("ar", "")),
        (("india", "indian", "mumbai", "delhi", "भारत"), ("hi", "")),
        (("europe", "european", "euro", "eu ", " ecb", " bce"), ("eu", "")),
        (("spain", "spanish", "españa", "espana", "madrid", "colombia", "mexico", "méxico", "chile", "peru", "perú", "argentina"), ("es", "")),
        (("brazil", "brasil", "portugal", "portuguese", "sao paulo", "são paulo"), ("pt", "")),
        (("france", "french", "paris", "français", "francais"), ("fr", "")),
        (("germany", "german", "deutsche", "deutschland", "frankfurt"), ("de", "")),
        (("italy", "italian", "italia", "milano", "rome", "roma"), ("it", "")),
        (("netherlands", "dutch", "amsterdam", "nederland"), ("nl", "")),
        (("turkey", "turkish", "türkiye", "istanbul"), ("tr", "")),
        (("indonesia", "jakarta", "rupiah"), ("id", "")),
    ]
    for needles, profile in country_rules:
        if any((" " + n + " ") in blob or n in raw.lower() for n in needles):
            return profile[0], profile[1] or canonical or raw
    return "en", canonical or raw


# Guardamos funciones v146 por diagnóstico.
_ORIG_NATIVE_IDENTITY_FOR_LOCAL_SWEEP_V147_PRE = _native_identity_for_local_sweep
_ORIG_LOCAL_SOURCE_QUERY_EXAMPLES_V147_PRE = _local_source_query_examples
_ORIG_NATIVE_QUERY_INSTRUCTION_V147_PRE = _native_query_instruction
_ORIG_RUN_LOCAL_SOURCE_SWEEP_V147_PRE = _run_local_source_sweep
_ORIG_SEARCH_INSTITUTION_CONNECTIONS_V147_PRE = search_institution_connections


def _native_identity_for_local_sweep(entity: Any) -> Tuple[str, str, str]:
    """v147: identidad local para cualquier búsqueda internacional, no solo CJK/no-latina."""
    raw = str(entity or "").strip()
    canonical = _canonical_entity_name(raw)
    script, native = _ORIG_NATIVE_IDENTITY_FOR_LOCAL_SWEEP_V147_PRE(entity)
    # Si v146 ya encontró un idioma nativo real, respetarlo.
    if script != "en" or native:
        return canonical, script, native
    # Si no, inferir perfil regional por entidad/país/nombre canónico.
    profile, local_name = _region_hint_for_entity_v147(raw or canonical)
    if profile != "en":
        return canonical, profile, local_name or canonical
    return canonical, "en", canonical


def _local_source_query_examples(entity: Any, limit: int = 12) -> List[str]:
    """v147: genera consultas locales/regionales para cualquier entidad débil."""
    canonical, script, native = _native_identity_for_local_sweep(entity)
    official = _LOCAL_OFFICIAL_SITES.get(script, _LOCAL_OFFICIAL_SITES.get("en", ""))
    media = _LOCAL_NEWS_SITES.get(script, "")
    terms = _LOCAL_RIPPLE_TERMS.get(script, _LOCAL_RIPPLE_TERMS.get("en", ""))
    doc_kw = _LOCAL_DOC_KEYWORDS.get(script, _LOCAL_DOC_KEYWORDS.get("en", "PDF"))
    names: List[str] = []
    for n in [native, canonical, str(entity or "").strip()]:
        n = str(n or "").strip()
        if n and n not in names:
            names.append(n)
    queries: List[str] = []
    def add(q: str) -> None:
        q = re.sub(r"\s+", " ", str(q or "").strip())
        if q and q not in queries:
            queries.append(q)
    for name in names[:3]:
        add(f'"{name}" ({terms})')
        if official:
            add(f'({official}) "{name}" ({terms})')
            add(f'({official}) "{name}" ({doc_kw})')
        if media:
            add(f'({media}) "{name}" ({terms})')
        add(f'"{name}" ({doc_kw})')
        add(f'site:ripple.com "{name}"')
        add(f'site:bis.org "{name}" (Ripple OR XRPL OR blockchain OR CBDC OR tokenisation OR tokenization)')
    # Barridos específicos sin destruir la lógica China de v146.
    if canonical == "People's Bank of China (PBoC)" or script == "zh":
        for q in [
            '(site:pbc.gov.cn OR site:bis.org OR site:hkma.gov.hk) "中国人民银行" (mBridge OR 多边央行数字货币桥 OR 跨境支付 OR 区块链)',
            '(site:caixin.com OR site:yicai.com OR site:21jingji.com OR site:thepaper.cn) "中国人民银行" (Ripple OR 瑞波 OR 区块链 OR 跨境支付 OR 数字人民币)',
            '"连连支付" (Ripple OR RippleNet OR 瑞波 OR 跨境支付)',
        ]:
            add(q)
    if script == "eu":
        for q in [
            '(site:ecb.europa.eu OR site:europa.eu OR site:bis.org) "digital euro" (DLT OR blockchain OR wholesale OR interoperability)',
            '(site:ecb.europa.eu OR site:bis.org OR site:swift.com) "European Central Bank" (Ripple OR XRPL OR tokenisation OR tokenization OR shared ledger)',
            '(site:eur-lex.europa.eu OR site:eba.europa.eu OR site:esma.europa.eu) (DLT OR tokenisation OR crypto-assets OR settlement) (Ripple OR XRP OR XRPL)',
        ]:
            add(q)
    return queries[:limit]


def _native_query_instruction(entity: Any) -> str:
    """v147: la primera llamada ya sabe que el fallback local es internacional."""
    canonical, script, native = _native_identity_for_local_sweep(entity)
    queries = _local_source_query_examples(entity, limit=7)
    local_hint = _LOCAL_SEARCH_ENGINE_HINTS.get(script, _LOCAL_SEARCH_ENGINE_HINTS.get("en", "fuentes globales y oficiales"))
    if not queries:
        return ""
    return (
        "\nMODO FUENTES LOCALES / INTERNACIONAL: no dependas solo de resultados globales en inglés/español. "
        "Si la primera búsqueda no encuentra evidencia suficiente, busca en fuentes locales de la jurisdicción probable. "
        f"Entidad canónica: {canonical}. Perfil regional/idioma: {script}. Nombre local útil: {native or canonical}. "
        f"Usa {local_hint}. Consultas orientativas: " + " ; ".join(queries) + ". "
        "Regla crítica: las fuentes locales amplían cobertura, pero NO convierten menciones genéricas de CBDC/blockchain en conexión Ripple/XRPL. "
        "Solo cuenta si la fuente menciona explícitamente ambas partes o una cadena documental verificable. "
    )


def _run_local_source_sweep(institution_name: str,
                            conn: Optional[sqlite3.Connection] = None) -> Dict[str, Any]:
    """v147: segunda pasada regional para cualquier entidad si la primera quedó débil."""
    canonical, script, native = _native_identity_for_local_sweep(institution_name)
    api_key = _get_api_key()
    entity_type = _classify_entity(canonical)
    if not api_key:
        return {"_local_source_sweep_skipped": True, "summary": "Sin API key para barrido local/internacional."}
    call_type = "discovery_fast"
    if conn is not None and not _charge_budget(conn, call_type):
        return {"_budget_locked": True, "summary": "Presupuesto API bloqueado; no se ejecutó barrido local/internacional."}
    queries = _local_source_query_examples(institution_name, limit=12)
    schema = {
        "institution": canonical,
        "entity_type": entity_type,
        "connected": False,
        "confidence": 0.0,
        "summary": "",
        "ripple_products": [],
        "layer": "Descubierto",
        "icon": "🔎",
        "connects_to": [],
        "route_kind": "private",
        "sources": [],
        "wallets": [], "corridors": [], "partners": [], "map_points": [],
        "evidence_items": [], "route_decisions": [], "future_watch_targets": []
    }
    prompt = (
        "Eres un analista OSINT financiero internacional. La primera búsqueda global fue débil o no concluyente. "
        "Ahora haz una segunda pasada de fuentes locales/regionales: reguladores, bancos centrales, bolsas, repositorios oficiales, PDFs, comunicados, prensa financiera local y BIS/SWIFT/IMF cuando proceda. "
        f"Entidad investigada por el usuario: {institution_name}. Entidad canónica: {canonical}. "
        f"Perfil regional/idioma probable: {script}. Nombre local útil: {native or canonical}. "
        "No traduzcas superficialmente: usa la jurisdicción real y sus fuentes primarias. "
        "Usa estas consultas como guía, adaptándolas si hace falta:\n- " + "\n- ".join(queries) + "\n"
        "Regla Proof-First: solo marques connected=true si una fuente conecta explícitamente la entidad con Ripple, XRPL, XRP Ledger, RippleNet, Ripple Payments, RLUSD, Ripple Treasury/GTreasury, Metaco/Custody, Hidden Road, Rail, o una cadena documental verificable. "
        "Si solo encuentras CBDC/blockchain/tokenización genérica sin Ripple/XRPL, devuelve connected=false pero incluye las fuentes como revisión. "
        "Responde SOLO JSON válido, sin markdown, con esta estructura exacta: " + json.dumps(schema, ensure_ascii=False)
    )
    payload = {
        "model": ANTHROPIC_MODEL_FAST,
        "max_tokens": 1500,
        "system": [{"type": "text", "text": _AUDIT_SYSTEM_PROMPT, "cache_control": {"type": "ephemeral"}}],
        "tools": [{"type": "web_search_20250305", "name": "web_search"}],
        "messages": [{"role": "user", "content": prompt}],
    }
    headers = {"x-api-key": api_key, "anthropic-version": "2023-06-01",
               "anthropic-beta": "prompt-caching-2024-07-31,web-search-2025-03-05",
               "content-type": "application/json"}
    try:
        resp = requests.post(ANTHROPIC_API_URL, json=payload, headers=headers, timeout=55)
        if resp.status_code in (408, 409, 425, 429, 500, 502, 503, 504, 529):
            raise RuntimeError(f"{resp.status_code} Error temporal Anthropic/local sweep: {getattr(resp, 'text', '')[:180]}")
        resp.raise_for_status()
        data = resp.json()
        _settle_budget(conn, call_type, data, ANTHROPIC_MODEL_FAST)
        text_parts = [b.get("text", "") for b in data.get("content", []) if isinstance(b, dict) and b.get("type") == "text"]
        raw = " ".join(text_parts).strip().replace("```json", "").replace("```", "").strip()
        try:
            result = _loads_discovery_json_lenient(raw) if raw else {}
        except Exception as parse_exc:
            result = _salvage_discovery_from_text_and_sources(canonical, entity_type, raw, data, parse_exc)
        result = _finalize_discovery_result(result, canonical, entity_type, data)
        result["_local_source_sweep"] = True
        result["_local_source_sweep_profile"] = script
        return result
    except Exception as exc:
        _refund_budget(conn, call_type)
        if _is_anthropic_temporal_error(exc):
            r = _safe_api_temporal_result(canonical, entity_type, exc)
            r["_local_source_sweep"] = True
            r["_local_source_sweep_profile"] = script
            return r
        return _finalize_discovery_result({
            "institution": canonical,
            "entity_type": entity_type,
            "connected": False,
            "confidence": 0.0,
            "summary": f"Barrido local/internacional falló: {str(exc)[:220]}",
            "ripple_products": [], "layer": _classify_entity(canonical), "icon": "🔎",
            "connects_to": [], "route_kind": "private", "sources": [],
            "wallets": [], "corridors": [], "partners": [], "map_points": [], "evidence_items": [], "route_decisions": [],
            "_local_source_sweep_error": str(exc)[:220],
            "_local_source_sweep_profile": script,
        }, canonical, entity_type, None)


def search_institution_connections(institution_name: str,
                                   conn: Optional[sqlite3.Connection] = None,
                                   force_online: bool = False) -> Dict[str, Any]:
    """v147: caché/global primero; si queda débil, barrido local/internacional para cualquier entidad."""
    raw_name = str(institution_name or "").strip()
    canonical_name = _canonical_entity_name(raw_name)
    base_search = _ORIG_SEARCH_INSTITUTION_CONNECTIONS_V147_PRE
    try:
        result = base_search(canonical_name, conn=conn, force_online=force_online)
    except TypeError:
        result = base_search(canonical_name, conn=conn, force_online=force_online)
    result = dict(result or {})
    result["institution"] = _canonical_entity_name(result.get("institution") or canonical_name)
    if raw_name and _canonical_entity_key(raw_name) != _canonical_entity_key(canonical_name):
        result["_user_query_alias"] = raw_name
        result["_canonical_resolved_from_alias"] = canonical_name
    needs_local = _is_weak_discovery_for_local_sweep(result)
    # Si ya hay un error temporal de API, no fuerces más llamadas.
    if needs_local and not result.get("_api_temporal_error") and not result.get("_budget_locked"):
        local = _run_local_source_sweep(raw_name or canonical_name, conn=conn)
        result = _merge_local_sweep_result(result, local, raw_name or canonical_name)
        try:
            if conn is not None and not result.get("_api_temporal_error") and not result.get("_api_transient_error"):
                _set_search_cache(conn, canonical_name, result, "discovery")
                if raw_name and raw_name != canonical_name:
                    _set_search_cache(conn, raw_name, result, "discovery")
        except Exception:
            pass
    return result


def _rrp_v147_selftest_international_sweep() -> Dict[str, Any]:
    """Diagnóstico sin internet: verifica perfiles y queries locales internacionales."""
    samples = [
        "banco popular chino", "Banco Central Europeo", "European Central Bank",
        "Banco de España", "Banco Central do Brasil", "Bundesbank", "Banque de France",
        "Banca d'Italia", "Bank Indonesia", "Akbank", "SBI Remit",
        "Entidad inventada global",
    ]
    rows = []
    for s in samples:
        ident = _native_identity_for_local_sweep(s)
        rows.append({
            "input": s,
            "canonical": _canonical_entity_name(s),
            "identity": ident,
            "queries": _local_source_query_examples(s, limit=4),
            "instruction_head": _native_query_instruction(s)[:280],
        })
    return {"ok": True, "rows": rows}


# =============================================================================
# v148 · WATCHPOINTS: NO CREAR FALSOS NEGATIVOS DE EVIDENCIA
# =============================================================================
# Problema corregido:
# Al pulsar Verificar desde un nodo publico como XRPL, la app validaba pares
# estructurales del mapa (XRPL↔RLUSD, XRPL↔DEX/AMM, XRPL↔Clusters, etc.) como
# si fueran relaciones documentales A↔B. Como no hay una “institucion” detrás,
# se guardaban filas en connection_proofs con 0%, que luego aparecían como
# “❌ Sin evidencia verificable”. Eso era falso y confuso: esas líneas son
# zonas de vigilancia/observabilidad, no hipótesis documentales fallidas.

_ORIG_VALIDATE_NODE_FAST_V148_PRE = validate_node_fast
_ORIG_VALIDATE_CONNECTION_ONCHAIN_V148_PRE = validate_connection_onchain

_RRP_STRUCTURAL_ROUTE_KINDS_V148: Set[str] = {
    "public",
    "monitoring_link",
    "public_trace_watch",
    "public_watchpoint",
    "watch_only",
    "watch",
    "deductive_watch",
    "indirect_watch",
    "core_infra",
    "technology_basis",
    "model",
    "future",
}

_RRP_FALSE_NEGATIVE_PROOF_TYPES_V148: Set[str] = {"sin_wallet", "unknown", "ai_inference"}


def _rrp_v148_route_kind_between(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> str:
    """Devuelve el tipo de ruta ya existente entre A y B, si es estructural/dinámica."""
    try:
        ka = _canonical_entity_key(node_a)
        kb = _canonical_entity_key(node_b)
        for r in ROUTES:
            try:
                a, b, kind = r[0], r[1], str(r[2] or "")
                if {ka, kb} == {_canonical_entity_key(a), _canonical_entity_key(b)}:
                    return kind
            except Exception:
                continue
        if conn is not None:
            try:
                rows = conn.execute(
                    "SELECT source, target, kind FROM dynamic_routes WHERE COALESCE(sanitizer_status,'active')!='quarantined'"
                ).fetchall()
                for a, b, kind in rows:
                    if {ka, kb} == {_canonical_entity_key(a), _canonical_entity_key(b)}:
                        return str(kind or "")
            except Exception:
                pass
    except Exception:
        pass
    return ""


def _rrp_v148_is_structural_watch_pair(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> bool:
    """True si el par es una línea de mapa/vigilancia y no debe guardarse como prueba negativa."""
    try:
        kind = _rrp_v148_route_kind_between(node_a, node_b, conn)
        if str(kind or "").strip() in _RRP_STRUCTURAL_ROUTE_KINDS_V148:
            return True
        # Si ambos son nodos públicos/observabilidad, siempre es estructura del radar.
        if _rrp_is_public_watchpoint_node(node_a) and _rrp_is_public_watchpoint_node(node_b):
            return True
        # Si uno es watchpoint y el otro es motor interno, también es observabilidad.
        engines = {"Topology Engine", "Anomaly Engine", "Fingerprint Engine"}
        if (_rrp_is_public_watchpoint_node(node_a) and _canonical_entity_name(node_b) in engines) or (_rrp_is_public_watchpoint_node(node_b) and _canonical_entity_name(node_a) in engines):
            return True
    except Exception:
        pass
    return False


def _rrp_v148_proof_has_real_evidence(proof_data: Any) -> bool:
    try:
        if isinstance(proof_data, str):
            data = json.loads(proof_data or "{}")
        elif isinstance(proof_data, dict):
            data = proof_data
        else:
            data = {}
        proofs = data.get("proofs") or []
        for p in proofs:
            if not isinstance(p, dict):
                continue
            typ = str(p.get("type") or "").strip()
            if typ in _RRP_FALSE_NEGATIVE_PROOF_TYPES_V148:
                continue
            if p.get("onchain") or p.get("internet") or p.get("url") or p.get("tx_hash"):
                return True
    except Exception:
        pass
    return False


def _rrp_v148_cleanup_false_negative_watchpoint_proofs(conn: Optional[sqlite3.Connection]) -> int:
    """Elimina pruebas 0% creadas sobre líneas estructurales/watchpoint del mapa."""
    if conn is None:
        return 0
    removed = 0
    try:
        ensure_discovery_tables(conn)
        rows = conn.execute(
            "SELECT proof_id, node_a, node_b, proof_type, proof_data, confidence FROM connection_proofs "
            "WHERE COALESCE(sanitizer_status,'active')!='quarantined'"
        ).fetchall()
        for proof_id, a, b, ptype, pdata, conf in rows:
            try:
                conf_f = float(conf or 0.0)
                if not _rrp_v148_is_structural_watch_pair(a, b, conn):
                    continue
                if conf_f > 0.05 and _rrp_v148_proof_has_real_evidence(pdata):
                    continue
                if str(ptype or "") in _RRP_FALSE_NEGATIVE_PROOF_TYPES_V148 or conf_f <= 0.05 or not _rrp_v148_proof_has_real_evidence(pdata):
                    cur = conn.execute("DELETE FROM connection_proofs WHERE proof_id=?", (proof_id,))
                    removed += int(cur.rowcount or 0)
            except Exception:
                continue
        if removed:
            conn.commit()
    except Exception:
        pass
    return removed


def _rrp_v148_watchpoint_skip_result(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> Dict[str, Any]:
    kind = _rrp_v148_route_kind_between(node_a, node_b, conn) or "watchpoint"
    return {
        "from_cache": False,
        "node_a": _canonical_entity_name(node_a),
        "node_b": _canonical_entity_name(node_b),
        "proofs": [],
        "wallets_a": [],
        "wallets_b": [],
        "active_wallets": [],
        "cert_label": "🛰 Punto de vigilancia del mapa",
        "cert_color": "#FB923C",
        "calibrated_score": 0.0,
        "has_onchain": False,
        "has_internet": False,
        "route_kind": kind,
        "_watchpoint_only": True,
        "summary": f"{_canonical_entity_name(node_a)} ↔ {_canonical_entity_name(node_b)} es una línea estructural/de vigilancia ({kind}); no se guarda como prueba negativa 0%.",
    }


def validate_node_fast(focus_node: str, peers: List[str], conn: sqlite3.Connection, progress_cb: Optional[Any] = None) -> None:
    """v148: verifica solo pares investigables; las líneas públicas/watch no generan 0%."""
    try:
        _rrp_v148_cleanup_false_negative_watchpoint_proofs(conn)
    except Exception:
        pass
    if not peers:
        return
    investigable: List[str] = []
    skipped: List[str] = []
    for p in peers:
        if _rrp_v148_is_structural_watch_pair(focus_node, p, conn):
            skipped.append(str(p))
        else:
            investigable.append(p)
    if skipped:
        try:
            st.session_state["rrp_v148_watchpoint_skipped"] = {
                "focus": str(focus_node),
                "peers": skipped,
                "at": datetime.now(timezone.utc).isoformat(),
                "reason": "Líneas de vigilancia/observabilidad del mapa: no se guardan como falso negativo 0%.",
            }
        except Exception:
            pass
    if not investigable:
        if progress_cb is not None:
            try:
                progress_cb(1.0, f"{len(skipped)} línea(s) eran vigilancia del mapa; no se crean falsos negativos.")
            except Exception:
                pass
        try:
            conn.commit()
        except Exception:
            pass
        return
    return _ORIG_VALIDATE_NODE_FAST_V148_PRE(focus_node, investigable, conn, progress_cb=progress_cb)


def validate_connection_onchain(node_a: str, node_b: str, conn: sqlite3.Connection, force: bool = False) -> Dict[str, Any]:
    """v148: una línea pública/watchpoint no se convierte en prueba 0% si no hay wallet/TX."""
    try:
        _rrp_v148_cleanup_false_negative_watchpoint_proofs(conn)
        if _rrp_v148_is_structural_watch_pair(node_a, node_b, conn):
            return _rrp_v148_watchpoint_skip_result(node_a, node_b, conn)
    except Exception:
        pass
    return _ORIG_VALIDATE_CONNECTION_ONCHAIN_V148_PRE(node_a, node_b, conn, force=force)


def _rrp_v148_boot_cleanup_watchpoint_false_negatives() -> int:
    try:
        conn = get_conn()
        return _rrp_v148_cleanup_false_negative_watchpoint_proofs(conn)
    except Exception:
        return 0


try:
    _rrp_v148_boot_cleanup_watchpoint_false_negatives()
except Exception:
    pass


# =============================================================================
# v149 · WATCHPOINTS: PENDIENTE DOCUMENTAL, NO “SIN EVIDENCIA”
# =============================================================================
# Matiz importante:
# v148 evitó crear falsos negativos 0% para XRPL/RLUSD/DEX/AMM/Trustlines/etc.
# Pero el usuario tiene razón: muchas de esas relaciones estructurales SÍ pueden
# tener documentos públicos que las respalden; simplemente todavía no se han
# investigado en el módulo documental. Por eso el estado correcto no es
# “sin evidencia”, sino “pendiente de investigación documental / on-chain”.

_RRP_V149_DOC_PENDING_KINDS: Set[str] = set(_RRP_STRUCTURAL_ROUTE_KINDS_V148) | {
    "public", "core_infra", "technology_basis", "public_trace_watch",
    "monitoring_link", "public_watchpoint", "watchpoint", "watch",
}


def _rrp_v149_pair_has_real_saved_evidence(conn: Optional[sqlite3.Connection], node_a: Any, node_b: Any) -> bool:
    """True si ya existe una prueba real guardada para el par."""
    if conn is None:
        return False
    try:
        row = _connection_proof_row(conn, _canonical_entity_name(node_a), _canonical_entity_name(node_b))
        if not row:
            return False
        pdata, onchain, conf, *_ = row
        if bool(onchain):
            return True
        if float(conf or 0.0) >= 0.20 and _rrp_v148_proof_has_real_evidence(pdata):
            return True
        return _rrp_v148_proof_has_real_evidence(pdata)
    except Exception:
        return False


def _rrp_v149_route_note_for_pair(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> Tuple[str, str]:
    """Devuelve (kind, note) para explicar una línea estructural pendiente."""
    kind = _rrp_v148_route_kind_between(node_a, node_b, conn) or "watchpoint"
    ca = _canonical_entity_name(node_a)
    cb = _canonical_entity_name(node_b)
    k = str(kind or "").strip().lower()
    if k == "technology_basis":
        return kind, "Base tecnológica posible/documental: requiere revisar documentos, no transacciones." 
    if k == "core_infra":
        return kind, "Infraestructura interna del stack Ripple/XRPL: no es una operación, pero puede tener documentación pública." 
    if k in {"public", "monitoring_link", "public_watchpoint", "public_trace_watch"}:
        return kind, "Zona pública observable del radar: se verifica con documentos y/o señales on-chain cuando haya una ruta institucional." 
    if _rrp_is_public_watchpoint_node(ca) or _rrp_is_public_watchpoint_node(cb):
        return kind, "Punto público de vigilancia: pendiente de investigación documental/on-chain; no equivale a ausencia de evidencia." 
    return kind, "Línea pendiente de revisión documental: todavía no se debe marcar como negativa." 


def _rrp_v149_is_document_pending_pair(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> bool:
    """Pares que no deben mostrarse como 0%, sino como pendientes de investigar documentos."""
    try:
        if _rrp_v149_pair_has_real_saved_evidence(conn, node_a, node_b):
            return False
        kind = str(_rrp_v148_route_kind_between(node_a, node_b, conn) or "").strip()
        if kind in _RRP_V149_DOC_PENDING_KINDS:
            return True
        if _rrp_v148_is_structural_watch_pair(node_a, node_b, conn):
            return True
        return False
    except Exception:
        return False


def _rrp_v149_document_pending_pairs_for_node(conn: Optional[sqlite3.Connection], focus_node: Any, limit: int = 16) -> List[Dict[str, Any]]:
    """Lista líneas del foco que son estructura/watchpoint/core y aún no tienen prueba documental guardada."""
    if conn is None or not focus_node:
        return []
    focus = _canonical_entity_name(focus_node)
    fkey = _canonical_entity_key(focus)
    pairs: Dict[str, Dict[str, Any]] = {}

    def add_pair(peer: Any, kind: Any, evidence: Any = "", urls: Optional[List[str]] = None) -> None:
        peer_name = _canonical_entity_name(peer)
        if not peer_name or _canonical_entity_key(peer_name) == fkey:
            return
        if not _rrp_v149_is_document_pending_pair(focus, peer_name, conn):
            return
        pk = _canonical_pair_key(focus, peer_name)
        k, note = _rrp_v149_route_note_for_pair(focus, peer_name, conn)
        pairs[pk] = {
            "peer": peer_name,
            "kind": str(kind or k or "watchpoint"),
            "note": note,
            "evidence": str(evidence or ""),
            "urls": list(urls or []),
        }

    try:
        for a, b, kind, *_rest in ROUTES:
            if _canonical_entity_key(a) == fkey:
                add_pair(b, kind)
            elif _canonical_entity_key(b) == fkey:
                add_pair(a, kind)
    except Exception:
        pass

    try:
        ensure_discovery_tables(conn)
        rows = conn.execute(
            "SELECT source, target, kind, evidence, source_urls FROM dynamic_routes "
            "WHERE COALESCE(sanitizer_status,'active')!='quarantined' AND (source_key=? OR target_key=? OR source=? OR target=?)",
            (fkey, fkey, focus, focus),
        ).fetchall()
        for src, dst, kind, ev, urls_json in rows:
            peer = dst if _canonical_entity_key(src) == fkey else src
            urls = []
            try:
                urls = json.loads(urls_json or "[]") if isinstance(urls_json, str) else []
            except Exception:
                urls = []
            add_pair(peer, kind, ev, urls)
    except Exception:
        pass

    # Prioridad: bases tecnológicas y rutas públicas antes que motores internos.
    def sort_key(item: Dict[str, Any]) -> Tuple[int, str]:
        k = str(item.get("kind") or "").lower()
        p = str(item.get("peer") or "")
        pri = 5
        if k in {"technology_basis", "core_infra"}: pri = 0
        elif k in {"public", "public_trace_watch", "public_watchpoint"}: pri = 1
        elif k in {"monitoring_link"}: pri = 4
        return (pri, p)

    return sorted(pairs.values(), key=sort_key)[:limit]


# Reemplazar el resultado skip de v148: ya no dice “no hay evidencia”, dice pendiente documental.
def _rrp_v148_watchpoint_skip_result(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> Dict[str, Any]:
    kind, note = _rrp_v149_route_note_for_pair(node_a, node_b, conn)
    return {
        "from_cache": False,
        "node_a": _canonical_entity_name(node_a),
        "node_b": _canonical_entity_name(node_b),
        "proofs": [],
        "wallets_a": [],
        "wallets_b": [],
        "active_wallets": [],
        "cert_label": "🧾 Pendiente de investigación documental/on-chain",
        "cert_color": "#F59E0B",
        "calibrated_score": 0.0,
        "has_onchain": False,
        "has_internet": False,
        "route_kind": kind,
        "_watchpoint_only": True,
        "_doc_pending": True,
        "summary": (
            f"{_canonical_entity_name(node_a)} ↔ {_canonical_entity_name(node_b)} es una línea estructural/de vigilancia ({kind}). "
            f"Estado correcto: pendiente de investigar documentos y señales públicas. {note} No se guarda como negativo 0%."
        ),
    }


# Limpieza ampliada: filas antiguas 0% sobre watchpoints se eliminan para que no reaparezcan como ❌.
def _rrp_v149_cleanup_doc_pending_false_negatives(conn: Optional[sqlite3.Connection]) -> int:
    if conn is None:
        return 0
    removed = 0
    try:
        ensure_discovery_tables(conn)
        rows = conn.execute(
            "SELECT proof_id, node_a, node_b, proof_type, proof_data, confidence FROM connection_proofs "
            "WHERE COALESCE(sanitizer_status,'active')!='quarantined'"
        ).fetchall()
        for proof_id, a, b, ptype, pdata, conf in rows:
            try:
                if not _rrp_v149_is_document_pending_pair(a, b, conn):
                    continue
                if _rrp_v149_pair_has_real_saved_evidence(conn, a, b):
                    continue
                cur = conn.execute("DELETE FROM connection_proofs WHERE proof_id=?", (proof_id,))
                removed += int(cur.rowcount or 0)
            except Exception:
                continue
        if removed:
            conn.commit()
    except Exception:
        pass
    return removed


# Añadir un panel pedagógico al mapa/nodo: lo pendiente no es negativo.
_ORIG_RENDER_NODE_INFO_PANEL_V149 = render_node_info_panel

def render_node_info_panel(
    focus_node: str,
    all_nodes: Dict[str, Dict[str, Any]],
    all_routes: List[Tuple],
    conn: Optional[sqlite3.Connection] = None,
    accent: str = "#5AD7FF",
) -> None:
    try:
        if conn is not None:
            _rrp_v149_cleanup_doc_pending_false_negatives(conn)
    except Exception:
        pass

    _ORIG_RENDER_NODE_INFO_PANEL_V149(focus_node, all_nodes, all_routes, conn=conn, accent=accent)

    try:
        pending = _rrp_v149_document_pending_pairs_for_node(conn, focus_node, limit=12)
    except Exception:
        pending = []
    if not pending:
        return

    st.markdown(
        "<div style='margin-top:10px;background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.30);"
        "border-radius:12px;padding:10px 12px;'>"
        "<div style='color:#F59E0B;font-weight:900'>🧾 Líneas pendientes de investigación documental / on-chain</div>"
        "<div style='color:#CBD5E1;font-size:.80rem;margin-top:4px;line-height:1.45'>"
        "Estas líneas no son <b>0%</b> ni <b>sin evidencia</b>. Son puntos estructurales o de vigilancia donde puede haber documentación pública, "
        "pero todavía no se ha hecho una investigación documental específica de esa línea."
        "</div></div>",
        unsafe_allow_html=True,
    )

    for item in pending:
        peer = item.get("peer") or ""
        kind = item.get("kind") or "watchpoint"
        note = item.get("note") or "Pendiente de revisión documental."
        ev = item.get("evidence") or ""
        urls = item.get("urls") or []
        with st.expander(f"🧾 Pendiente · {focus_node} ↔ {peer} · {kind}", expanded=False):
            st.markdown(f"**Estado:** pendiente de investigar documentos/señales públicas.  \n**Lectura correcta:** {note}")
            if ev:
                st.caption(str(ev)[:650])
            if urls:
                links = " ".join(f"[fuente {i+1}]({u})" for i, u in enumerate(urls[:6]))
                st.markdown(links)
            c1, c2 = st.columns([1, 1])
            with c1:
                if st.button("🧾 Investigar documentos de esta línea", key=f"v149_doc_line_{_canonical_pair_key(focus_node, peer)}", use_container_width=True):
                    q = f"{_canonical_entity_name(focus_node)} {_canonical_entity_name(peer)}"
                    if conn is None:
                        st.error("No hay conexión SQLite disponible para lanzar la investigación.")
                    else:
                        with st.spinner(f"Investigando documentos para: {q}"):
                            try:
                                res = search_institution_connections(q, conn=conn, force_online=True)
                                res = _finalize_discovery_result(res, q, _classify_entity(q), None)
                                apply_info = apply_discovery_to_map(conn, res, auto=True)
                                st.session_state["disc_result"] = res
                                st.session_state["disc_query"] = q
                                st.session_state["disc_from_cache"] = False
                                st.success(
                                    f"Investigación documental lanzada: {apply_info.get('added_routes',0)} rutas · "
                                    f"{apply_info.get('added_nodes',0)} nodos/puntos actualizados. Revisa Descubrimientos para ver el detalle."
                                )
                            except Exception as e:
                                st.error(f"No pude completar la investigación documental de la línea: {e}")
            with c2:
                st.caption("No se repite como búsqueda normal salvo que pulses el botón; así no se gasta API sin intención.")


try:
    _rrp_v149_cleanup_doc_pending_false_negatives(get_conn())
except Exception:
    pass


# =============================================================================
# v150 · CUALQUIER NODO FIJO: PENDIENTE DOCUMENTAL/ON-CHAIN, NO FALSO 0%
# =============================================================================
# Extiende la filosofía de v149: no solo XRPL/RLUSD/watchpoints. Si una línea
# pertenece a un nodo fijo del mapa (NODES) y todavía no hay una investigación
# documental específica guardada, el estado correcto es "pendiente", no
# "sin evidencia verificable 0%". Esto evita confundir líneas estructurales del
# mapa con conclusiones negativas.

_ORIG_RRP_V148_IS_STRUCTURAL_WATCH_PAIR_V150 = _rrp_v148_is_structural_watch_pair
_ORIG_RRP_V149_IS_DOCUMENT_PENDING_PAIR_V150 = _rrp_v149_is_document_pending_pair
_ORIG_RRP_V149_ROUTE_NOTE_FOR_PAIR_V150 = _rrp_v149_route_note_for_pair


def _rrp_v150_is_fixed_node(name: Any) -> bool:
    """True si el nodo forma parte del mapa base/fijado, no descubierto dinámicamente."""
    try:
        key = _canonical_entity_key(_canonical_entity_name(name))
        return key in {_canonical_entity_key(k) for k in (NODES or {}).keys()}
    except Exception:
        return False


def _rrp_v150_known_route_kind_between(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> str:
    """Devuelve tipo de ruta si el par existe en ROUTES o dynamic_routes."""
    try:
        kind = _rrp_v148_route_kind_between(node_a, node_b, conn)
        if kind:
            return str(kind or "")
    except Exception:
        pass
    return ""


def _rrp_v150_is_fixed_map_pair(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> bool:
    """Par con al menos un nodo fijo y una línea ya existente en el mapa.

    No convierte cualquier combinación de nodos fijos en pendiente: solo las
    líneas que el mapa ya dibuja o que Discovery guardó en dynamic_routes.
    """
    try:
        if not (_rrp_v150_is_fixed_node(node_a) or _rrp_v150_is_fixed_node(node_b)):
            return False
        return bool(_rrp_v150_known_route_kind_between(node_a, node_b, conn))
    except Exception:
        return False


def _rrp_v148_is_structural_watch_pair(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> bool:
    """v150: también trata líneas de nodos fijos como pendientes, no falso negativo.

    La validación rápida/on-chain no debe escribir 0% solo porque una línea fija
    no tenga wallet/TX inmediata. Eso se investiga documentalmente con un botón
    específico, o queda pendiente.
    """
    try:
        if _ORIG_RRP_V148_IS_STRUCTURAL_WATCH_PAIR_V150(node_a, node_b, conn):
            return True
        if _rrp_v150_is_fixed_map_pair(node_a, node_b, conn):
            return True
    except Exception:
        pass
    return False


def _rrp_v149_is_document_pending_pair(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> bool:
    """v150: watchpoints + cualquier línea existente de nodo fijo sin evidencia real."""
    try:
        if _rrp_v149_pair_has_real_saved_evidence(conn, node_a, node_b):
            return False
        if _ORIG_RRP_V149_IS_DOCUMENT_PENDING_PAIR_V150(node_a, node_b, conn):
            return True
        if _rrp_v150_is_fixed_map_pair(node_a, node_b, conn):
            return True
    except Exception:
        pass
    return False


def _rrp_v149_route_note_for_pair(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> Tuple[str, str]:
    """v150: nota pedagógica distinta para líneas de nodos fijos."""
    try:
        if _rrp_v150_is_fixed_map_pair(node_a, node_b, conn) and not _rrp_v149_pair_has_real_saved_evidence(conn, node_a, node_b):
            kind = _rrp_v150_known_route_kind_between(node_a, node_b, conn) or "fixed_map_route"
            return kind, (
                "Línea del mapa base/fijado: todavía no se ha investigado documentalmente esta relación concreta. "
                "No debe leerse como 0% ni como ausencia de evidencia; queda pendiente de documentos, fuentes oficiales u on-chain si procede."
            )
    except Exception:
        pass
    return _ORIG_RRP_V149_ROUTE_NOTE_FOR_PAIR_V150(node_a, node_b, conn)


def _rrp_v150_cleanup_fixed_node_false_negatives(conn: Optional[sqlite3.Connection]) -> int:
    """Borra antiguos 0% guardados sobre rutas de nodos fijos que solo estaban sin investigar."""
    if conn is None:
        return 0
    removed = 0
    try:
        ensure_discovery_tables(conn)
        rows = conn.execute(
            "SELECT proof_id, node_a, node_b, proof_type, proof_data, confidence FROM connection_proofs "
            "WHERE COALESCE(sanitizer_status,'active')!='quarantined'"
        ).fetchall()
        for proof_id, a, b, ptype, pdata, conf in rows:
            try:
                conf_f = float(conf or 0.0)
                if not _rrp_v150_is_fixed_map_pair(a, b, conn):
                    continue
                if _rrp_v149_pair_has_real_saved_evidence(conn, a, b):
                    continue
                if conf_f <= 0.05 or str(ptype or "") in _RRP_FALSE_NEGATIVE_PROOF_TYPES_V148 or not _rrp_v148_proof_has_real_evidence(pdata):
                    cur = conn.execute("DELETE FROM connection_proofs WHERE proof_id=?", (proof_id,))
                    removed += int(cur.rowcount or 0)
            except Exception:
                continue
        if removed:
            conn.commit()
    except Exception:
        pass
    return removed


# Refuerza la limpieza existente de v149 para que también cubra nodos fijados.
_ORIG_RRP_V149_CLEANUP_DOC_PENDING_FALSE_NEGATIVES_V150 = _rrp_v149_cleanup_doc_pending_false_negatives

def _rrp_v149_cleanup_doc_pending_false_negatives(conn: Optional[sqlite3.Connection]) -> int:
    total = 0
    try:
        total += int(_ORIG_RRP_V149_CLEANUP_DOC_PENDING_FALSE_NEGATIVES_V150(conn) or 0)
    except Exception:
        pass
    try:
        total += int(_rrp_v150_cleanup_fixed_node_false_negatives(conn) or 0)
    except Exception:
        pass
    return total


# Mensaje más claro en el panel: ahora cubre watchpoints y nodos fijados.
_ORIG_RENDER_NODE_INFO_PANEL_V150 = render_node_info_panel

def render_node_info_panel(
    focus_node: str,
    all_nodes: Dict[str, Dict[str, Any]],
    all_routes: List[Tuple],
    conn: Optional[sqlite3.Connection] = None,
    accent: str = "#5AD7FF",
) -> None:
    try:
        if conn is not None:
            _rrp_v149_cleanup_doc_pending_false_negatives(conn)
    except Exception:
        pass
    _ORIG_RENDER_NODE_INFO_PANEL_V150(focus_node, all_nodes, all_routes, conn=conn, accent=accent)
    try:
        if _rrp_v150_is_fixed_node(focus_node):
            st.caption("📌 Nodo fijado: las líneas sin prueba específica se muestran como pendientes de investigación, no como 0% ni como ausencia de evidencia.")
    except Exception:
        pass


try:
    _rrp_v149_cleanup_doc_pending_false_negatives(get_conn())
except Exception:
    pass



# =============================================================================
# v151 · FIX DEFINITIVO: NO MÁS 0% FALSOS EN NODOS FIJOS + TYPEERROR PANEL
# =============================================================================
# Corrección real de v149/v150:
# 1) El wrapper anterior de render_node_info_panel tenía firma incorrecta y podía
#    provocar TypeError en Streamlit al abrir fichas de nodos.
# 2) La limpieza de falsos 0% dependía de columnas sanitizer_* y de detectar una
#    ruta concreta; si la DB venía de versiones antiguas, esas filas podían seguir
#    apareciendo como "❌ Sin evidencia verificable".
# 3) Para nodos fijados/estructurales, un 0% sin pruebas no significa ausencia de
#    evidencia: significa pendiente de investigación documental/on-chain.

_RRP_V151_FALSE_NEGATIVE_LABELS = (
    "sin evidencia verificable",
    "sin evidencia registrada",
    "sin rastro verificable",
)


def _rrp_v151_table_columns(conn: sqlite3.Connection, table: str) -> Set[str]:
    try:
        return {str(r[1]) for r in conn.execute(f"PRAGMA table_info({table})").fetchall()}
    except Exception:
        return set()


def _rrp_v151_safe_connection_rows(conn: Optional[sqlite3.Connection]) -> List[Dict[str, Any]]:
    """Lee connection_proofs aunque falten columnas de migraciones antiguas."""
    if conn is None:
        return []
    try:
        ensure_discovery_tables(conn)
    except Exception:
        pass
    try:
        # Añadir sanitizer si existe la función; si falla, seguimos sin depender de ella.
        try:
            ensure_sanitizer_tables(conn)
        except Exception:
            pass
        cols = _rrp_v151_table_columns(conn, "connection_proofs")
        if not cols:
            return []
        wanted = [
            "proof_id", "node_a", "node_b", "proof_type", "proof_data",
            "confidence", "onchain", "cert_label", "validated_at", "sanitizer_status",
        ]
        select_cols = [c for c in wanted if c in cols]
        if not select_cols:
            return []
        q = "SELECT " + ",".join(select_cols) + " FROM connection_proofs"
        if "sanitizer_status" in cols:
            q += " WHERE COALESCE(sanitizer_status,'active')!='quarantined'"
        rows = conn.execute(q).fetchall()
        out = []
        for row in rows:
            d = dict(zip(select_cols, row))
            out.append(d)
        return out
    except Exception:
        return []


def _rrp_v151_pair_has_existing_map_line(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> bool:
    """True si A↔B ya pertenece al mapa base o a dynamic_routes."""
    try:
        ka = _canonical_entity_key(node_a)
        kb = _canonical_entity_key(node_b)
        for r in ROUTES:
            try:
                if {ka, kb} == {_canonical_entity_key(r[0]), _canonical_entity_key(r[1])}:
                    return True
            except Exception:
                continue
        if conn is not None:
            cols = _rrp_v151_table_columns(conn, "dynamic_routes")
            if {"src", "dst"}.issubset(cols):
                q = "SELECT src,dst FROM dynamic_routes"
                if "sanitizer_status" in cols:
                    q += " WHERE COALESCE(sanitizer_status,'active')!='quarantined'"
                for a, b in conn.execute(q).fetchall():
                    if {ka, kb} == {_canonical_entity_key(a), _canonical_entity_key(b)}:
                        return True
    except Exception:
        pass
    return False


def _rrp_v151_is_fixed_or_watch_related_pair(node_a: Any, node_b: Any, conn: Optional[sqlite3.Connection] = None) -> bool:
    """Pares que no deben convertirse en 0% sin investigación documental real."""
    try:
        # Watchpoints públicos internos: siempre son observabilidad, no negativos.
        if _rrp_is_public_watchpoint_node(node_a) or _rrp_is_public_watchpoint_node(node_b):
            return True
        # Si al menos un extremo es nodo fijado del mapa, y hay línea o la fila nació
        # de una validación del mapa, lo tratamos como pendiente.
        if _rrp_v150_is_fixed_node(node_a) or _rrp_v150_is_fixed_node(node_b):
            return True
        # Pares explícitos del mapa dinámico/estático.
        if _rrp_v151_pair_has_existing_map_line(node_a, node_b, conn):
            return True
    except Exception:
        pass
    return False


def _rrp_v151_proof_data_has_real_evidence(pdata: Any) -> bool:
    """Detecta si una fila contiene fuentes reales; si no, es candidata a pendiente."""
    try:
        if isinstance(pdata, str):
            data = json.loads(pdata or "{}")
        elif isinstance(pdata, dict):
            data = pdata
        else:
            data = {}
    except Exception:
        data = {}
    try:
        if data.get("has_onchain") or data.get("has_internet"):
            proofs = data.get("proofs") or []
            # Si dice tener internet/onchain pero no trae ninguna URL/TX, no lo consideramos prueba real.
            for p in proofs:
                if not isinstance(p, dict):
                    continue
                if p.get("tx_hash") or p.get("ledger") or p.get("url") or p.get("source_url"):
                    return True
        proofs = data.get("proofs") or []
        for p in proofs:
            if not isinstance(p, dict):
                continue
            typ = str(p.get("type") or "").strip().lower()
            if typ in _RRP_FALSE_NEGATIVE_PROOF_TYPES_V148:
                continue
            if p.get("tx_hash") or p.get("ledger") or p.get("url") or p.get("source_url"):
                return True
        # También admitir fuentes sueltas antiguas.
        for key in ("url", "source_url", "source_urls", "sources"):
            val = data.get(key)
            if isinstance(val, str) and "http" in val:
                return True
            if isinstance(val, list) and any("http" in str(x) for x in val):
                return True
    except Exception:
        pass
    return False


def _rrp_v151_is_false_negative_row(row: Dict[str, Any], conn: Optional[sqlite3.Connection] = None) -> bool:
    try:
        a = row.get("node_a")
        b = row.get("node_b")
        if not a or not b:
            return False
        conf = float(row.get("confidence") or 0.0)
        ptype = str(row.get("proof_type") or "").strip().lower()
        pdata = row.get("proof_data") or "{}"
        cert = ""
        try:
            data = json.loads(pdata or "{}") if isinstance(pdata, str) else dict(pdata or {})
            cert = str(data.get("cert_label") or row.get("cert_label") or "").strip().lower()
        except Exception:
            cert = str(row.get("cert_label") or "").strip().lower()
        if not _rrp_v151_is_fixed_or_watch_related_pair(a, b, conn):
            return False
        has_real = _rrp_v151_proof_data_has_real_evidence(pdata)
        negative_label = any(x in cert for x in _RRP_V151_FALSE_NEGATIVE_LABELS)
        false_type = ptype in _RRP_FALSE_NEGATIVE_PROOF_TYPES_V148 or ptype in {"sin_evidencia", "no_evidence", "none"}
        return (not has_real) and (conf <= 0.05 or false_type or negative_label)
    except Exception:
        return False


def _rrp_v151_cleanup_all_fixed_false_negatives(conn: Optional[sqlite3.Connection]) -> int:
    """Elimina de forma robusta filas 0% antiguas de nodos fijados/watchpoints."""
    if conn is None:
        return 0
    removed = 0
    try:
        rows = _rrp_v151_safe_connection_rows(conn)
        for row in rows:
            try:
                if not _rrp_v151_is_false_negative_row(row, conn):
                    continue
                proof_id = row.get("proof_id")
                a = row.get("node_a")
                b = row.get("node_b")
                if proof_id:
                    cur = conn.execute("DELETE FROM connection_proofs WHERE proof_id=?", (proof_id,))
                else:
                    cur = conn.execute(
                        "DELETE FROM connection_proofs WHERE node_a=? AND node_b=? AND COALESCE(confidence,0)<=0.05",
                        (a, b),
                    )
                removed += int(cur.rowcount or 0)
            except Exception:
                continue
        if removed:
            conn.commit()
    except Exception:
        pass
    return removed


# Sobrescribir limpiadores anteriores con el limpiador robusto.
def _rrp_v149_cleanup_doc_pending_false_negatives(conn: Optional[sqlite3.Connection]) -> int:
    return _rrp_v151_cleanup_all_fixed_false_negatives(conn)


def _rrp_v150_cleanup_fixed_node_false_negatives(conn: Optional[sqlite3.Connection]) -> int:
    return _rrp_v151_cleanup_all_fixed_false_negatives(conn)


# Reforzar validación individual: estas líneas no se guardan como 0%.
_ORIG_VALIDATE_CONNECTION_ONCHAIN_V151_PRE = validate_connection_onchain

def validate_connection_onchain(node_a: str, node_b: str, conn: sqlite3.Connection, force: bool = False) -> Dict[str, Any]:
    try:
        if _rrp_v151_is_fixed_or_watch_related_pair(node_a, node_b, conn) and not force:
            return _rrp_v149_doc_pending_result(node_a, node_b, conn)
    except Exception:
        pass
    res = _ORIG_VALIDATE_CONNECTION_ONCHAIN_V151_PRE(node_a, node_b, conn, force=force)
    try:
        _rrp_v151_cleanup_all_fixed_false_negatives(conn)
    except Exception:
        pass
    return res


