def _rrp_v195_alias_to_anchor(text: Any) -> str:
    blob = _rrp_v195_norm(text)
    if not blob:
        return ""
    # Primero canónico exacto por alias completo.
    for canon, aliases in RRP_V195_ECOSYSTEM_ALIASES.items():
        all_aliases = [canon] + list(aliases or [])
        for a in all_aliases:
            ak = _rrp_v195_norm(a)
            if ak and (blob == ak or ak in blob):
                return canon
    return ""


def _rrp_v195_result_blob(result: Optional[Dict[str, Any]]) -> str:
    if not isinstance(result, dict):
        return ""
    parts: List[str] = []
    for k in ("institution", "query", "summary", "entity_type", "layer"):
        parts.append(str(result.get(k) or ""))
    for key in ("evidence_items", "route_decisions", "derived_nodes", "sources"):
        arr = result.get(key) or []
        if isinstance(arr, list):
            for item in arr[:80]:
                if isinstance(item, dict):
                    parts.extend(str(v or "") for v in item.values())
                else:
                    parts.append(str(item or ""))
    return "\n".join(parts)


def _rrp_v195_urls_from_result(result: Optional[Dict[str, Any]]) -> List[str]:
    urls: List[str] = []
    try:
        blob_items = []
        if isinstance(result, dict):
            for key in ("evidence_items", "sources", "route_decisions"):
                val = result.get(key) or []
                if isinstance(val, list):
                    blob_items.extend(val)
            blob_items.append(result)
        for item in blob_items:
            if isinstance(item, dict):
                for k in ("url", "source", "href", "link"):
                    u = str(item.get(k) or "").strip()
                    if u.startswith("http"):
                        urls.append(u)
                for k in ("urls", "source_urls"):
                    v = item.get(k)
                    if isinstance(v, list):
                        urls.extend(str(x).strip() for x in v if str(x).strip().startswith("http"))
                    elif isinstance(v, str):
                        try:
                            arr = json.loads(v)
                            if isinstance(arr, list):
                                urls.extend(str(x).strip() for x in arr if str(x).strip().startswith("http"))
                        except Exception:
                            for u in re.findall(r"https?://[^\s\]\)\}\"']+", v):
                                urls.append(u)
    except Exception:
        pass
    # limpiar https:/// generado por versiones anteriores
    clean=[]
    for u in urls:
        u=str(u or '').strip().replace('https:///', 'https://').replace('http:///', 'http://')
        if u.startswith('http') and u not in clean:
            clean.append(u)
    return clean[:25]


def _rrp_v195_entity_is_anchor(entity: Any) -> bool:
    e = _canonical_entity_name(entity) if callable(globals().get('_canonical_entity_name')) else str(entity or '').strip()
    return bool(_rrp_v195_alias_to_anchor(e))


def _rrp_v195_seed_anchor_network(conn: sqlite3.Connection) -> None:
    """Asegura una red mínima de anclas Ripple/XRPL sin dibujar clientes directos."""
    if conn is None:
        return
    try:
        # Núcleo Ripple -> XRPL
        _rrp_v194_insert_dynamic_route(conn, "Ripple Payments", "XRPL", "official_ripple_xrpl_anchor", 0.82,
            "Ancla documental del ecosistema: Ripple Payments/RippleNet puede encadenarse hacia XRPL como borde público. No atribuye actividad a clientes privados sin wallet/issuer.",
            ["https://ripple.com/solutions/cross-border-payments/"])
        # Features oficiales XRPL
        for src, conf, ev, url in [
            ("DEX/AMM", 0.86, "DEX/AMM es funcionalidad documentada del XRP Ledger: DEX/orderbook y AMM como zonas públicas vigilables.", "https://xrpl.org/docs/concepts/tokens/decentralized-exchange"),
            ("Trustlines", 0.84, "Trustlines/TrustSet/RippleState son mecanismos documentados del XRP Ledger para issued currencies.", "https://xrpl.org/docs/references/protocol/transactions/types/trustset"),
            ("Issued Currencies", 0.84, "Issued currencies/fungible tokens son funcionalidad documentada del XRP Ledger.", "https://xrpl.org/docs/concepts/tokens/fungible-tokens"),
            ("XRP", 0.92, "XRP es el activo nativo del XRP Ledger.", "https://xrpl.org/docs/concepts/introduction/xrp"),
        ]:
            _rrp_v194_insert_dynamic_route(conn, "XRPL", src, "official_xrpl_ecosystem_feature", conf, ev, [url])
        # Dependencias técnicas internas
        _rrp_v194_insert_dynamic_route(conn, "Issued Currencies", "Trustlines", "technical_protocol_dependency", 0.82,
            "La documentación del XRP Ledger vincula issued currencies/fungible tokens con trust lines. Dependencia técnica, no adopción institucional.",
            ["https://xrpl.org/docs/concepts/tokens/fungible-tokens", "https://xrpl.org/docs/references/protocol/transactions/types/trustset"])
        # RLUSD canónico si el código ya lo conoce
        _rrp_v194_insert_dynamic_route(conn, "RLUSD", "XRPL", "official_stablecoin_on_xrpl", 0.86,
            "RLUSD/Ripple USD tiene punto público observable en XRPL cuando aparece issuer/currency. No prueba adopción bancaria concreta.",
            ["https://docs.ripple.com/stablecoin"])
    except Exception:
        pass


def _rrp_v195_link_anchor_to_xrpl(conn: sqlite3.Connection, anchor: str) -> bool:
    anchor = _rrp_v195_alias_to_anchor(anchor) or _canonical_entity_name(anchor)
    if not anchor or anchor == "XRPL":
        return False
    hop_info = RRP_V195_ANCHOR_TO_XRPL_HOP.get(anchor)
    if not hop_info:
        return False
    hop, ev, conf = hop_info
    urls = []
    if anchor in {"DEX/AMM", "Trustlines", "Issued Currencies", "XRP", "RLUSD"}:
        # Para features/tokens sí se puede crear ruta técnica directa hacia XRPL.
        try:
            _rrp_v194_insert_dynamic_route(conn, anchor, hop, "documented_xrpl_ecosystem_anchor", conf, ev, urls)
        except Exception:
            pass
    else:
        # Para infraestructura Ripple, no siempre crear directo a XRPL; usar tramo al hop.
        try:
            _rrp_v194_insert_dynamic_route(conn, anchor, hop, "documented_ripple_infra_anchor", conf, ev, urls)
        except Exception:
            pass
    # Si el hop no es XRPL, asegurar que hop llega a XRPL por la red de anclas.
    try:
        if hop != "XRPL":
            _rrp_v195_link_anchor_to_xrpl(conn, hop)
    except Exception:
        pass
    return True


def _rrp_v195_link_entity_to_anchor(conn: sqlite3.Connection, entity: str, anchor: str, result: Optional[Dict[str, Any]] = None, confidence: float = 0.62) -> bool:
    entity = _canonical_entity_name(entity) if callable(globals().get('_canonical_entity_name')) else str(entity or '').strip()
    anchor = _rrp_v195_alias_to_anchor(anchor) or _canonical_entity_name(anchor)
    if not entity or not anchor or entity == anchor:
        return False
    # No convertir anchors en clientes de sí mismos.
    if _rrp_v195_alias_to_anchor(entity) == anchor:
        return False
    urls = _rrp_v195_urls_from_result(result)
    blob = _rrp_v195_result_blob(result)
    claim = f"La investigación detecta relación documental o contextual entre {entity} y {anchor}. Se encadena hacia XRPL solo a través del nodo intermedio documentado; no se inventa {entity} → XRPL directo."
    if blob:
        # Si hay un resumen útil, incorporarlo sin sobrecargar.
        claim += " Evidencia resumida: " + re.sub(r"\s+", " ", blob)[:650]
    try:
        _rrp_v195_seed_anchor_network(conn)
        _rrp_v195_link_anchor_to_xrpl(conn, anchor)
    except Exception:
        pass
    ok = False
    try:
        ok = bool(_rrp_v194_insert_dynamic_route(conn, entity, anchor, "documented_ecosystem_relation", confidence, claim, urls)) or ok
    except Exception:
        pass
    # Crear camino deductivo. Si anchor tiene hop directo a XRPL, usar anchor como public_hop.
    try:
        hop_info = RRP_V195_ANCHOR_TO_XRPL_HOP.get(anchor)
        if anchor == "XRPL":
            pass
        elif hop_info:
            hop = anchor
            _rrp_v194_insert_route_path(conn, entity, hop, "XRPL", min(confidence, 0.78),
                f"Camino deductivo del ecosistema v195: {entity} → {anchor} → XRPL. El primer tramo requiere documento/fuente; el borde XRPL se mide solo donde haya wallet, issuer, token, trustline, DEX/AMM o transacción verificable.",
                path_type="deductive_ripple_xrpl_ecosystem")
            ok = True
    except Exception:
        pass
    return ok


def _rrp_v195_detect_anchors_in_result(entity: str, result: Optional[Dict[str, Any]]) -> List[str]:
    blob = _rrp_v195_result_blob(result)
    anchors: List[str] = []
    if not blob:
        return anchors
    bnorm = _rrp_v195_norm(blob)
    ent_norm = _rrp_v195_norm(entity)
    # Requiere que aparezca la entidad o que el resultado sea de esa entidad para no mezclar fuentes ajenas.
    entity_present = bool(ent_norm and (ent_norm in bnorm or _rrp_v195_norm(_canonical_entity_name(entity)) in bnorm))
    if not entity_present:
        inst = ""
        try:
            inst = _rrp_v195_norm((result or {}).get("institution") or (result or {}).get("query") or "")
        except Exception:
            pass
        entity_present = bool(ent_norm and (ent_norm == inst or ent_norm in inst or inst in ent_norm))
    if not entity_present:
        return anchors
    for canon, aliases in RRP_V195_ECOSYSTEM_ALIASES.items():
        for a in [canon] + list(aliases or []):
            ak = _rrp_v195_norm(a)
            if ak and ak in bnorm:
                anchors.append(canon)
                break
    # Orden estable y sin duplicados.
    out=[]
    for a in anchors:
        if a not in out:
            out.append(a)
    return out


def _rrp_v195_anchor_seed_result(query: Any) -> Optional[Dict[str, Any]]:
    anchor = _rrp_v195_alias_to_anchor(query)
    if not anchor:
        return None
    # Si es Ripple core, mantener seed v193.
    if anchor == "Ripple Payments" and callable(globals().get("_rrp_v193_ripple_core_seed_result")):
        return _rrp_v193_ripple_core_seed_result(query)
    hop_info = RRP_V195_ANCHOR_TO_XRPL_HOP.get(anchor)
    derived = []
    route_decisions = []
    evidence_items = []
    sources = []
    conf = 0.70
    if hop_info:
        hop, ev, conf = hop_info
        route_decisions.append({"to": hop, "evidence_type": "documented_ecosystem_anchor", "confidence": conf, "claim": ev, "status": "documented", "draw_on_map": True})
        derived.append({"name": hop, "reason": f"Borde/ancla pública de {anchor}."})
        evidence_items.append({"title": f"{anchor} → {hop} · ancla del ecosistema", "evidence_type": "documented_ecosystem_anchor", "claim": ev, "url": "", "node_a": anchor, "node_b": hop})
    # Enlaces oficiales si son features XRPL conocidas.
    official_url = {
        "DEX/AMM": "https://xrpl.org/docs/concepts/tokens/decentralized-exchange",
        "Trustlines": "https://xrpl.org/docs/references/protocol/transactions/types/trustset",
        "Issued Currencies": "https://xrpl.org/docs/concepts/tokens/fungible-tokens",
        "RLUSD": "https://docs.ripple.com/stablecoin",
        "XRP": "https://xrpl.org/docs/concepts/introduction/xrp",
        "Ripple CBDC Platform": "https://ripple.com/solutions/central-bank-digital-currency/",
    }.get(anchor, "")
    if official_url:
        sources.append({"title": f"{anchor} official/source", "url": official_url, "type": "official_source"})
        if evidence_items:
            evidence_items[0]["url"] = official_url
    return {
        "institution": anchor,
        "query": str(query or anchor),
        "icon": "🔎",
        "entity_type": "Ripple/XRPL ecosystem anchor",
        "layer": "Ecosistema Ripple/XRPL",
        "connected": True,
        "confidence": conf,
        "summary": f"{anchor} se reconoce como nodo del ecosistema Ripple/XRPL. La búsqueda abre rutas documentales/deductivas conservadoras hacia XRPL cuando proceda, sin afirmar uso operativo directo por entidades privadas.",
        "evidence_items": evidence_items,
        "route_decisions": route_decisions,
        "derived_nodes": derived,
        "sources": sources,
        "_v195_ecosystem_seed": True,
    }


_ORIG_RRP_V156_RUN_AND_STORE_V195 = globals().get("_rrp_v156_run_and_store")
def _rrp_v156_run_and_store(conn: sqlite3.Connection, query: str, *, parent: str = "", force_online: bool = False, use_cache: bool = True, source: str = "initial") -> None:
    qraw = str(query or "").strip()
    if not qraw:
        return None
    # 0) Si la consulta ES un nodo del ecosistema, sembrar resultado antes/después de la búsqueda normal.
    seed = _rrp_v195_anchor_seed_result(qraw)
    if seed:
        try:
            flow = list(st.session_state.get("rrp_simple_flow", []) or [])
            # No duplicar el mismo seed muchas veces en la vista.
            sk = _canonical_entity_key(seed.get("institution") or qraw)
            if not any(_canonical_entity_key((x or {}).get("institution") or (x or {}).get("query") or "") == sk and (x or {}).get("_v195_ecosystem_seed") for x in flow if isinstance(x, dict)):
                seed["source"] = source
                seed["parent"] = parent
                flow.append(seed)
                st.session_state["rrp_simple_flow"] = flow[-80:]
        except Exception:
            pass
        try:
            _rrp_v193_persist_result_everywhere(conn, seed, parent=parent)
        except Exception:
            pass
        try:
            _rrp_v195_seed_anchor_network(conn)
            _rrp_v195_link_anchor_to_xrpl(conn, seed.get("institution") or qraw)
        except Exception:
            pass
    # 1) Ejecutar el buscador existente para fuentes reales.
    if callable(_ORIG_RRP_V156_RUN_AND_STORE_V195):
        _ORIG_RRP_V156_RUN_AND_STORE_V195(conn, qraw, parent=parent, force_online=force_online, use_cache=use_cache, source=source)
    # 2) Revisar el resultado y crear vínculos a cualquier infraestructura Ripple/XRPL detectada, no solo Ripple Payments.
    try:
        res = _rrp_v194_latest_result_for_query(qraw)
    except Exception:
        res = None
    made = False
    try:
        anchors = _rrp_v195_detect_anchors_in_result(qraw, res)
        # Si el propio query es una entidad conocida de hints v194, mantener la ruta universal v194.
        for a in anchors[:8]:
            if a != _rrp_v195_alias_to_anchor(qraw):
                made = bool(_rrp_v195_link_entity_to_anchor(conn, qraw, a, result=res, confidence=0.64)) or made
    except Exception:
        pass
    # 3) Si no encontró nada y es una búsqueda normal, expandir con todo el ecosistema, no solo Ripple Payments.
    try:
        guard = set(st.session_state.get("rrp_v195_expanded_done", set()) or set())
    except Exception:
        guard = set()
    gk = _canonical_entity_key(qraw)
    try:
        rcount = _rrp_v194_route_count(res)
    except Exception:
        rcount = 0
    if not made and not seed and rcount == 0 and gk not in guard and source in {"initial", "cascade"}:
        guard.add(gk)
        st.session_state["rrp_v195_expanded_done"] = guard
        expanded = (
            f'{qraw} Ripple RippleNet Ripple Payments ODL On-Demand Liquidity XRP Ledger XRPL XRP RLUSD '
            f'Ripple Treasury GTreasury Metaco Custody Hidden Road Prime Ripple CBDC Platform Trustlines DEX AMM issued currencies official source'
        )
        try:
            if callable(_ORIG_RRP_V156_RUN_AND_STORE_V195):
                _ORIG_RRP_V156_RUN_AND_STORE_V195(conn, expanded, parent=parent, force_online=True, use_cache=False, source=source)
            res2 = _rrp_v194_latest_result_for_query(qraw) or _rrp_v194_latest_result_for_query(expanded)
            anchors2 = _rrp_v195_detect_anchors_in_result(qraw, res2)
            for a in anchors2[:8]:
                if a != _rrp_v195_alias_to_anchor(qraw):
                    _rrp_v195_link_entity_to_anchor(conn, qraw, a, result=res2, confidence=0.62)
        except Exception:
            pass
    # 4) Sembrar vigilancia y Route A-B desde rutas/caminos generados.
    try:
        _rrp_v195_seed_anchor_network(conn)
        if callable(globals().get("_rrp_v171_seed_watch_targets_from_routes")):
            _rrp_v171_seed_watch_targets_from_routes(conn)
        if callable(globals().get("_rrp_v175_persist_watch_paths")):
            _rrp_v175_persist_watch_paths(conn)
        if callable(globals().get("_rrp_v184_seed_live_watch_from_paths")):
            _rrp_v184_seed_live_watch_from_paths(conn)
    except Exception:
        pass
    try:
        conn.commit()
    except Exception:
        pass
    return None


def _rrp_v195_backfill_all_ecosystem_paths(conn: sqlite3.Connection, limit: int = 1200) -> int:
    """Backfill ligero: cualquier ruta hacia un anchor Ripple/XRPL genera camino deductivo a XRPL."""
    made = 0
    try:
        _rrp_v195_seed_anchor_network(conn)
        if not _rrp_v156_table_exists(conn, "dynamic_routes"):
            return 0
        cols = _rrp_v194_table_cols(conn, "dynamic_routes")
        src_col = "src" if "src" in cols else ("source" if "source" in cols else "from_node")
        dst_col = "dst" if "dst" in cols else ("target" if "target" in cols else "to_node")
        kind_col = "kind" if "kind" in cols else ("route_type" if "route_type" in cols else "type")
        conf_col = "confidence" if "confidence" in cols else None
        rows = conn.execute(f"SELECT {src_col},{dst_col},{kind_col}{','+conf_col if conf_col else ''} FROM dynamic_routes LIMIT ?", (int(limit),)).fetchall()
        for row in rows:
            src, dst, kind = str(row[0] or ""), str(row[1] or ""), str(row[2] or "")
            conf = float(row[3] or 0.62) if conf_col and len(row) > 3 else 0.62
            s_anchor = _rrp_v195_alias_to_anchor(src)
            d_anchor = _rrp_v195_alias_to_anchor(dst)
            if d_anchor and not s_anchor and d_anchor != "XRPL":
                if _rrp_v195_link_entity_to_anchor(conn, src, d_anchor, confidence=min(conf, 0.78)):
                    made += 1
            elif s_anchor and not d_anchor and s_anchor != "XRPL":
                if _rrp_v195_link_entity_to_anchor(conn, dst, s_anchor, confidence=min(conf, 0.78)):
                    made += 1
            elif s_anchor:
                _rrp_v195_link_anchor_to_xrpl(conn, s_anchor)
            elif d_anchor:
                _rrp_v195_link_anchor_to_xrpl(conn, d_anchor)
        conn.commit()
    except Exception:
        pass
    return made

try:
    _c = get_conn()
    _rrp_v195_seed_anchor_network(_c)
    # Backfill pequeño para no penalizar carga rápida.
    _rrp_v195_backfill_all_ecosystem_paths(_c, limit=300)
except Exception:
    pass



# =============================================================================
# v196 · MAP HOVER CONFIDENCE CROSSCHECK FIX
# -----------------------------------------------------------------------------
# Problema:
# - El mapa podía decir "Verificado / con prueba" en el hover del nodo pero mostrar
#   "Confianza: 0%" porque estaba leyendo meta.confidence de dynamic_nodes, no la
#   confianza real guardada en connection_proofs/dynamic_routes/route_paths/watch.
# - Las líneas también podían aparecer documentadas sin enseñar la confianza real
#   de la ruta guardada.
# Solución:
# - Al renderizar el mapa, cruzar el hover con la evidencia real de SQLite.
# - Si una línea/nodo tiene pruebas o rutas guardadas, mostrar "Confianza documental".
# - Si algo está verificado pero no tiene score recalculable, no mostrar 0%; mostrar
#   "pendiente de recalcular".
# =============================================================================
try:
    VERSION = "Route Path Intelligence v6.2.3 PRO — Universal Ripple/XRPL Ecosystem · v196"
    BUILD_ID = "v196_2026_05_14_MAP_HOVER_CONFIDENCE_CROSSCHECK_FIX"
    BUILD_NOTE = "Hover del mapa cruza pruebas/rutas: verificado no puede salir con confianza 0%."
except Exception:
    pass


def _rrp_v196_pair_key(a: Any, b: Any) -> str:
    try:
        return _canonical_pair_key(a, b)
    except Exception:
        aa = _norm_key(a)
        bb = _norm_key(b)
        return "|".join(sorted([aa, bb]))


def _rrp_v196_pair_display_key(a: Any, b: Any) -> str:
    return f"{str(a or '').strip()}|{str(b or '').strip()}"


def _rrp_v196_conf_maps(conn: Optional[sqlite3.Connection]) -> Tuple[Dict[str, float], Dict[str, float], Dict[str, List[str]]]:
    """Devuelve (pair_conf, node_conf, pair_urls) usando todas las tablas relevantes.

    pair_conf usa claves canónicas y direccionales para que A↔B se reconozca desde
    ambos extremos. node_conf es el máximo score relacionado con el nodo.
    """
    pair_conf: Dict[str, float] = {}
    node_conf: Dict[str, float] = {}
    pair_urls: Dict[str, List[str]] = {}
    if conn is None:
        return pair_conf, node_conf, pair_urls

    def add(a: Any, b: Any, conf: Any, urls: Optional[List[str]] = None) -> None:
        a = str(a or '').strip(); b = str(b or '').strip()
        if not a or not b:
            return
        try:
            c = float(conf or 0.0)
        except Exception:
            c = 0.0
        if c <= 0:
            return
        keys = [_rrp_v196_pair_key(a, b), _rrp_v196_pair_display_key(a, b), _rrp_v196_pair_display_key(b, a)]
        for k in keys:
            pair_conf[k] = max(float(pair_conf.get(k, 0.0) or 0.0), c)
            if urls:
                old = pair_urls.get(k, [])
                for u in urls:
                    u = str(u or '').strip().replace('https:///', 'https://').replace('http:///', 'http://')
                    if u.startswith('http') and u not in old:
                        old.append(u)
                pair_urls[k] = old[:8]
        for n in (a, b):
            node_conf[n] = max(float(node_conf.get(n, 0.0) or 0.0), c)
            try:
                canon = _canonical_entity_name(n)
                if canon:
                    node_conf[canon] = max(float(node_conf.get(canon, 0.0) or 0.0), c)
            except Exception:
                pass

    try:
        rows = conn.execute("SELECT node_a,node_b,proof_data,confidence FROM connection_proofs WHERE COALESCE(sanitizer_status,'active')!='quarantined'").fetchall()
        for a,b,pdata,conf in rows:
            urls=[]; c=float(conf or 0.0)
            try:
                pj=json.loads(pdata or '{}')
                c=max(c, float(pj.get('calibrated_score') or pj.get('confidence') or 0.0))
                for pr in pj.get('proofs') or []:
                    if isinstance(pr, dict):
                        u=str(pr.get('url') or pr.get('source_url') or '').strip()
                        if u.startswith('http') and u not in urls:
                            urls.append(u)
                for u in pj.get('source_urls') or []:
                    if str(u).startswith('http') and str(u) not in urls:
                        urls.append(str(u))
            except Exception:
                pass
            add(a,b,c,urls)
    except Exception:
        pass

    try:
        if _rrp_v156_table_exists(conn, 'dynamic_routes') if callable(globals().get('_rrp_v156_table_exists')) else True:
            for a,b,conf,urls in conn.execute("SELECT src,dst,confidence,source_urls FROM dynamic_routes WHERE COALESCE(sanitizer_status,'active')!='quarantined'").fetchall():
                us=[]
                for u in re.findall(r"https?://[^\s,;<>'\"\)\]]+", str(urls or '').replace('https:///', 'https://')):
                    u=u.strip().rstrip('.,)];')
                    if u not in us:
                        us.append(u)
                add(a,b,conf,us)
    except Exception:
        pass

    try:
        if _rrp_v156_table_exists(conn, 'route_paths') if callable(globals().get('_rrp_v156_table_exists')) else True:
            for a,h,b,conf in conn.execute("SELECT origin,public_hop,destination,confidence FROM route_paths").fetchall():
                # El path A→hop→B no es una línea directa A→B; aun así da confianza al nodo y a cada tramo visible.
                add(a,h,conf,[])
                add(h,b,conf,[])
    except Exception:
        pass

    try:
        if _rrp_v156_table_exists(conn, 'onchain_watch_targets') if callable(globals().get('_rrp_v156_table_exists')) else True:
            for a,b,subj,conf,last_sig in conn.execute("SELECT src,dst,subject,confidence,last_signal FROM onchain_watch_targets WHERE COALESCE(status,'active')!='ignore'").fetchall():
                c=max(float(conf or 0.0), float(last_sig or 0.0))
                add(a,b,c,[])
                if subj:
                    add(a,subj,c,[])
                    add(subj,b,c,[])
    except Exception:
        pass

    return pair_conf, node_conf, pair_urls


def _rrp_v196_line_conf(pair_conf: Dict[str, float], src: str, dst: str) -> float:
    return float(pair_conf.get(_rrp_v196_pair_key(src, dst)) or pair_conf.get(_rrp_v196_pair_display_key(src, dst)) or pair_conf.get(_rrp_v196_pair_display_key(dst, src)) or 0.0)


def _rrp_v196_fix_hovertexts(fig: go.Figure, conn: Optional[sqlite3.Connection]) -> go.Figure:
    pair_conf, node_conf, pair_urls = _rrp_v196_conf_maps(conn)

    def clean_name(x: str) -> str:
        try:
            return html.unescape(re.sub(r"<[^>]+>", "", str(x or ''))).strip()
        except Exception:
            return str(x or '').strip()

    def node_score(name: str) -> float:
        vals = [node_conf.get(name, 0.0)]
        try:
            vals.append(node_conf.get(_canonical_entity_name(name), 0.0))
        except Exception:
            pass
        return max(float(v or 0.0) for v in vals)

    try:
        for tr in list(fig.data or []):
            hv = getattr(tr, 'hovertext', None)
            if hv is None:
                continue
            # Node trace: hovertext is list/tuple.
            if isinstance(hv, (list, tuple)):
                new=[]
                for item in hv:
                    s=str(item or '')
                    m=re.search(r"<b>(.*?)</b>", s, flags=re.I|re.S)
                    if not m:
                        new.append(s); continue
                    nm=clean_name(m.group(1))
                    score=node_score(nm)
                    if score > 0:
                        # Sustituye cualquier Confianza: 0% o Confianza: X% por confianza cruzada real.
                        if re.search(r"Confianza:\s*\d+%", s):
                            s=re.sub(r"Confianza:\s*\d+%", f"Confianza documental cruzada: {score*100:.0f}%", s)
                        elif "Confianza documental cruzada" not in s:
                            s=s.replace("<i>Click", f"Confianza documental cruzada: {score*100:.0f}%<br><i>Click")
                    else:
                        # Si está verificado pero no hay score, no mostrar 0%: eso parece falso negativo.
                        if "Verificado / con prueba" in s and re.search(r"Confianza:\s*0%", s):
                            s=re.sub(r"Confianza:\s*0%", "Confianza: prueba guardada · score pendiente de recalcular", s)
                    new.append(s)
                tr.hovertext = tuple(new) if isinstance(hv, tuple) else new
                continue

            # Line trace: hovertext is string.
            s=str(hv or '')
            m=re.search(r"<b>(.*?)\s*(?:→|&rarr;|-&gt;)\s*(.*?)</b>", s, flags=re.I|re.S)
            if not m:
                continue
            src=clean_name(m.group(1)); dst=clean_name(m.group(2))
            conf=_rrp_v196_line_conf(pair_conf, src, dst)
            if conf > 0:
                if re.search(r"Confianza(?: documental)?[^<]*:\s*\d+%", s):
                    s=re.sub(r"Confianza(?: documental)?[^<]*:\s*\d+%", f"Confianza documental cruzada: {conf*100:.0f}%", s)
                else:
                    s += f"<br>Confianza documental cruzada: {conf*100:.0f}%"
                urls = pair_urls.get(_rrp_v196_pair_key(src,dst)) or pair_urls.get(_rrp_v196_pair_display_key(src,dst)) or []
                if urls and "Fuente 1" not in s:
                    s += "<br>Fuentes: " + " · ".join([f"<a href='{html.escape(u)}' target='_blank'>Fuente {i+1}</a>" for i,u in enumerate(urls[:3])])
                if "Estado visual: documented" in s and "Verificado / documentado" not in s:
                    s = s.replace("Estado visual: documented", "Estado visual: Verificado / documentado")
            else:
                if "Verificado" in s and re.search(r"Confianza:\s*0%", s):
                    s=re.sub(r"Confianza:\s*0%", "Confianza: prueba guardada · score pendiente de recalcular", s)
            tr.hovertext=s
    except Exception:
        pass
    return fig


_ORIG_MAKE_MAP_V196 = globals().get('make_map')
def make_map(*args, **kwargs):
    conn = kwargs.get('conn')
    if conn is None:
        # En la firma actual conn es el tercer/ cuarto argumento nombrado; si viene posicional, buscar sqlite.Connection.
        for a in args:
            try:
                if isinstance(a, sqlite3.Connection):
                    conn = a; break
            except Exception:
                pass
    fig = _ORIG_MAKE_MAP_V196(*args, **kwargs) if callable(_ORIG_MAKE_MAP_V196) else go.Figure()
    return _rrp_v196_fix_hovertexts(fig, conn)



# =============================================================================
# v197 · Route A→B live volume metrics
# -----------------------------------------------------------------------------
# Motivo:
# Una ruta podía mostrar "Señal vivo 33%" pero la ficha no enseñaba los números
# que alimentaban esa señal: volumen RLUSD/activo, XRP nativo, pagos, trustlines,
# ofertas DEX, pools AMM, cuentas únicas, grandes transferencias, etc.
# Esta capa separa definitivamente:
#   - confianza documental
#   - señal on-chain normalizada
#   - métricas brutas observadas
# =============================================================================
try:
    VERSION = "Route Path Intelligence v6.2.3 PRO — Universal Ripple/XRPL Ecosystem · v197"
    BUILD_ID = "v197_2026_05_14_ROUTE_AB_LIVE_VOLUME_METRICS_FIX"
    BUILD_NOTE = "Route A→B muestra métricas vivas reales: volúmenes, pagos, trustlines, DEX/AMM, cuentas y grandes transferencias."
except Exception:
    pass


def _rrp_v197_num(x: Any, decimals: int = 2) -> float:
    try:
        if x is None or x == "":
            return 0.0
        return float(x)
    except Exception:
        return 0.0


def _rrp_v197_fmt_amount(x: Any, suffix: str = "", decimals: int = 2) -> str:
    v = _rrp_v197_num(x)
    try:
        if abs(v) >= 1_000_000_000:
            s = f"{v/1_000_000_000:.2f}B"
        elif abs(v) >= 1_000_000:
            s = f"{v/1_000_000:.2f}M"
        elif abs(v) >= 1_000:
            s = f"{v:,.0f}"
        else:
            s = f"{v:,.{decimals}f}"
        return (s + (" " + suffix if suffix else "")).strip()
    except Exception:
        return f"0 {suffix}".strip()


def _rrp_v197_extract_native_xrp_from_tx(tx: Dict[str, Any]) -> float:
    """Suma XRP nativo entregado en una TX si existe. IOUs no se convierten a XRP."""
    try:
        meta = tx.get("meta") or tx.get("metaData") or {}
        field = _delivered_amount_field(tx, meta) if callable(globals().get("_delivered_amount_field")) else tx.get("Amount")
        if isinstance(field, str):
            return max(0.0, min(float(int(field) / 1_000_000), float(globals().get("_MAX_TX_XRP", 1_000_000_000))))
    except Exception:
        return 0.0
    return 0.0


def _rrp_v197_iou_profile_from_tx(tx: Dict[str, Any]) -> Tuple[str, float]:
    """Devuelve (currency, value) para IOU entregado si lo hay."""
    try:
        meta = tx.get("meta") or tx.get("metaData") or {}
        field = _delivered_amount_field(tx, meta) if callable(globals().get("_delivered_amount_field")) else tx.get("Amount")
        if isinstance(field, dict):
            cur = str(field.get("currency") or "IOU")
            val = abs(float(field.get("value") or 0.0))
            return cur, val
    except Exception:
        pass
    return "", 0.0


_ORIG_RRP_V171_FETCH_LIVE_WATCH_METRICS_V197 = globals().get("_rrp_v171_fetch_live_watch_metrics")
def _rrp_v171_fetch_live_watch_metrics() -> Dict[str, Any]:
    """Amplía el snapshot vivo con métricas brutas que la ficha A→B puede mostrar."""
    metrics = _ORIG_RRP_V171_FETCH_LIVE_WATCH_METRICS_V197() if callable(_ORIG_RRP_V171_FETCH_LIVE_WATCH_METRICS_V197) else {}
    if not isinstance(metrics, dict):
        metrics = {}

    # Añadir métricas de XRP nativo/IOUs desde el issuer observable cuando sea posible.
    # No atribuye esas métricas a bancos o privados: solo al borde público observado.
    try:
        txs = fetch_issuer_transactions(limit_pages=1, per_page=120) if callable(globals().get("fetch_issuer_transactions")) else []
        xrp_volume = 0.0
        xrp_payments = 0
        xrp_max = 0.0
        iou_by_cur: Dict[str, float] = {}
        payment_count = 0
        for tx in txs or []:
            try:
                cls = classify_tx(tx) if callable(globals().get("classify_tx")) else {}
                is_payment = bool(cls.get("payment", 0)) if isinstance(cls, dict) else str(tx.get("TransactionType")) == "Payment"
                if is_payment:
                    payment_count += 1
                xv = _rrp_v197_extract_native_xrp_from_tx(tx)
                if xv > 0:
                    xrp_volume += xv
                    xrp_payments += 1
                    xrp_max = max(xrp_max, xv)
                cur, val = _rrp_v197_iou_profile_from_tx(tx)
                if cur and val > 0:
                    iou_by_cur[cur] = iou_by_cur.get(cur, 0.0) + val
            except Exception:
                continue
        metrics.setdefault("xrp_payment_volume", float(xrp_volume))
        metrics.setdefault("xrp_payment_count", int(xrp_payments))
        metrics.setdefault("xrp_max_payment", float(xrp_max))
        metrics.setdefault("iou_volume_by_currency", iou_by_cur)
        metrics.setdefault("payment_count", max(int(metrics.get("payment_count") or 0), int(payment_count)))
    except Exception as exc:
        metrics.setdefault("xrp_volume_error", str(exc))
    return metrics


def _rrp_v197_metric_bits(metrics: Dict[str, Any], watch_type: str = "") -> List[str]:
    if not isinstance(metrics, dict):
        return []
    wt = str(watch_type or "").lower()
    bits: List[str] = []

    def add(label: str, value: Any, suffix: str = "", decimals: int = 2, show_zero: bool = False):
        v = _rrp_v197_num(value)
        if v or show_zero:
            bits.append(f"{label}: {_rrp_v197_fmt_amount(v, suffix, decimals)}")

    # Métricas comunes / pagos.
    add("Pagos observados", metrics.get("payment_count"), "", 0)
    add("Cuentas únicas", metrics.get("rlusd_unique_accounts"), "", 0)
    add("Grandes transferencias", metrics.get("rlusd_large_count"), "", 0)

    # Volúmenes. XRP nativo separado de IOUs.
    add("Volumen XRP nativo", metrics.get("xrp_payment_volume"), "XRP", 2)
    add("Mayor pago XRP", metrics.get("xrp_max_payment"), "XRP", 2)
    add("Volumen RLUSD", metrics.get("rlusd_volume"), "RLUSD", 2)

    # Otros IOUs detectados si existen.
    ious = metrics.get("iou_volume_by_currency") or {}
    if isinstance(ious, dict):
        for cur, val in list(ious.items())[:5]:
            if str(cur).upper() != "RLUSD" and _rrp_v197_num(val) > 0:
                bits.append(f"Volumen {str(cur)[:12]}: {_rrp_v197_fmt_amount(val, str(cur)[:12], 2)}")

    # Trustlines / issued currencies.
    add("TrustSet", metrics.get("trustline_count"), "", 0)
    add("RippleState", metrics.get("ripple_state_events"), "", 0)

    # DEX / AMM / liquidez.
    add("Ofertas DEX", metrics.get("dex_offer_count") or metrics.get("offer_count"), "", 0)
    add("Pools AMM", metrics.get("amm_pool_count"), "", 0)
    add("AMM TX", metrics.get("amm_tx_count"), "", 0)
    add("Profundidad book", metrics.get("book_depth_xrp"), "XRP", 0)
    add("TVL AMM aprox.", metrics.get("amm_tvl_xrp"), "XRP", 0)

    # Si hay señal pero pocas métricas, explicar qué falta.
    if not bits:
        bits.append("Sin métricas brutas todavía: ejecuta Vigilar/Actualizar XRPL para llenar volumen, pagos y cuentas.")
    return bits


def _rrp_v197_live_metrics_block_from_signal_json(signal_json: Any, fallback_summary: str = "", watch_type: str = "") -> str:
    try:
        sj = json.loads(signal_json or "{}") if isinstance(signal_json, str) else (signal_json or {})
    except Exception:
        sj = {}
    metrics = sj.get("metrics") if isinstance(sj, dict) else {}
    observed_at = sj.get("observed_at") if isinstance(sj, dict) else ""
    bits = _rrp_v197_metric_bits(metrics or {}, watch_type)
    prefix = "📊 Métricas vivas del borde público observado"
    if observed_at:
        prefix += f" ({str(observed_at)[:19]})"
    txt = prefix + ": " + " · ".join(bits)
    if fallback_summary:
        txt += " · Resumen scanner: " + str(fallback_summary)[:280]
    return txt[:1400]


_ORIG_RRP_V175_ROUTE_PATH_ROWS_FROM_WATCH_V197 = globals().get("_rrp_v175_route_path_rows_from_watch")
def _rrp_v175_route_path_rows_from_watch(conn: sqlite3.Connection) -> List[Dict[str, Any]]:
    rows = _ORIG_RRP_V175_ROUTE_PATH_ROWS_FROM_WATCH_V197(conn) if callable(_ORIG_RRP_V175_ROUTE_PATH_ROWS_FROM_WATCH_V197) else []
    if not rows:
        return rows
    # Indexar señales recientes por target_id.
    sigs: Dict[str, Tuple[str, str, str, float]] = {}
    try:
        _rrp_v171_ensure_watch_tables(conn)
        q = """
            SELECT t.target_id, t.watch_type, t.last_summary, s.signal_json, COALESCE(s.observed_at,t.last_checked,''), COALESCE(t.last_signal,0)
            FROM onchain_watch_targets t
            LEFT JOIN onchain_watch_signals s ON s.signal_id=(
                SELECT signal_id FROM onchain_watch_signals ss WHERE ss.target_id=t.target_id ORDER BY observed_at DESC LIMIT 1
            )
        """
        for tid, wt, last_summary, sj, obs, sig in conn.execute(q).fetchall():
            sigs[str(tid or "")] = (str(wt or ""), str(last_summary or ""), str(sj or "{}"), float(sig or 0.0))
    except Exception:
        sigs = {}

    out: List[Dict[str, Any]] = []
    for r in rows:
        rr = dict(r)
        tid = str(rr.get("watch_target_id") or "")
        wt, summary, sj, sig = sigs.get(tid, ("", "", "{}", float(rr.get("live_signal") or 0.0)))
        block = _rrp_v197_live_metrics_block_from_signal_json(sj, summary, wt)
        # Evitar duplicar el mismo bloque si la fila ya venía de otro override.
        for col in ("evidence", "explanation", "deduction_note"):
            cur = str(rr.get(col) or "")
            if "📊 Métricas vivas" not in cur:
                rr[col] = (cur + "\n" + block).strip()[:2500]
        out.append(rr)
    return out


